// 项目实战“复刻面试自习室”第 15 关：AI 老师对话（多轮追问、保存历史、每日次数）。
// 学习卡片由 .sites-runtime/cards/pj-chat-*.mjs 生成（node .sites-runtime/lessons.mjs apply …），题目直接写在这里。
import type {AiLevel} from '../journey';

export const pjChat:AiLevel={id:'pj-chat',title:'AI 老师：多轮对话和次数限制',summary:'让 AI 老师能接着追问：每次把历史一起发给模型，对话存进数据库可查看和删除，每人每天限制提问次数，失败不扣次数',lessons:[
  {title:'这一关做什么：能追问的 AI 老师',body:'第 14 关的 AI 只能“问一句答一句”：评分、讲解都是一次性的，问完就忘。真正的面试自习室里，AI 老师可以接着追问：“能举个例子吗？”“那和 B 有什么区别？”，刷新页面、换台电脑，之前的对话还在。\n这一关做三件事：\n一、多轮对话：追问时 AI 记得之前聊过什么；\n二、保存对话：对话存进数据库，可以查看历史、接着问、删除；\n三、每日次数限制：每人每天最多问几次，防止大模型的费用失控。\n接口一共五个，全部需要登录：开新对话、追问、对话列表、对话详情、删除对话。'},
  {title:'模型其实不记得你：多轮对话是“每次重发”',body:'很多人以为大模型会记住和你的聊天。其实不会：每次请求都是独立的，模型只看得到这一次请求里的 messages。\n那 ChatGPT 是怎么“记得”的？答案是：每次提问，程序都把之前的对话一起发过去。比如第三次提问时，messages 是：\n系统提示词 → 第一问 → 第一次的回答 → 第二问 → 第二次的回答 → 第三问\n模型读完整段，才知道“它”指的是什么。\n所以“记住对话”是我们后端的工作：把每一问一答存进数据库，下次追问时按顺序取出来，拼在新问题的前面。'},
  {title:'对话越长越贵：只带最近几轮',body:'大模型按 token 收费，发过去的内容越多越贵，也越慢。如果一段对话聊了 50 轮，每次追问都把 100 条消息全发过去，费用会越来越高。\n常见的做法是只带最近几轮。这一关规定：追问时最多带最近 10 条消息（5 轮问答）。更早的内容模型就“忘了”，对初学者答疑来说一般够用。\n更讲究的做法还有：把很早的对话让模型先总结成一小段摘要再带上，或者只挑和新问题相关的旧消息。这些是优化，先把最简单的做对。\n另外，系统提示词每次都要带上，而且放在最前面：里面有 AI 老师的角色设定，以及这道题的题目和参考答案。'},
  {title:'三张表：对话、消息、次数',body:'一、chats：一段对话一行。记着是谁的（user_id）、针对哪道题（question_id，可以为空）、标题、最后提问时间；\n二、chat_messages：对话里的每一句话一行。role 是 user 或 assistant，正好对应发给模型的 messages；\n三、chat_usage：每人每天一行，count 是今天问了几次。\n为什么次数不直接数消息条数？因为用户可以删除对话，删了再数，次数就“回来了”。单独一张表记次数，删对话不影响它。'},
  {title:'每日次数：检查和加一必须是一步',body:'最直接的写法是：先查今天问了几次，没到上限就加一。但两个请求同时到达时会出问题：\n请求 A 查到 19 次（上限 20），请求 B 也查到 19 次；\nA 加一变 20，B 也加一变 21。超限了。\n解决办法是让“检查”和“加一”在一条 SQL 里完成：\nINSERT … VALUES (用户, 今天, 1) ON CONFLICT (user_id, day) DO UPDATE SET count = count + 1 WHERE count < 上限 RETURNING count\n数据库保证这一条语句不会被别的请求插进来。到了上限时它一行都不改，也就拿不到返回值，程序据此返回 429（请求太多）。\n还有一个细节：大模型调用失败时，要把这一次退回去，不能让用户为失败的请求买单。'},
  {title:'对话接口约定',body:'五个接口都需要登录，没登录返回 401。对话不是自己的，一律当作不存在（404），不透露它是否存在。',code:`POST   /api/chats                {"questionId": 1, "message": "defer 是什么时候执行的？"}
→ 201  {"chatId": 7, "reply": "……", "remaining": 19}

POST   /api/chats/7/messages     {"message": "能举个例子吗"}
→ 200  {"chatId": 7, "reply": "……", "remaining": 18}

GET    /api/chats                → 200 [{"id": 7, "title": "defer 是什么时候执行的？", "questionId": 1, "updatedAt": "…", "messages": 4}]
GET    /api/chats/7              → 200 {"id": 7, "questionId": 1, "title": "…", "messages": [{"role": "user", "content": "…", "createdAt": "…"}, …]}
DELETE /api/chats/7              → 204

错误：400 消息为空或超过 1000 个字 · 404 对话或题目不存在 · 429 今天的次数用完了
      502 AI 服务出错（不扣次数、不保存）· 503 AI 还没有配置`,explain:[{at:'POST   /api/chats ',to:'→ 201  {"chatId": 7, "reply": "……", "remaining": 19}',text:'开一段新对话。questionId 可以不传，表示不针对具体题目。返回对话编号、AI 的回答和今天还能问几次。'},{at:'POST   /api/chats/7/messages',to:'→ 200  {"chatId": 7, "reply": "……", "remaining": 18}',text:'在已有对话里追问，返回格式和开新对话一样。'},{at:'GET    /api/chats ',text:'我的对话列表，最近问过的在前，messages 是消息条数。'},{at:'GET    /api/chats/7 ',to:'DELETE /api/chats/7 ',text:'某段对话的全部消息（按先后顺序），以及删除对话。'},{at:'错误：400',to:'502 AI 服务出错（不扣次数、不保存）· 503 AI 还没有配置',text:'各种错误的状态码。注意 502：AI 出错时这句话不保存进对话，次数也退回去。'}]},
  {title:'任务一：多条消息的客户端和对话数据访问层',body:'先把第 14 关的大模型客户端改成能发“一整段对话”，再写数据访问层：三张表，以及查对话、存一问一答、占用和退回次数、删除对话这几个函数。',variants:{go:{practice:{steps:['打开 internal/ai/client.go，把 message 换成 Message，把 Chat 换成 ChatMessages 和新的 Chat，补完 TODO 1、2。','新建 internal/store/chat.go，补完 TODO 3 到 7。','运行 go vet ./... 和 go test ./...，确认原来的测试还能通过。'],expect:'没有报错，测试全部通过；下一个任务把它们用起来'},code:'// internal/ai/client.go（把 type message 到文件末尾换成下面的内容）\n// Message 是对话里的一条消息：Role 是 system、user 或 assistant。\ntype Message struct {\n    Role    string `json:"role"`\n    Content string `json:"content"`\n}\n\n// ChatMessages 发送一整段对话，返回模型的回答。\nfunc (c *Client) ChatMessages(messages []Message, temperature float64) (string, error) {\n    // TODO 1：把原来 Chat 里的代码搬过来：正文里的 temperature 和 messages 改用参数，\n    //         解析返回值的结构体里 message 换成 Message\n    return "", nil\n}\n\n// Chat 是第 14 关的函数，改成调用 ChatMessages：评分和讲解不用改。\nfunc (c *Client) Chat(system, user string) (string, error) {\n    // TODO 2：调用 ChatMessages，传入 system 和 user 两条消息，temperature 传 0\n    return "", nil\n}\n\n// internal/store/chat.go\npackage store\n\nimport (\n    "database/sql"\n    "errors"\n)\n\ntype Chat struct {\n    ID         int    `json:"id"`\n    QuestionID *int   `json:"questionId"`\n    Title      string `json:"title"`\n}\n\ntype ChatMessage struct {\n    Role      string `json:"role"`\n    Content   string `json:"content"`\n    CreatedAt string `json:"createdAt"`\n}\n\ntype ChatSummary struct {\n    Chat\n    UpdatedAt string `json:"updatedAt"`\n    Messages  int    `json:"messages"`\n}\n\nvar chatSchema = []string{\n    `CREATE TABLE IF NOT EXISTS chats (\n        id          INTEGER PRIMARY KEY AUTOINCREMENT,\n        user_id     INTEGER NOT NULL REFERENCES users(id),\n        question_id INTEGER REFERENCES questions(id),\n        title       TEXT    NOT NULL,\n        updated_at  TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP\n    )`,\n    `CREATE TABLE IF NOT EXISTS chat_messages (\n        id         INTEGER PRIMARY KEY AUTOINCREMENT,\n        chat_id    INTEGER NOT NULL REFERENCES chats(id),\n        role       TEXT    NOT NULL,\n        content    TEXT    NOT NULL,\n        created_at TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP\n    )`,\n    `CREATE TABLE IF NOT EXISTS chat_usage (\n        user_id INTEGER NOT NULL REFERENCES users(id),\n        day     TEXT    NOT NULL,\n        count   INTEGER NOT NULL,\n        PRIMARY KEY (user_id, day)\n    )`,\n}\n\ntype ChatStore struct {\n    db *sql.DB\n}\n\nfunc NewChatStore(db *sql.DB) (*ChatStore, error) {\n    for _, stmt := range chatSchema {\n        if _, err := db.Exec(stmt); err != nil {\n            return nil, err\n        }\n    }\n    return &ChatStore{db: db}, nil\n}\n\n// Get 返回某个用户的一段对话；不是这个用户的也当作不存在（ErrNotFound）。\nfunc (s *ChatStore) Get(userID, chatID int) (Chat, error) {\n    var c Chat\n    err := s.db.QueryRow("SELECT id, question_id, title FROM chats WHERE id = ? AND user_id = ?", chatID, userID).\n        Scan(&c.ID, &c.QuestionID, &c.Title)\n    if errors.Is(err, sql.ErrNoRows) {\n        return c, ErrNotFound\n    }\n    return c, err\n}\n\n// Messages 返回一段对话里的全部消息，按先后顺序。\nfunc (s *ChatStore) Messages(chatID int) ([]ChatMessage, error) {\n    rows, err := s.db.Query("SELECT role, content, created_at FROM chat_messages WHERE chat_id = ? ORDER BY id", chatID)\n    if err != nil {\n        return nil, err\n    }\n    defer rows.Close()\n    list := []ChatMessage{}\n    for rows.Next() {\n        var m ChatMessage\n        if err := rows.Scan(&m.Role, &m.Content, &m.CreatedAt); err != nil {\n            return nil, err\n        }\n        list = append(list, m)\n    }\n    return list, rows.Err()\n}\n\n// List 返回某个用户的对话列表，最近问过的在前。\nfunc (s *ChatStore) List(userID int) ([]ChatSummary, error) {\n    rows, err := s.db.Query(`SELECT c.id, c.question_id, c.title, c.updated_at, COUNT(m.id)\n        FROM chats c LEFT JOIN chat_messages m ON m.chat_id = c.id\n        WHERE c.user_id = ? GROUP BY c.id ORDER BY c.updated_at DESC, c.id DESC`, userID)\n    if err != nil {\n        return nil, err\n    }\n    defer rows.Close()\n    list := []ChatSummary{}\n    for rows.Next() {\n        var c ChatSummary\n        if err := rows.Scan(&c.ID, &c.QuestionID, &c.Title, &c.UpdatedAt, &c.Messages); err != nil {\n            return nil, err\n        }\n        list = append(list, c)\n    }\n    return list, rows.Err()\n}\n\n// TakeQuota 占用今天的一次提问：没到上限就加一并返回已用次数，到了上限 ok 为 false。\nfunc (s *ChatStore) TakeQuota(userID, limit int) (used int, ok bool, err error) {\n    // TODO 3：一条 SQL 完成“没有今天的记录就插入 count = 1，有就在 count < limit 时加一”，用 RETURNING count 拿回新的次数；\n    //         到了上限时这条 SQL 不会改任何行，Scan 得到 sql.ErrNoRows，这时返回 0, false, nil\n    return 0, false, nil\n}\n\n// RefundQuota 在提问失败时把刚才占用的一次还回去。\nfunc (s *ChatStore) RefundQuota(userID int) error {\n    // TODO 4：把今天的 count 减一，用 MAX(count - 1, 0) 保证不会减成负数\n    return nil\n}\n\n// SaveTurn 保存一轮问答：chatID 为 0 时先新建对话。几条写入放在同一个事务里。\nfunc (s *ChatStore) SaveTurn(userID, chatID int, questionID *int, title, question, reply string) (int, error) {\n    // TODO 5：开事务（记得 defer tx.Rollback()）。chatID 为 0 就插入一行 chats 并用 LastInsertId 拿到新的 id，否则更新 updated_at\n    // TODO 6：往 chat_messages 插入两行：先是 user 的 question，再是 assistant 的 reply；最后 Commit 并返回 chatID\n    return 0, nil\n}\n\n// Delete 删除自己的一段对话（连同里面的消息），不是自己的返回 ErrNotFound。\nfunc (s *ChatStore) Delete(userID, chatID int) error {\n    // TODO 7：在事务里先确认这段对话是 userID 的（不是就返回 ErrNotFound），再删消息、删对话，最后 Commit\n    return nil\n}\n',explain:[{at:'// internal/ai/client.go（把 type message 到文件末尾换成下面的内容）',to:'// ChatMessages 发送一整段对话，返回模型的回答。',text:'打开第 14 关写的 internal/ai/client.go。原来的 message 类型首字母小写，只能在 ai 包里用；现在业务逻辑层要自己拼消息列表，所以改成首字母大写的 Message。'},{at:'// internal/store/chat.go',to:')',text:'新建数据访问层文件，专门负责对话相关的三张表。'},{at:'type Chat struct {',to:'}',text:'一段对话。QuestionID 是指针：对话可以不针对具体题目，这时数据库里是 NULL，这里就是 nil，转成 JSON 是 null。'},{at:'type ChatMessage struct {',to:'}',text:'对话里的一句话。Role 是 user（学生问的）或 assistant（AI 答的），和发给大模型的 role 一致。'},{at:'type ChatSummary struct {',to:'var chatSchema = []string{',text:'历史列表里的一项：把 Chat 嵌进来，再加上最后提问时间和消息条数。'},{at:'`CREATE TABLE IF NOT EXISTS chats (',to:')`,',text:'chats 表：一段对话一行。user_id 是谁的对话；question_id 可以为空；title 是显示在历史列表里的标题；updated_at 是最后一次提问的时间。'},{at:'`CREATE TABLE IF NOT EXISTS chat_messages (',to:')`,',text:'chat_messages 表：对话里的每一句话一行。'},{at:'`CREATE TABLE IF NOT EXISTS chat_usage (',to:'}',text:'chat_usage 表：每个用户每天一行，count 是当天已经问了几次。联合主键保证同一个人同一天只有一行。次数单独记一张表，而不是去数消息：这样删除对话不会把次数“删回来”。'},{at:'type ChatStore struct {',to:'// Get 返回某个用户的一段对话；不是这个用户的也当作不存在（ErrNotFound）。',text:'和前几关的 ExamStore 一样：创建时把三张表建好。'},{at:'func (s *ChatStore) Get(userID, chatID int) (Chat, error) {',to:'// Messages 返回一段对话里的全部消息，按先后顺序。',text:'按“对话 id + 用户 id”一起查：不是自己的对话就查不到，和不存在一样，都返回 ErrNotFound。'},{at:'func (s *ChatStore) Messages(chatID int) ([]ChatMessage, error) {',to:'// List 返回某个用户的对话列表，最近问过的在前。',text:'一段对话里的所有消息，按 id 从小到大，也就是说话的先后顺序。'},{at:'func (s *ChatStore) List(userID int) ([]ChatSummary, error) {',to:'// TakeQuota 占用今天的一次提问：没到上限就加一并返回已用次数，到了上限 ok 为 false。',text:'我的对话列表：LEFT JOIN 消息表再 GROUP BY，用 COUNT(m.id) 数出每段对话有几条消息；最近问过的排在前面。'},{at:'func (c *Client) ChatMessages(messages []Message, temperature float64) (string, error) {',text:'新的方法：直接接收一整个消息列表和 temperature。要你补全。',to:'// Chat 是第 14 关的函数，改成调用 ChatMessages：评分和讲解不用改。'},{at:'func (c *Client) Chat(system, user string) (string, error) {',text:'保留原来的名字和参数，第 14 关的评分、讲解代码一行都不用改。要你补全。',to:'}'},{at:'func (s *ChatStore) TakeQuota(userID, limit int) (used int, ok bool, err error) {',text:'占用一次提问次数，要你补全。',to:'// RefundQuota 在提问失败时把刚才占用的一次还回去。'},{at:'func (s *ChatStore) RefundQuota(userID int) error {',text:'退回一次，要你补全。',to:'// SaveTurn 保存一轮问答：chatID 为 0 时先新建对话。几条写入放在同一个事务里。'},{at:'func (s *ChatStore) SaveTurn(',text:'保存一问一答，要你补全。',to:'// Delete 删除自己的一段对话（连同里面的消息），不是自己的返回 ErrNotFound。'},{at:'func (s *ChatStore) Delete(userID, chatID int) error {',text:'删除对话，要你补全。',to:'}'}],solution:{code:'// internal/ai/client.go（把 type message 到文件末尾换成下面的内容）\n// Message 是对话里的一条消息：Role 是 system、user 或 assistant。\ntype Message struct {\n    Role    string `json:"role"`\n    Content string `json:"content"`\n}\n\n// ChatMessages 发送一整段对话，返回模型的回答。\nfunc (c *Client) ChatMessages(messages []Message, temperature float64) (string, error) {\n    if c.apiKey == "" {\n        return "", ErrNotConfigured\n    }\n    body, err := json.Marshal(map[string]any{"model": c.model, "temperature": temperature, "messages": messages})\n    if err != nil {\n        return "", err\n    }\n    req, err := http.NewRequest(http.MethodPost, c.baseURL+"/chat/completions", bytes.NewReader(body))\n    if err != nil {\n        return "", err\n    }\n    req.Header.Set("Authorization", "Bearer "+c.apiKey)\n    req.Header.Set("Content-Type", "application/json")\n    resp, err := c.http.Do(req)\n    if err != nil {\n        return "", err\n    }\n    defer resp.Body.Close()\n    if resp.StatusCode != http.StatusOK {\n        return "", fmt.Errorf("AI 服务返回状态码 %d", resp.StatusCode)\n    }\n    var out struct {\n        Choices []struct {\n            Message Message `json:"message"`\n        } `json:"choices"`\n    }\n    if err := json.NewDecoder(resp.Body).Decode(&out); err != nil {\n        return "", err\n    }\n    if len(out.Choices) == 0 {\n        return "", errors.New("AI 服务没有返回内容")\n    }\n    return out.Choices[0].Message.Content, nil\n}\n\n// Chat 是第 14 关的函数，改成调用 ChatMessages：评分和讲解不用改。\nfunc (c *Client) Chat(system, user string) (string, error) {\n    return c.ChatMessages([]Message{{"system", system}, {"user", user}}, 0)\n}\n\n// internal/store/chat.go\npackage store\n\nimport (\n    "database/sql"\n    "errors"\n)\n\ntype Chat struct {\n    ID         int    `json:"id"`\n    QuestionID *int   `json:"questionId"`\n    Title      string `json:"title"`\n}\n\ntype ChatMessage struct {\n    Role      string `json:"role"`\n    Content   string `json:"content"`\n    CreatedAt string `json:"createdAt"`\n}\n\ntype ChatSummary struct {\n    Chat\n    UpdatedAt string `json:"updatedAt"`\n    Messages  int    `json:"messages"`\n}\n\nvar chatSchema = []string{\n    `CREATE TABLE IF NOT EXISTS chats (\n        id          INTEGER PRIMARY KEY AUTOINCREMENT,\n        user_id     INTEGER NOT NULL REFERENCES users(id),\n        question_id INTEGER REFERENCES questions(id),\n        title       TEXT    NOT NULL,\n        updated_at  TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP\n    )`,\n    `CREATE TABLE IF NOT EXISTS chat_messages (\n        id         INTEGER PRIMARY KEY AUTOINCREMENT,\n        chat_id    INTEGER NOT NULL REFERENCES chats(id),\n        role       TEXT    NOT NULL,\n        content    TEXT    NOT NULL,\n        created_at TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP\n    )`,\n    `CREATE TABLE IF NOT EXISTS chat_usage (\n        user_id INTEGER NOT NULL REFERENCES users(id),\n        day     TEXT    NOT NULL,\n        count   INTEGER NOT NULL,\n        PRIMARY KEY (user_id, day)\n    )`,\n}\n\ntype ChatStore struct {\n    db *sql.DB\n}\n\nfunc NewChatStore(db *sql.DB) (*ChatStore, error) {\n    for _, stmt := range chatSchema {\n        if _, err := db.Exec(stmt); err != nil {\n            return nil, err\n        }\n    }\n    return &ChatStore{db: db}, nil\n}\n\n// Get 返回某个用户的一段对话；不是这个用户的也当作不存在（ErrNotFound）。\nfunc (s *ChatStore) Get(userID, chatID int) (Chat, error) {\n    var c Chat\n    err := s.db.QueryRow("SELECT id, question_id, title FROM chats WHERE id = ? AND user_id = ?", chatID, userID).\n        Scan(&c.ID, &c.QuestionID, &c.Title)\n    if errors.Is(err, sql.ErrNoRows) {\n        return c, ErrNotFound\n    }\n    return c, err\n}\n\n// Messages 返回一段对话里的全部消息，按先后顺序。\nfunc (s *ChatStore) Messages(chatID int) ([]ChatMessage, error) {\n    rows, err := s.db.Query("SELECT role, content, created_at FROM chat_messages WHERE chat_id = ? ORDER BY id", chatID)\n    if err != nil {\n        return nil, err\n    }\n    defer rows.Close()\n    list := []ChatMessage{}\n    for rows.Next() {\n        var m ChatMessage\n        if err := rows.Scan(&m.Role, &m.Content, &m.CreatedAt); err != nil {\n            return nil, err\n        }\n        list = append(list, m)\n    }\n    return list, rows.Err()\n}\n\n// List 返回某个用户的对话列表，最近问过的在前。\nfunc (s *ChatStore) List(userID int) ([]ChatSummary, error) {\n    rows, err := s.db.Query(`SELECT c.id, c.question_id, c.title, c.updated_at, COUNT(m.id)\n        FROM chats c LEFT JOIN chat_messages m ON m.chat_id = c.id\n        WHERE c.user_id = ? GROUP BY c.id ORDER BY c.updated_at DESC, c.id DESC`, userID)\n    if err != nil {\n        return nil, err\n    }\n    defer rows.Close()\n    list := []ChatSummary{}\n    for rows.Next() {\n        var c ChatSummary\n        if err := rows.Scan(&c.ID, &c.QuestionID, &c.Title, &c.UpdatedAt, &c.Messages); err != nil {\n            return nil, err\n        }\n        list = append(list, c)\n    }\n    return list, rows.Err()\n}\n\n// TakeQuota 占用今天的一次提问：没到上限就加一并返回已用次数，到了上限 ok 为 false。\nfunc (s *ChatStore) TakeQuota(userID, limit int) (used int, ok bool, err error) {\n    err = s.db.QueryRow(`INSERT INTO chat_usage (user_id, day, count) VALUES (?, date(\'now\'), 1)\n        ON CONFLICT (user_id, day) DO UPDATE SET count = count + 1 WHERE count < ?\n        RETURNING count`, userID, limit).Scan(&used)\n    if errors.Is(err, sql.ErrNoRows) {\n        return 0, false, nil\n    }\n    return used, err == nil, err\n}\n\n// RefundQuota 在提问失败时把刚才占用的一次还回去。\nfunc (s *ChatStore) RefundQuota(userID int) error {\n    _, err := s.db.Exec("UPDATE chat_usage SET count = MAX(count - 1, 0) WHERE user_id = ? AND day = date(\'now\')", userID)\n    return err\n}\n\n// SaveTurn 保存一轮问答：chatID 为 0 时先新建对话。几条写入放在同一个事务里。\nfunc (s *ChatStore) SaveTurn(userID, chatID int, questionID *int, title, question, reply string) (int, error) {\n    tx, err := s.db.Begin()\n    if err != nil {\n        return 0, err\n    }\n    defer tx.Rollback()\n    if chatID == 0 {\n        res, err := tx.Exec("INSERT INTO chats (user_id, question_id, title) VALUES (?, ?, ?)", userID, questionID, title)\n        if err != nil {\n            return 0, err\n        }\n        id, err := res.LastInsertId()\n        if err != nil {\n            return 0, err\n        }\n        chatID = int(id)\n    } else if _, err := tx.Exec("UPDATE chats SET updated_at = CURRENT_TIMESTAMP WHERE id = ?", chatID); err != nil {\n        return 0, err\n    }\n    for _, m := range [][2]string{{"user", question}, {"assistant", reply}} {\n        if _, err := tx.Exec("INSERT INTO chat_messages (chat_id, role, content) VALUES (?, ?, ?)", chatID, m[0], m[1]); err != nil {\n            return 0, err\n        }\n    }\n    return chatID, tx.Commit()\n}\n\n// Delete 删除自己的一段对话（连同里面的消息），不是自己的返回 ErrNotFound。\nfunc (s *ChatStore) Delete(userID, chatID int) error {\n    tx, err := s.db.Begin()\n    if err != nil {\n        return err\n    }\n    defer tx.Rollback()\n    var id int\n    err = tx.QueryRow("SELECT id FROM chats WHERE id = ? AND user_id = ?", chatID, userID).Scan(&id)\n    if errors.Is(err, sql.ErrNoRows) {\n        return ErrNotFound\n    }\n    if err != nil {\n        return err\n    }\n    if _, err := tx.Exec("DELETE FROM chat_messages WHERE chat_id = ?", chatID); err != nil {\n        return err\n    }\n    if _, err := tx.Exec("DELETE FROM chats WHERE id = ?", chatID); err != nil {\n        return err\n    }\n    return tx.Commit()\n}\n',explain:[{at:'// internal/ai/client.go（把 type message 到文件末尾换成下面的内容）',to:'// ChatMessages 发送一整段对话，返回模型的回答。',text:'打开第 14 关写的 internal/ai/client.go。原来的 message 类型首字母小写，只能在 ai 包里用；现在业务逻辑层要自己拼消息列表，所以改成首字母大写的 Message。'},{at:'// internal/store/chat.go',to:')',text:'新建数据访问层文件，专门负责对话相关的三张表。'},{at:'type Chat struct {',to:'}',text:'一段对话。QuestionID 是指针：对话可以不针对具体题目，这时数据库里是 NULL，这里就是 nil，转成 JSON 是 null。'},{at:'type ChatMessage struct {',to:'}',text:'对话里的一句话。Role 是 user（学生问的）或 assistant（AI 答的），和发给大模型的 role 一致。'},{at:'type ChatSummary struct {',to:'var chatSchema = []string{',text:'历史列表里的一项：把 Chat 嵌进来，再加上最后提问时间和消息条数。'},{at:'`CREATE TABLE IF NOT EXISTS chats (',to:')`,',text:'chats 表：一段对话一行。user_id 是谁的对话；question_id 可以为空；title 是显示在历史列表里的标题；updated_at 是最后一次提问的时间。'},{at:'`CREATE TABLE IF NOT EXISTS chat_messages (',to:')`,',text:'chat_messages 表：对话里的每一句话一行。'},{at:'`CREATE TABLE IF NOT EXISTS chat_usage (',to:'}',text:'chat_usage 表：每个用户每天一行，count 是当天已经问了几次。联合主键保证同一个人同一天只有一行。次数单独记一张表，而不是去数消息：这样删除对话不会把次数“删回来”。'},{at:'type ChatStore struct {',to:'// Get 返回某个用户的一段对话；不是这个用户的也当作不存在（ErrNotFound）。',text:'和前几关的 ExamStore 一样：创建时把三张表建好。'},{at:'func (s *ChatStore) Get(userID, chatID int) (Chat, error) {',to:'// Messages 返回一段对话里的全部消息，按先后顺序。',text:'按“对话 id + 用户 id”一起查：不是自己的对话就查不到，和不存在一样，都返回 ErrNotFound。'},{at:'func (s *ChatStore) Messages(chatID int) ([]ChatMessage, error) {',to:'// List 返回某个用户的对话列表，最近问过的在前。',text:'一段对话里的所有消息，按 id 从小到大，也就是说话的先后顺序。'},{at:'func (s *ChatStore) List(userID int) ([]ChatSummary, error) {',to:'// TakeQuota 占用今天的一次提问：没到上限就加一并返回已用次数，到了上限 ok 为 false。',text:'我的对话列表：LEFT JOIN 消息表再 GROUP BY，用 COUNT(m.id) 数出每段对话有几条消息；最近问过的排在前面。'},{at:'func (c *Client) ChatMessages(messages []Message, temperature float64) (string, error) {',to:'// Chat 是第 14 关的函数，改成调用 ChatMessages：评分和讲解不用改。',text:'和原来的 Chat 几乎一样，区别只有两处：messages 由调用方传进来，可以是任意多条；temperature 也由调用方决定。'},{at:'func (c *Client) Chat(system, user string) (string, error) {',to:'return c.ChatMessages(',text:'原来的 Chat 变成一层很薄的包装：把两个字符串拼成两条消息，temperature 传 0（评分要稳定）。两个方法共用一份发请求的代码。'},{at:'func (s *ChatStore) TakeQuota(userID, limit int) (used int, ok bool, err error) {',to:'// RefundQuota 在提问失败时把刚才占用的一次还回去。',text:'“检查有没有超限”和“次数加一”必须是一步：如果先查再改，同一个人同时发两个请求，可能都查到“还剩 1 次”，结果都通过。这条 SQL 的意思是：今天还没有记录就插入 count = 1；已经有了（主键冲突）就改成 count + 1，但只在 count < 上限时才改。RETURNING count 把改完的次数拿回来；到了上限时一行都没改，Scan 得到 sql.ErrNoRows。'},{at:'func (s *ChatStore) RefundQuota(userID int) error {',to:'// SaveTurn 保存一轮问答：chatID 为 0 时先新建对话。几条写入放在同一个事务里。',text:'大模型调用失败时把次数还回去。MAX(count - 1, 0) 保证不会变成负数。'},{at:'func (s *ChatStore) SaveTurn(',to:'defer tx.Rollback()',text:'开一个事务。defer tx.Rollback() 保证中途出错返回时自动撤销；已经 Commit 之后再 Rollback 不会有任何效果。'},{at:'if chatID == 0 {',to:'chatID = int(id)',text:'新对话先插入 chats，LastInsertId 是数据库自动生成的 id。'},{at:'} else if _, err := tx.Exec("UPDATE chats SET updated_at',to:'return 0, err',text:'已有的对话只更新“最后提问时间”，它决定历史列表的排序。'},{at:'for _, m := range [][2]string{{"user", question}, {"assistant", reply}} {',to:'// Delete 删除自己的一段对话（连同里面的消息），不是自己的返回 ErrNotFound。',text:'一问一答两条消息一起存，然后提交。因为在同一个事务里，不会出现“存了问题没存回答”的半截数据。'},{at:'func (s *ChatStore) Delete(userID, chatID int) error {',to:'return tx.Commit()',text:'先确认这段对话是自己的，再删消息、删对话，三步在同一个事务里。先删消息是因为消息表引用了对话表。'}]}},java:{practice:{steps:['打开 ai/AiClient.java，给 Message 加上 public，把 chat 方法换成 chatMessages 和新的 chat，补完 TODO 1、2。','在 schema.sql 最后加上三张表，新建 repository/ChatRepository.java，补完 TODO 3 到 7。','运行 mvn test（Windows 用 mvnw.cmd test），确认原来的测试还能通过。'],expect:'BUILD SUCCESS；下一个任务把它们用起来'},code:'// ai/AiClient.java（把 Message 改成 public，再把 chat 方法换成下面两个方法）\n    public record Message(String role, String content) {}\n\n    // 发送一整段对话（消息列表），返回模型的回答\n    public String chatMessages(List<Message> messages, double temperature) {\n        // TODO 1：把原来 chat 方法里的代码搬过来，正文改成 Map.of("model", model, "temperature", temperature, "messages", messages)\n        return "";\n    }\n\n    // 第 14 关的 chat 改成调用 chatMessages：评分和讲解不用改\n    public String chat(String system, String user) {\n        // TODO 2：调用 chatMessages，传入 system 和 user 两条消息，temperature 传 0\n        return "";\n    }\n\n-- schema.sql（加在文件最后）\nCREATE TABLE IF NOT EXISTS chats (\n    id          INTEGER PRIMARY KEY AUTOINCREMENT,\n    user_id     INTEGER NOT NULL REFERENCES users(id),\n    question_id INTEGER REFERENCES questions(id),\n    title       TEXT    NOT NULL,\n    updated_at  TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE TABLE IF NOT EXISTS chat_messages (\n    id         INTEGER PRIMARY KEY AUTOINCREMENT,\n    chat_id    INTEGER NOT NULL REFERENCES chats(id),\n    role       TEXT    NOT NULL,\n    content    TEXT    NOT NULL,\n    created_at TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE TABLE IF NOT EXISTS chat_usage (\n    user_id INTEGER NOT NULL REFERENCES users(id),\n    day     TEXT    NOT NULL,\n    count   INTEGER NOT NULL,\n    PRIMARY KEY (user_id, day)\n);\n\n// repository/ChatRepository.java\npackage com.example.zixishi.repository;\n\nimport java.util.List;\nimport java.util.Optional;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.springframework.stereotype.Repository;\nimport org.springframework.transaction.annotation.Transactional;\n\n@Repository\npublic class ChatRepository {\n\n    public record Chat(int id, Integer questionId, String title) {}\n\n    public record ChatMessage(String role, String content, String createdAt) {}\n\n    public record ChatSummary(int id, String title, Integer questionId, String updatedAt, int messages) {}\n\n    private final JdbcTemplate jdbc;\n\n    public ChatRepository(JdbcTemplate jdbc) {\n        this.jdbc = jdbc;\n    }\n\n    // 某个用户的一段对话；不是这个用户的也当作不存在\n    public Optional<Chat> find(int userId, int chatId) {\n        return jdbc.query("SELECT id, question_id, title FROM chats WHERE id = ? AND user_id = ?",\n            (rs, i) -> new Chat(rs.getInt("id"), (Integer) rs.getObject("question_id"), rs.getString("title")),\n            chatId, userId).stream().findFirst();\n    }\n\n    public List<ChatMessage> messages(int chatId) {\n        return jdbc.query("SELECT role, content, created_at FROM chat_messages WHERE chat_id = ? ORDER BY id",\n            (rs, i) -> new ChatMessage(rs.getString("role"), rs.getString("content"), rs.getString("created_at")), chatId);\n    }\n\n    public List<ChatSummary> list(int userId) {\n        return jdbc.query("""\n            SELECT c.id, c.title, c.question_id, c.updated_at, COUNT(m.id) AS messages\n            FROM chats c LEFT JOIN chat_messages m ON m.chat_id = c.id\n            WHERE c.user_id = ? GROUP BY c.id ORDER BY c.updated_at DESC, c.id DESC""",\n            (rs, i) -> new ChatSummary(rs.getInt("id"), rs.getString("title"), (Integer) rs.getObject("question_id"),\n                rs.getString("updated_at"), rs.getInt("messages")), userId);\n    }\n\n    // 占用今天的一次提问：没到上限就加一并返回已用次数，到了上限返回空\n    public Optional<Integer> takeQuota(int userId, int limit) {\n        // TODO 3：一条 SQL 完成“没有今天的记录就插入 count = 1，有就在 count < limit 时加一”，用 RETURNING count 拿回新的次数；\n        //         用 jdbc.queryForList(sql, Integer.class, …).stream().findFirst()：到了上限时一行都没改，得到空的 Optional\n        return Optional.empty();\n    }\n\n    // 提问失败时把刚才占用的一次还回去\n    public void refundQuota(int userId) {\n        // TODO 4：把今天的 count 减一，用 MAX(count - 1, 0) 保证不会减成负数\n    }\n\n    // 保存一轮问答：chatId 为 null 时先新建对话。几条写入放在同一个事务里\n    @Transactional\n    public int saveTurn(int userId, Integer chatId, Integer questionId, String title, String question, String reply) {\n        // TODO 5：chatId 为 null 就插入一行 chats，再用 SELECT last_insert_rowid() 拿到新的 id；否则更新 updated_at\n        // TODO 6：往 chat_messages 插入两行：先是 user 的 question，再是 assistant 的 reply；最后返回对话的 id\n        return 0;\n    }\n\n    // 删除自己的一段对话（连同里面的消息），不是自己的返回 false\n    @Transactional\n    public boolean delete(int userId, int chatId) {\n        // TODO 7：先用 find 确认是自己的，再删 chat_messages 里的消息，最后删 chats 里的这一行\n        return false;\n    }\n}',explain:[{at:'// ai/AiClient.java（把 Message 改成 public，再把 chat 方法换成下面两个方法）',to:'// 发送一整段对话（消息列表），返回模型的回答',text:'打开第 14 关写的 ai/AiClient.java。原来的 Message 没有写 public，只能在 ai 这个包里用；现在业务逻辑层要自己拼消息列表，所以加上 public。'},{at:'-- schema.sql（加在文件最后）',text:'打开 src/main/resources/schema.sql，把下面三张表加到最后。启动时 Spring Boot 会执行整个文件，表不存在就新建。'},{at:'CREATE TABLE IF NOT EXISTS chats (',to:');',text:'chats 表：一段对话一行。user_id 是谁的对话；question_id 是针对哪道题问的，可以为空（不针对具体题目）；title 是显示在历史列表里的标题；updated_at 是最后一次提问的时间。'},{at:'CREATE TABLE IF NOT EXISTS chat_messages (',to:');',text:'chat_messages 表：对话里的每一句话一行。role 是 user（学生问的）或 assistant（AI 答的），和发给大模型的 role 一致。'},{at:'CREATE TABLE IF NOT EXISTS chat_usage (',to:');',text:'chat_usage 表：每个用户每天一行，count 是当天已经问了几次。联合主键保证同一个人同一天只有一行。次数单独记一张表，而不是去数消息：这样删除对话不会把次数“删回来”。'},{at:'// repository/ChatRepository.java',to:'public class ChatRepository {',text:'新建数据访问层，专门负责对话相关的三张表。'},{at:'public record Chat(int id, Integer questionId, String title) {}',to:'public record ChatSummary(int id, String title, Integer questionId, String updatedAt, int messages) {}',text:'三个只在对话功能里用的数据类型，直接写在这个类里面：一段对话、一条消息、历史列表里的一项。questionId 用 Integer 而不是 int，因为它可以是 null。'},{at:'private final JdbcTemplate jdbc;',to:'// 某个用户的一段对话；不是这个用户的也当作不存在',text:'和其他 Repository 一样，通过构造方法拿到 JdbcTemplate。'},{at:'public Optional<Chat> find(int userId, int chatId) {',to:'}',text:'按“对话 id + 用户 id”一起查：不是自己的对话就查不到，和不存在一样。rs.getObject 在列是 NULL 时返回 null，而 rs.getInt 会返回 0，所以可以为空的列用 getObject。'},{at:'public List<ChatMessage> messages(int chatId) {',to:'}',text:'一段对话里的所有消息，按 id 从小到大，也就是说话的先后顺序。'},{at:'public List<ChatSummary> list(int userId) {',to:'// 占用今天的一次提问：没到上限就加一并返回已用次数，到了上限返回空',text:'我的对话列表：LEFT JOIN 消息表再 GROUP BY，用 COUNT(m.id) 数出每段对话有几条消息；最近问过的排在前面。'},{at:'public String chatMessages(List<Message> messages, double temperature) {',text:'新的方法：直接接收一整个消息列表和 temperature。要你补全。',to:'// 第 14 关的 chat 改成调用 chatMessages：评分和讲解不用改'},{at:'public String chat(String system, String user) {',text:'保留原来的名字和参数，第 14 关的评分、讲解代码一行都不用改。要你补全。',to:'}'},{at:'public Optional<Integer> takeQuota(int userId, int limit) {',text:'占用一次提问次数，要你补全。',to:'// 提问失败时把刚才占用的一次还回去'},{at:'public void refundQuota(int userId) {',text:'退回一次，要你补全。',to:'@Transactional'},{at:'public int saveTurn(',text:'保存一问一答，要你补全。@Transactional 让方法里的几条写入要么全部成功，要么全部不生效。',to:'@Transactional'},{at:'public boolean delete(int userId, int chatId) {',text:'删除对话，要你补全。',to:'}'}],solution:{code:'// ai/AiClient.java（把 Message 改成 public，再把 chat 方法换成下面两个方法）\n    public record Message(String role, String content) {}\n\n    // 发送一整段对话（消息列表），返回模型的回答\n    public String chatMessages(List<Message> messages, double temperature) {\n        if (apiKey.isBlank()) {\n            throw new NotConfiguredException();\n        }\n        ChatResponse response = http.post()\n            .uri("/chat/completions")\n            .header("Authorization", "Bearer " + apiKey)\n            .body(Map.of("model", model, "temperature", temperature, "messages", messages))\n            .retrieve()\n            .body(ChatResponse.class);\n        if (response == null || response.choices() == null || response.choices().isEmpty()) {\n            throw new IllegalStateException("AI 服务没有返回内容");\n        }\n        return response.choices().get(0).message().content();\n    }\n\n    // 第 14 关的 chat 改成调用 chatMessages：评分和讲解不用改\n    public String chat(String system, String user) {\n        return chatMessages(List.of(new Message("system", system), new Message("user", user)), 0);\n    }\n\n-- schema.sql（加在文件最后）\nCREATE TABLE IF NOT EXISTS chats (\n    id          INTEGER PRIMARY KEY AUTOINCREMENT,\n    user_id     INTEGER NOT NULL REFERENCES users(id),\n    question_id INTEGER REFERENCES questions(id),\n    title       TEXT    NOT NULL,\n    updated_at  TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE TABLE IF NOT EXISTS chat_messages (\n    id         INTEGER PRIMARY KEY AUTOINCREMENT,\n    chat_id    INTEGER NOT NULL REFERENCES chats(id),\n    role       TEXT    NOT NULL,\n    content    TEXT    NOT NULL,\n    created_at TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE TABLE IF NOT EXISTS chat_usage (\n    user_id INTEGER NOT NULL REFERENCES users(id),\n    day     TEXT    NOT NULL,\n    count   INTEGER NOT NULL,\n    PRIMARY KEY (user_id, day)\n);\n\n// repository/ChatRepository.java\npackage com.example.zixishi.repository;\n\nimport java.util.List;\nimport java.util.Optional;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.springframework.stereotype.Repository;\nimport org.springframework.transaction.annotation.Transactional;\n\n@Repository\npublic class ChatRepository {\n\n    public record Chat(int id, Integer questionId, String title) {}\n\n    public record ChatMessage(String role, String content, String createdAt) {}\n\n    public record ChatSummary(int id, String title, Integer questionId, String updatedAt, int messages) {}\n\n    private final JdbcTemplate jdbc;\n\n    public ChatRepository(JdbcTemplate jdbc) {\n        this.jdbc = jdbc;\n    }\n\n    // 某个用户的一段对话；不是这个用户的也当作不存在\n    public Optional<Chat> find(int userId, int chatId) {\n        return jdbc.query("SELECT id, question_id, title FROM chats WHERE id = ? AND user_id = ?",\n            (rs, i) -> new Chat(rs.getInt("id"), (Integer) rs.getObject("question_id"), rs.getString("title")),\n            chatId, userId).stream().findFirst();\n    }\n\n    public List<ChatMessage> messages(int chatId) {\n        return jdbc.query("SELECT role, content, created_at FROM chat_messages WHERE chat_id = ? ORDER BY id",\n            (rs, i) -> new ChatMessage(rs.getString("role"), rs.getString("content"), rs.getString("created_at")), chatId);\n    }\n\n    public List<ChatSummary> list(int userId) {\n        return jdbc.query("""\n            SELECT c.id, c.title, c.question_id, c.updated_at, COUNT(m.id) AS messages\n            FROM chats c LEFT JOIN chat_messages m ON m.chat_id = c.id\n            WHERE c.user_id = ? GROUP BY c.id ORDER BY c.updated_at DESC, c.id DESC""",\n            (rs, i) -> new ChatSummary(rs.getInt("id"), rs.getString("title"), (Integer) rs.getObject("question_id"),\n                rs.getString("updated_at"), rs.getInt("messages")), userId);\n    }\n\n    // 占用今天的一次提问：没到上限就加一并返回已用次数，到了上限返回空\n    public Optional<Integer> takeQuota(int userId, int limit) {\n        return jdbc.queryForList("""\n            INSERT INTO chat_usage (user_id, day, count) VALUES (?, date(\'now\'), 1)\n            ON CONFLICT (user_id, day) DO UPDATE SET count = count + 1 WHERE count < ?\n            RETURNING count""", Integer.class, userId, limit).stream().findFirst();\n    }\n\n    // 提问失败时把刚才占用的一次还回去\n    public void refundQuota(int userId) {\n        jdbc.update("UPDATE chat_usage SET count = MAX(count - 1, 0) WHERE user_id = ? AND day = date(\'now\')", userId);\n    }\n\n    // 保存一轮问答：chatId 为 null 时先新建对话。几条写入放在同一个事务里\n    @Transactional\n    public int saveTurn(int userId, Integer chatId, Integer questionId, String title, String question, String reply) {\n        int id;\n        if (chatId == null) {\n            jdbc.update("INSERT INTO chats (user_id, question_id, title) VALUES (?, ?, ?)", userId, questionId, title);\n            id = jdbc.queryForObject("SELECT last_insert_rowid()", Integer.class);\n        } else {\n            id = chatId;\n            jdbc.update("UPDATE chats SET updated_at = CURRENT_TIMESTAMP WHERE id = ?", id);\n        }\n        jdbc.update("INSERT INTO chat_messages (chat_id, role, content) VALUES (?, \'user\', ?)", id, question);\n        jdbc.update("INSERT INTO chat_messages (chat_id, role, content) VALUES (?, \'assistant\', ?)", id, reply);\n        return id;\n    }\n\n    // 删除自己的一段对话（连同里面的消息），不是自己的返回 false\n    @Transactional\n    public boolean delete(int userId, int chatId) {\n        if (find(userId, chatId).isEmpty()) {\n            return false;\n        }\n        jdbc.update("DELETE FROM chat_messages WHERE chat_id = ?", chatId);\n        jdbc.update("DELETE FROM chats WHERE id = ?", chatId);\n        return true;\n    }\n}',explain:[{at:'// ai/AiClient.java（把 Message 改成 public，再把 chat 方法换成下面两个方法）',to:'// 发送一整段对话（消息列表），返回模型的回答',text:'打开第 14 关写的 ai/AiClient.java。原来的 Message 没有写 public，只能在 ai 这个包里用；现在业务逻辑层要自己拼消息列表，所以加上 public。'},{at:'-- schema.sql（加在文件最后）',text:'打开 src/main/resources/schema.sql，把下面三张表加到最后。启动时 Spring Boot 会执行整个文件，表不存在就新建。'},{at:'CREATE TABLE IF NOT EXISTS chats (',to:');',text:'chats 表：一段对话一行。user_id 是谁的对话；question_id 是针对哪道题问的，可以为空（不针对具体题目）；title 是显示在历史列表里的标题；updated_at 是最后一次提问的时间。'},{at:'CREATE TABLE IF NOT EXISTS chat_messages (',to:');',text:'chat_messages 表：对话里的每一句话一行。role 是 user（学生问的）或 assistant（AI 答的），和发给大模型的 role 一致。'},{at:'CREATE TABLE IF NOT EXISTS chat_usage (',to:');',text:'chat_usage 表：每个用户每天一行，count 是当天已经问了几次。联合主键保证同一个人同一天只有一行。次数单独记一张表，而不是去数消息：这样删除对话不会把次数“删回来”。'},{at:'// repository/ChatRepository.java',to:'public class ChatRepository {',text:'新建数据访问层，专门负责对话相关的三张表。'},{at:'public record Chat(int id, Integer questionId, String title) {}',to:'public record ChatSummary(int id, String title, Integer questionId, String updatedAt, int messages) {}',text:'三个只在对话功能里用的数据类型，直接写在这个类里面：一段对话、一条消息、历史列表里的一项。questionId 用 Integer 而不是 int，因为它可以是 null。'},{at:'private final JdbcTemplate jdbc;',to:'// 某个用户的一段对话；不是这个用户的也当作不存在',text:'和其他 Repository 一样，通过构造方法拿到 JdbcTemplate。'},{at:'public Optional<Chat> find(int userId, int chatId) {',to:'}',text:'按“对话 id + 用户 id”一起查：不是自己的对话就查不到，和不存在一样。rs.getObject 在列是 NULL 时返回 null，而 rs.getInt 会返回 0，所以可以为空的列用 getObject。'},{at:'public List<ChatMessage> messages(int chatId) {',to:'}',text:'一段对话里的所有消息，按 id 从小到大，也就是说话的先后顺序。'},{at:'public List<ChatSummary> list(int userId) {',to:'// 占用今天的一次提问：没到上限就加一并返回已用次数，到了上限返回空',text:'我的对话列表：LEFT JOIN 消息表再 GROUP BY，用 COUNT(m.id) 数出每段对话有几条消息；最近问过的排在前面。'},{at:'public String chatMessages(List<Message> messages, double temperature) {',to:'// 第 14 关的 chat 改成调用 chatMessages：评分和讲解不用改',text:'和原来的 chat 几乎一样，区别只有两处：messages 由调用方传进来，可以是任意多条；temperature 也由调用方决定。'},{at:'public String chat(String system, String user) {',to:'}',text:'原来的 chat 变成一层很薄的包装：把两个字符串拼成两条消息，temperature 传 0（评分要稳定）。两个方法共用一份发请求的代码。'},{at:'public Optional<Integer> takeQuota(int userId, int limit) {',to:'// 提问失败时把刚才占用的一次还回去',text:'“检查有没有超限”和“次数加一”必须是一步：如果先查再改，同一个人同时发两个请求，可能都查到“还剩 1 次”，结果都通过。这条 SQL 的意思是：今天还没有记录就插入 count = 1；已经有了（主键冲突）就改成 count + 1，但只在 count < 上限时才改。RETURNING count 让这条写入语句像查询一样返回改完的次数，所以用 queryForList 来执行；到了上限时一行都没改，列表是空的。'},{at:'public void refundQuota(int userId) {',to:'@Transactional',text:'大模型调用失败时把次数还回去。MAX(count - 1, 0) 保证不会变成负数。'},{at:'public int saveTurn(',to:'} else {',text:'新对话先插入 chats，再用 last_insert_rowid() 拿到数据库自动生成的 id，写法和第 13 关创建考试时一样。'},{at:'id = chatId;',to:'}',text:'已有的对话只更新“最后提问时间”，它决定历史列表的排序。'},{at:'jdbc.update("INSERT INTO chat_messages (chat_id, role, content) VALUES (?, \'user\', ?)", id, question);',to:'@Transactional',text:'一问一答两条消息一起存。因为方法上有 @Transactional，不会出现“存了问题没存回答”的半截数据。'},{at:'public boolean delete(int userId, int chatId) {',to:'return true;',text:'先确认这段对话是自己的，再删消息、删对话。先删消息是因为消息表引用了对话表。'}]}},node:{practice:{steps:['打开 src/ai/client.js，把 chat 函数换成 chatMessages 和新的 chat，补完 TODO 1、2，并改好最后一行的导出。','新建 src/db/chat.js，补完 TODO 3 到 7。','运行 node --test，确认已有单元测试都能通过（评分和讲解仍然用 chat，不应该受影响）。'],expect:'测试全部通过；下一个任务把它们用起来'},code:'// src/ai/client.js（只改 chat 函数这一段，上面的配置和 NotConfiguredError 不动）\n\n// 发送一整段对话（messages 数组），返回模型的回答\nasync function chatMessages(messages, temperature = 0.5) {\n  // TODO 1：把原来 chat 函数里的代码搬过来，正文改成 { model: MODEL, temperature, messages }\n}\n\n// 第 14 关的 chat 改成调用 chatMessages：评分和讲解不用改\nfunction chat(system, user) {\n  // TODO 2：调用 chatMessages，传入 system 和 user 两条消息，temperature 传 0\n}\n\nmodule.exports = { NotConfiguredError, chat, chatMessages };\n\n// src/db/chat.js\nconst { db } = require("./database");\n\ndb.exec(`\n  CREATE TABLE IF NOT EXISTS chats (\n    id          INTEGER PRIMARY KEY AUTOINCREMENT,\n    user_id     INTEGER NOT NULL REFERENCES users(id),\n    question_id INTEGER REFERENCES questions(id),\n    title       TEXT    NOT NULL,\n    updated_at  TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP\n  );\n  CREATE TABLE IF NOT EXISTS chat_messages (\n    id         INTEGER PRIMARY KEY AUTOINCREMENT,\n    chat_id    INTEGER NOT NULL REFERENCES chats(id),\n    role       TEXT    NOT NULL,\n    content    TEXT    NOT NULL,\n    created_at TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP\n  );\n  CREATE TABLE IF NOT EXISTS chat_usage (\n    user_id INTEGER NOT NULL REFERENCES users(id),\n    day     TEXT    NOT NULL,\n    count   INTEGER NOT NULL,\n    PRIMARY KEY (user_id, day)\n  );\n`);\n\nfunction getChat(userId, chatId) {\n  return db.prepare("SELECT id, question_id AS questionId, title FROM chats WHERE id = ? AND user_id = ?").get(chatId, userId);\n}\n\nfunction listMessages(chatId) {\n  return db\n    .prepare("SELECT role, content, created_at AS createdAt FROM chat_messages WHERE chat_id = ? ORDER BY id")\n    .all(chatId);\n}\n\nfunction listChats(userId) {\n  return db\n    .prepare(\n      `SELECT c.id, c.title, c.question_id AS questionId, c.updated_at AS updatedAt, COUNT(m.id) AS messages\n       FROM chats c LEFT JOIN chat_messages m ON m.chat_id = c.id\n       WHERE c.user_id = ? GROUP BY c.id ORDER BY c.updated_at DESC, c.id DESC`\n    )\n    .all(userId);\n}\n\n// 占用今天的一次提问：没到上限就加一并返回已用次数，到了上限返回 null\nfunction takeQuota(userId, limit) {\n  // TODO 3：一条 SQL 完成“没有今天的记录就插入 count = 1，有就在 count < limit 时加一”，用 RETURNING count 拿回新的次数；\n  //         到了上限时这条 SQL 不会改任何行，get() 得到 undefined，这时返回 null\n}\n\n// 提问失败时把刚才占用的一次还回去\nfunction refundQuota(userId) {\n  // TODO 4：把今天的 count 减一，用 MAX(count - 1, 0) 保证不会减成负数\n}\n\n// 保存一轮问答：chatId 为 null 时先新建对话。几条写入放在同一个事务里\nconst saveTurn = db.transaction((userId, chatId, questionId, title, question, reply) => {\n  // TODO 5：chatId 为 null 就插入一行 chats 并拿到新的 id；否则把这段对话的 updated_at 改成 CURRENT_TIMESTAMP\n  // TODO 6：往 chat_messages 插入两行：先是 user 的 question，再是 assistant 的 reply；最后返回 chatId\n});\n\n// 删除自己的一段对话（连同里面的消息），不是自己的返回 false\nconst deleteChat = db.transaction((userId, chatId) => {\n  // TODO 7：先用 getChat 确认是自己的，再删 chat_messages 里的消息，最后删 chats 里的这一行\n});\n\nmodule.exports = { getChat, listMessages, listChats, takeQuota, refundQuota, saveTurn, deleteChat };',explain:[{at:'// src/ai/client.js（只改 chat 函数这一段',text:'打开第 14 关写的 src/ai/client.js，把原来的 chat 函数换成下面两个函数，文件最后的导出也跟着改。',to:'// 发送一整段对话（messages 数组），返回模型的回答'},{at:'// src/db/chat.js',to:'db.exec(`',text:'新建数据访问层文件，专门负责对话相关的三张表。'},{at:'CREATE TABLE IF NOT EXISTS chats (',to:');',text:'chats 表：一段对话一行。user_id 是谁的对话；question_id 是针对哪道题问的，可以为空（不针对具体题目）；title 是显示在历史列表里的标题；updated_at 是最后一次提问的时间。'},{at:'CREATE TABLE IF NOT EXISTS chat_messages (',to:');',text:'chat_messages 表：对话里的每一句话一行。role 是 user（学生问的）或 assistant（AI 答的），和发给大模型的 messages 里的 role 一致。'},{at:'CREATE TABLE IF NOT EXISTS chat_usage (',to:'`);',text:'chat_usage 表：每个用户每天一行，count 是当天已经问了几次。联合主键保证同一个人同一天只有一行。次数单独记一张表，而不是去数消息：这样删除对话不会把次数“删回来”。'},{at:'function getChat(userId, chatId) {',to:'}',text:'按“对话 id + 用户 id”一起查：不是自己的对话就查不到，和不存在一样。AS questionId 把列名换成接口里用的驼峰写法。'},{at:'function listMessages(chatId) {',to:'}',text:'一段对话里的所有消息，按 id 从小到大，也就是说话的先后顺序。'},{at:'function listChats(userId) {',to:'// 占用今天的一次提问：没到上限就加一并返回已用次数，到了上限返回 null',text:'我的对话列表：LEFT JOIN 消息表再 GROUP BY，用 COUNT(m.id) 数出每段对话有几条消息；最近问过的排在前面。'},{at:'async function chatMessages(messages, temperature = 0.5) {',text:'新的函数：直接接收一整个 messages 数组。temperature 默认 0.5，聊天时回答可以活一点。要你补全。',to:'// 第 14 关的 chat 改成调用 chatMessages：评分和讲解不用改'},{at:'function chat(system, user) {',text:'保留原来的名字和参数，第 14 关的评分、讲解代码一行都不用改。要你补全。',to:'module.exports = { NotConfiguredError, chat, chatMessages };'},{at:'function takeQuota(userId, limit) {',text:'占用一次提问次数，要你补全。',to:'// 提问失败时把刚才占用的一次还回去'},{at:'function refundQuota(userId) {',text:'退回一次，要你补全。',to:'// 保存一轮问答：chatId 为 null 时先新建对话。几条写入放在同一个事务里'},{at:'const saveTurn = db.transaction(',text:'保存一问一答，要你补全。db.transaction 包起来的函数，里面的写入要么全部成功，要么全部不生效。',to:'// 删除自己的一段对话（连同里面的消息），不是自己的返回 false'},{at:'const deleteChat = db.transaction(',text:'删除对话，要你补全。',to:'});'},{at:'module.exports = { getChat,',text:'导出这一层的全部函数。'}],solution:{code:'// src/ai/client.js（只改 chat 函数这一段，上面的配置和 NotConfiguredError 不动）\n\n// 发送一整段对话（messages 数组），返回模型的回答\nasync function chatMessages(messages, temperature = 0.5) {\n  if (!API_KEY) throw new NotConfiguredError();\n  const res = await fetch(`${BASE_URL}/chat/completions`, {\n    method: "POST",\n    headers: { Authorization: `Bearer ${API_KEY}`, "Content-Type": "application/json" },\n    body: JSON.stringify({ model: MODEL, temperature, messages }),\n    signal: AbortSignal.timeout(30000),\n  });\n  if (!res.ok) throw new Error(`AI 服务返回状态码 ${res.status}`);\n  const data = await res.json();\n  const content = data.choices?.[0]?.message?.content;\n  if (typeof content !== "string") throw new Error("AI 服务没有返回内容");\n  return content;\n}\n\n// 第 14 关的 chat 改成调用 chatMessages：评分和讲解不用改\nfunction chat(system, user) {\n  return chatMessages([\n    { role: "system", content: system },\n    { role: "user", content: user },\n  ], 0);\n}\n\nmodule.exports = { NotConfiguredError, chat, chatMessages };\n\n// src/db/chat.js\nconst { db } = require("./database");\n\ndb.exec(`\n  CREATE TABLE IF NOT EXISTS chats (\n    id          INTEGER PRIMARY KEY AUTOINCREMENT,\n    user_id     INTEGER NOT NULL REFERENCES users(id),\n    question_id INTEGER REFERENCES questions(id),\n    title       TEXT    NOT NULL,\n    updated_at  TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP\n  );\n  CREATE TABLE IF NOT EXISTS chat_messages (\n    id         INTEGER PRIMARY KEY AUTOINCREMENT,\n    chat_id    INTEGER NOT NULL REFERENCES chats(id),\n    role       TEXT    NOT NULL,\n    content    TEXT    NOT NULL,\n    created_at TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP\n  );\n  CREATE TABLE IF NOT EXISTS chat_usage (\n    user_id INTEGER NOT NULL REFERENCES users(id),\n    day     TEXT    NOT NULL,\n    count   INTEGER NOT NULL,\n    PRIMARY KEY (user_id, day)\n  );\n`);\n\nfunction getChat(userId, chatId) {\n  return db.prepare("SELECT id, question_id AS questionId, title FROM chats WHERE id = ? AND user_id = ?").get(chatId, userId);\n}\n\nfunction listMessages(chatId) {\n  return db\n    .prepare("SELECT role, content, created_at AS createdAt FROM chat_messages WHERE chat_id = ? ORDER BY id")\n    .all(chatId);\n}\n\nfunction listChats(userId) {\n  return db\n    .prepare(\n      `SELECT c.id, c.title, c.question_id AS questionId, c.updated_at AS updatedAt, COUNT(m.id) AS messages\n       FROM chats c LEFT JOIN chat_messages m ON m.chat_id = c.id\n       WHERE c.user_id = ? GROUP BY c.id ORDER BY c.updated_at DESC, c.id DESC`\n    )\n    .all(userId);\n}\n\n// 占用今天的一次提问：没到上限就加一并返回已用次数，到了上限返回 null\nfunction takeQuota(userId, limit) {\n  const row = db\n    .prepare(\n      `INSERT INTO chat_usage (user_id, day, count) VALUES (?, date(\'now\'), 1)\n       ON CONFLICT (user_id, day) DO UPDATE SET count = count + 1 WHERE count < ?\n       RETURNING count`\n    )\n    .get(userId, limit);\n  return row ? row.count : null;\n}\n\n// 提问失败时把刚才占用的一次还回去\nfunction refundQuota(userId) {\n  db.prepare("UPDATE chat_usage SET count = MAX(count - 1, 0) WHERE user_id = ? AND day = date(\'now\')").run(userId);\n}\n\n// 保存一轮问答：chatId 为 null 时先新建对话。几条写入放在同一个事务里\nconst saveTurn = db.transaction((userId, chatId, questionId, title, question, reply) => {\n  if (chatId === null) {\n    const info = db.prepare("INSERT INTO chats (user_id, question_id, title) VALUES (?, ?, ?)").run(userId, questionId, title);\n    chatId = Number(info.lastInsertRowid);\n  } else {\n    db.prepare("UPDATE chats SET updated_at = CURRENT_TIMESTAMP WHERE id = ?").run(chatId);\n  }\n  const insert = db.prepare("INSERT INTO chat_messages (chat_id, role, content) VALUES (?, ?, ?)");\n  insert.run(chatId, "user", question);\n  insert.run(chatId, "assistant", reply);\n  return chatId;\n});\n\n// 删除自己的一段对话（连同里面的消息），不是自己的返回 false\nconst deleteChat = db.transaction((userId, chatId) => {\n  if (!getChat(userId, chatId)) return false;\n  db.prepare("DELETE FROM chat_messages WHERE chat_id = ?").run(chatId);\n  db.prepare("DELETE FROM chats WHERE id = ?").run(chatId);\n  return true;\n});\n\nmodule.exports = { getChat, listMessages, listChats, takeQuota, refundQuota, saveTurn, deleteChat };',explain:[{at:'// src/ai/client.js（只改 chat 函数这一段',text:'打开第 14 关写的 src/ai/client.js，把原来的 chat 函数换成下面两个函数，文件最后的导出也跟着改。',to:'// 发送一整段对话（messages 数组），返回模型的回答'},{at:'// src/db/chat.js',to:'db.exec(`',text:'新建数据访问层文件，专门负责对话相关的三张表。'},{at:'CREATE TABLE IF NOT EXISTS chats (',to:');',text:'chats 表：一段对话一行。user_id 是谁的对话；question_id 是针对哪道题问的，可以为空（不针对具体题目）；title 是显示在历史列表里的标题；updated_at 是最后一次提问的时间。'},{at:'CREATE TABLE IF NOT EXISTS chat_messages (',to:');',text:'chat_messages 表：对话里的每一句话一行。role 是 user（学生问的）或 assistant（AI 答的），和发给大模型的 messages 里的 role 一致。'},{at:'CREATE TABLE IF NOT EXISTS chat_usage (',to:'`);',text:'chat_usage 表：每个用户每天一行，count 是当天已经问了几次。联合主键保证同一个人同一天只有一行。次数单独记一张表，而不是去数消息：这样删除对话不会把次数“删回来”。'},{at:'function getChat(userId, chatId) {',to:'}',text:'按“对话 id + 用户 id”一起查：不是自己的对话就查不到，和不存在一样。AS questionId 把列名换成接口里用的驼峰写法。'},{at:'function listMessages(chatId) {',to:'}',text:'一段对话里的所有消息，按 id 从小到大，也就是说话的先后顺序。'},{at:'function listChats(userId) {',to:'// 占用今天的一次提问：没到上限就加一并返回已用次数，到了上限返回 null',text:'我的对话列表：LEFT JOIN 消息表再 GROUP BY，用 COUNT(m.id) 数出每段对话有几条消息；最近问过的排在前面。'},{at:'async function chatMessages(messages, temperature = 0.5) {',to:'// 第 14 关的 chat 改成调用 chatMessages：评分和讲解不用改',text:'和原来的 chat 几乎一样，区别只有两处：messages 由调用方传进来，可以是任意多条；temperature 也由调用方决定。'},{at:'function chat(system, user) {',to:'], 0);',text:'原来的 chat 变成一层很薄的包装：把两个字符串拼成两条消息，temperature 传 0（评分要稳定）。这样两个函数共用一份发请求的代码。'},{at:'module.exports = { NotConfiguredError, chat, chatMessages };',text:'多导出一个 chatMessages。'},{at:'function takeQuota(userId, limit) {',to:'// 提问失败时把刚才占用的一次还回去',text:'“检查有没有超限”和“次数加一”必须是一步：如果先查再改，同一个人同时发两个请求，可能都查到“还剩 1 次”，结果都通过。这条 SQL 的意思是：今天还没有记录就插入 count = 1；已经有了（主键冲突）就改成 count + 1，但只在 count < 上限时才改。RETURNING count 把改完的次数拿回来；到了上限时一行都没改，get() 得到 undefined。'},{at:'function refundQuota(userId) {',to:'// 保存一轮问答：chatId 为 null 时先新建对话。几条写入放在同一个事务里',text:'大模型调用失败时把次数还回去。MAX(count - 1, 0) 保证不会变成负数。'},{at:'const saveTurn = db.transaction(',to:'} else {',text:'新对话先插入 chats，lastInsertRowid 是数据库自动生成的 id。'},{at:'db.prepare("UPDATE chats SET updated_at = CURRENT_TIMESTAMP WHERE id = ?").run(chatId);',text:'已有的对话只更新“最后提问时间”，它决定历史列表的排序。',to:'}'},{at:'const insert = db.prepare("INSERT INTO chat_messages',to:'// 删除自己的一段对话（连同里面的消息），不是自己的返回 false',text:'一问一答两条消息一起存。因为在同一个事务里，不会出现“存了问题没存回答”的半截数据。'},{at:'const deleteChat = db.transaction(',to:'});',text:'先确认这段对话是自己的，再删消息、删对话。先删消息是因为消息表引用了对话表。'},{at:'module.exports = { getChat,',text:'导出这一层的全部函数。'}]}},python:{practice:{steps:['打开 app/ai_client.py，把 chat 函数换成 chat_messages 和新的 chat，补完 TODO 1、2。','在 app/database.py 的 SCHEMA 里加上三张表，新建 app/chat.py，补完 TODO 3 到 6。','运行 python -m pytest，确认原来的评分和讲解测试还能通过。'],expect:'测试全部通过；下一个任务把它们用起来'},code:'# app/ai_client.py（只改 chat 函数这一段，上面的配置和 NotConfigured 不动）\n\ndef chat_messages(messages, temperature=0.5):\n    """发送一整段对话（messages 列表），返回模型的回答"""\n    # TODO 1：把原来 chat 函数里的代码搬过来，json 改成 {"model": MODEL, "temperature": temperature, "messages": messages}\n\n\ndef chat(system, user):\n    """第 14 关的 chat 改成调用 chat_messages：评分和讲解不用改"""\n    # TODO 2：调用 chat_messages，传入 system 和 user 两条消息，temperature 传 0\n\n# app/database.py（在 SCHEMA 字符串的最后，三个引号之前，加上这三张表）\nCREATE TABLE IF NOT EXISTS chats (\n    id          INTEGER PRIMARY KEY AUTOINCREMENT,\n    user_id     INTEGER NOT NULL REFERENCES users(id),\n    question_id INTEGER REFERENCES questions(id),\n    title       TEXT    NOT NULL,\n    updated_at  TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\nCREATE TABLE IF NOT EXISTS chat_messages (\n    id         INTEGER PRIMARY KEY AUTOINCREMENT,\n    chat_id    INTEGER NOT NULL REFERENCES chats(id),\n    role       TEXT    NOT NULL,\n    content    TEXT    NOT NULL,\n    created_at TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\nCREATE TABLE IF NOT EXISTS chat_usage (\n    user_id INTEGER NOT NULL REFERENCES users(id),\n    day     TEXT    NOT NULL,\n    count   INTEGER NOT NULL,\n    PRIMARY KEY (user_id, day)\n);\n\n# app/chat.py\nfrom contextlib import closing\n\nfrom app.database import connect, query_all, query_one\n\n\ndef get_chat(user_id, chat_id):\n    """某个用户的一段对话；不是这个用户的也当作不存在（返回 None）"""\n    return query_one(\n        "SELECT id, question_id AS questionId, title FROM chats WHERE id = ? AND user_id = ?", (chat_id, user_id)\n    )\n\n\ndef list_messages(chat_id):\n    return query_all(\n        "SELECT role, content, created_at AS createdAt FROM chat_messages WHERE chat_id = ? ORDER BY id", (chat_id,)\n    )\n\n\ndef list_chats(user_id):\n    return query_all(\n        "SELECT c.id, c.title, c.question_id AS questionId, c.updated_at AS updatedAt, COUNT(m.id) AS messages "\n        "FROM chats c LEFT JOIN chat_messages m ON m.chat_id = c.id "\n        "WHERE c.user_id = ? GROUP BY c.id ORDER BY c.updated_at DESC, c.id DESC",\n        (user_id,),\n    )\n\n\ndef take_quota(user_id, limit):\n    """占用今天的一次提问：没到上限就加一并返回已用次数，到了上限返回 None"""\n    # TODO 3：一条 SQL 完成“没有今天的记录就插入 count = 1，有就在 count < limit 时加一”，用 RETURNING count 拿回新的次数；\n    #         到了上限时这条 SQL 不会改任何行，fetchone() 得到 None。记得用 with conn 提交\n\n\ndef refund_quota(user_id):\n    """提问失败时把刚才占用的一次还回去"""\n    # TODO 4：把今天的 count 减一，用 MAX(count - 1, 0) 保证不会减成负数\n\n\ndef save_turn(user_id, chat_id, question_id, title, question, reply):\n    """保存一轮问答：chat_id 为 None 时先新建对话。几条写入放在同一个事务里"""\n    # TODO 5：在同一个 with conn 里：chat_id 为 None 就插入一行 chats 并用 lastrowid 拿到新的 id，否则更新 updated_at；\n    #         再往 chat_messages 插入两行（先 user 的 question，再 assistant 的 reply）；最后返回 chat_id\n\n\ndef delete_chat(user_id, chat_id):\n    """删除自己的一段对话（连同里面的消息），不是自己的返回 False"""\n    # TODO 6：在同一个 with conn 里：先确认这段对话是 user_id 的，不是就返回 False；再删消息、删对话，返回 True\n',explain:[{at:'# app/ai_client.py（只改 chat 函数这一段',text:'打开第 14 关写的 app/ai_client.py，把原来的 chat 函数换成下面两个函数。'},{at:'# app/database.py（在 SCHEMA 字符串的最后',text:'打开 app/database.py，把下面三张表的建表语句加到 SCHEMA 里。启动时 init_db 会执行整个 SCHEMA，表不存在就新建。'},{at:'CREATE TABLE IF NOT EXISTS chats (',to:');',text:'chats 表：一段对话一行。user_id 是谁的对话；question_id 是针对哪道题问的，可以为空（不针对具体题目）；title 是显示在历史列表里的标题；updated_at 是最后一次提问的时间。'},{at:'CREATE TABLE IF NOT EXISTS chat_messages (',to:');',text:'chat_messages 表：对话里的每一句话一行。role 是 user（学生问的）或 assistant（AI 答的），和发给大模型的 messages 里的 role 一致。'},{at:'CREATE TABLE IF NOT EXISTS chat_usage (',to:');',text:'chat_usage 表：每个用户每天一行，count 是当天已经问了几次。联合主键保证同一个人同一天只有一行。次数单独记一张表，而不是去数消息：这样删除对话不会把次数“删回来”。'},{at:'# app/chat.py',to:'from app.database import connect, query_all, query_one',text:'新建数据访问层文件，专门负责对话相关的三张表。'},{at:'def get_chat(user_id, chat_id):',to:'"SELECT id, question_id AS questionId, title FROM chats WHERE id = ? AND user_id = ?", (chat_id, user_id)',text:'按“对话 id + 用户 id”一起查：不是自己的对话就查不到，和不存在一样。AS questionId 把列名换成接口里用的驼峰写法。'},{at:'def list_messages(chat_id):',to:'"SELECT role, content, created_at AS createdAt FROM chat_messages WHERE chat_id = ? ORDER BY id", (chat_id,)',text:'一段对话里的所有消息，按 id 从小到大，也就是说话的先后顺序。'},{at:'def list_chats(user_id):',to:'(user_id,),',text:'我的对话列表：LEFT JOIN 消息表再 GROUP BY，用 COUNT(m.id) 数出每段对话有几条消息；最近问过的排在前面。'},{at:'def chat_messages(messages, temperature=0.5):',text:'新的函数：直接接收一整个 messages 列表。temperature 默认 0.5，聊天时回答可以活一点。要你补全。',to:'# TODO 1：把原来 chat 函数里的代码搬过来，json 改成 {"model": MODEL, "temperature": temperature, "messages": messages}'},{at:'def chat(system, user):',text:'保留原来的名字和参数，第 14 关的评分、讲解代码一行都不用改。要你补全。',to:'# TODO 2：调用 chat_messages，传入 system 和 user 两条消息，temperature 传 0'},{at:'def take_quota(user_id, limit):',text:'占用一次提问次数，要你补全。',to:'#         到了上限时这条 SQL 不会改任何行，fetchone() 得到 None。记得用 with conn 提交'},{at:'def refund_quota(user_id):',text:'退回一次，要你补全。',to:'# TODO 4：把今天的 count 减一，用 MAX(count - 1, 0) 保证不会减成负数'},{at:'def save_turn(user_id, chat_id, question_id, title, question, reply):',text:'保存一问一答，要你补全。',to:'#         再往 chat_messages 插入两行（先 user 的 question，再 assistant 的 reply）；最后返回 chat_id'},{at:'def delete_chat(user_id, chat_id):',text:'删除对话，要你补全。',to:'# TODO 6：在同一个 with conn 里：先确认这段对话是 user_id 的，不是就返回 False；再删消息、删对话，返回 True'}],solution:{code:'# app/ai_client.py（只改 chat 函数这一段，上面的配置和 NotConfigured 不动）\n\ndef chat_messages(messages, temperature=0.5):\n    """发送一整段对话（messages 列表），返回模型的回答"""\n    if not API_KEY:\n        raise NotConfigured("AI 评分还没有配置")\n    response = httpx.post(\n        f"{BASE_URL}/chat/completions",\n        headers={"Authorization": f"Bearer {API_KEY}"},\n        json={"model": MODEL, "temperature": temperature, "messages": messages},\n        timeout=30,\n    )\n    response.raise_for_status()\n    content = response.json()["choices"][0]["message"]["content"]\n    if not isinstance(content, str):\n        raise ValueError("AI 服务没有返回内容")\n    return content\n\n\ndef chat(system, user):\n    """第 14 关的 chat 改成调用 chat_messages：评分和讲解不用改"""\n    return chat_messages([{"role": "system", "content": system}, {"role": "user", "content": user}], 0)\n\n# app/database.py（在 SCHEMA 字符串的最后，三个引号之前，加上这三张表）\nCREATE TABLE IF NOT EXISTS chats (\n    id          INTEGER PRIMARY KEY AUTOINCREMENT,\n    user_id     INTEGER NOT NULL REFERENCES users(id),\n    question_id INTEGER REFERENCES questions(id),\n    title       TEXT    NOT NULL,\n    updated_at  TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\nCREATE TABLE IF NOT EXISTS chat_messages (\n    id         INTEGER PRIMARY KEY AUTOINCREMENT,\n    chat_id    INTEGER NOT NULL REFERENCES chats(id),\n    role       TEXT    NOT NULL,\n    content    TEXT    NOT NULL,\n    created_at TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\nCREATE TABLE IF NOT EXISTS chat_usage (\n    user_id INTEGER NOT NULL REFERENCES users(id),\n    day     TEXT    NOT NULL,\n    count   INTEGER NOT NULL,\n    PRIMARY KEY (user_id, day)\n);\n\n# app/chat.py\nfrom contextlib import closing\n\nfrom app.database import connect, query_all, query_one\n\n\ndef get_chat(user_id, chat_id):\n    """某个用户的一段对话；不是这个用户的也当作不存在（返回 None）"""\n    return query_one(\n        "SELECT id, question_id AS questionId, title FROM chats WHERE id = ? AND user_id = ?", (chat_id, user_id)\n    )\n\n\ndef list_messages(chat_id):\n    return query_all(\n        "SELECT role, content, created_at AS createdAt FROM chat_messages WHERE chat_id = ? ORDER BY id", (chat_id,)\n    )\n\n\ndef list_chats(user_id):\n    return query_all(\n        "SELECT c.id, c.title, c.question_id AS questionId, c.updated_at AS updatedAt, COUNT(m.id) AS messages "\n        "FROM chats c LEFT JOIN chat_messages m ON m.chat_id = c.id "\n        "WHERE c.user_id = ? GROUP BY c.id ORDER BY c.updated_at DESC, c.id DESC",\n        (user_id,),\n    )\n\n\ndef take_quota(user_id, limit):\n    """占用今天的一次提问：没到上限就加一并返回已用次数，到了上限返回 None"""\n    with closing(connect()) as conn:\n        with conn:\n            row = conn.execute(\n                "INSERT INTO chat_usage (user_id, day, count) VALUES (?, date(\'now\'), 1) "\n                "ON CONFLICT (user_id, day) DO UPDATE SET count = count + 1 WHERE count < ? "\n                "RETURNING count",\n                (user_id, limit),\n            ).fetchone()\n    return row["count"] if row else None\n\n\ndef refund_quota(user_id):\n    """提问失败时把刚才占用的一次还回去"""\n    with closing(connect()) as conn:\n        with conn:\n            conn.execute(\n                "UPDATE chat_usage SET count = MAX(count - 1, 0) WHERE user_id = ? AND day = date(\'now\')", (user_id,)\n            )\n\n\ndef save_turn(user_id, chat_id, question_id, title, question, reply):\n    """保存一轮问答：chat_id 为 None 时先新建对话。几条写入放在同一个事务里"""\n    with closing(connect()) as conn:\n        with conn:\n            if chat_id is None:\n                chat_id = conn.execute(\n                    "INSERT INTO chats (user_id, question_id, title) VALUES (?, ?, ?)", (user_id, question_id, title)\n                ).lastrowid\n            else:\n                conn.execute("UPDATE chats SET updated_at = CURRENT_TIMESTAMP WHERE id = ?", (chat_id,))\n            conn.executemany(\n                "INSERT INTO chat_messages (chat_id, role, content) VALUES (?, ?, ?)",\n                [(chat_id, "user", question), (chat_id, "assistant", reply)],\n            )\n    return chat_id\n\n\ndef delete_chat(user_id, chat_id):\n    """删除自己的一段对话（连同里面的消息），不是自己的返回 False"""\n    with closing(connect()) as conn:\n        with conn:\n            owned = conn.execute("SELECT 1 FROM chats WHERE id = ? AND user_id = ?", (chat_id, user_id)).fetchone()\n            if owned is None:\n                return False\n            conn.execute("DELETE FROM chat_messages WHERE chat_id = ?", (chat_id,))\n            conn.execute("DELETE FROM chats WHERE id = ?", (chat_id,))\n    return True\n',explain:[{at:'# app/ai_client.py（只改 chat 函数这一段',text:'打开第 14 关写的 app/ai_client.py，把原来的 chat 函数换成下面两个函数。'},{at:'# app/database.py（在 SCHEMA 字符串的最后',text:'打开 app/database.py，把下面三张表的建表语句加到 SCHEMA 里。启动时 init_db 会执行整个 SCHEMA，表不存在就新建。'},{at:'CREATE TABLE IF NOT EXISTS chats (',to:');',text:'chats 表：一段对话一行。user_id 是谁的对话；question_id 是针对哪道题问的，可以为空（不针对具体题目）；title 是显示在历史列表里的标题；updated_at 是最后一次提问的时间。'},{at:'CREATE TABLE IF NOT EXISTS chat_messages (',to:');',text:'chat_messages 表：对话里的每一句话一行。role 是 user（学生问的）或 assistant（AI 答的），和发给大模型的 messages 里的 role 一致。'},{at:'CREATE TABLE IF NOT EXISTS chat_usage (',to:');',text:'chat_usage 表：每个用户每天一行，count 是当天已经问了几次。联合主键保证同一个人同一天只有一行。次数单独记一张表，而不是去数消息：这样删除对话不会把次数“删回来”。'},{at:'# app/chat.py',to:'from app.database import connect, query_all, query_one',text:'新建数据访问层文件，专门负责对话相关的三张表。'},{at:'def get_chat(user_id, chat_id):',to:'"SELECT id, question_id AS questionId, title FROM chats WHERE id = ? AND user_id = ?", (chat_id, user_id)',text:'按“对话 id + 用户 id”一起查：不是自己的对话就查不到，和不存在一样。AS questionId 把列名换成接口里用的驼峰写法。'},{at:'def list_messages(chat_id):',to:'"SELECT role, content, created_at AS createdAt FROM chat_messages WHERE chat_id = ? ORDER BY id", (chat_id,)',text:'一段对话里的所有消息，按 id 从小到大，也就是说话的先后顺序。'},{at:'def list_chats(user_id):',to:'(user_id,),',text:'我的对话列表：LEFT JOIN 消息表再 GROUP BY，用 COUNT(m.id) 数出每段对话有几条消息；最近问过的排在前面。'},{at:'def chat_messages(messages, temperature=0.5):',to:'return content',text:'和原来的 chat 几乎一样，区别只有两处：messages 由调用方传进来，可以是任意多条；temperature 也由调用方决定。'},{at:'def chat(system, user):',to:'return chat_messages(',text:'原来的 chat 变成一层很薄的包装：把两个字符串拼成两条消息，temperature 传 0（评分要稳定）。这样两个函数共用一份发请求的代码。'},{at:'def take_quota(user_id, limit):',to:'return row["count"] if row else None',text:'“检查有没有超限”和“次数加一”必须是一步：如果先查再改，同一个人同时发两个请求，可能都查到“还剩 1 次”，结果都通过。这条 SQL 的意思是：今天还没有记录就插入 count = 1；已经有了（主键冲突）就改成 count + 1，但只在 count < 上限时才改。RETURNING count 把改完的次数拿回来；到了上限时一行都没改，fetchone() 得到 None。with conn 负责提交。'},{at:'def refund_quota(user_id):',to:'"UPDATE chat_usage SET count = MAX(count - 1, 0) WHERE user_id = ? AND day = date(\'now\')", (user_id,)',text:'大模型调用失败时把次数还回去。MAX(count - 1, 0) 保证不会变成负数。'},{at:'def save_turn(user_id, chat_id, question_id, title, question, reply):',to:'else:',text:'新对话先插入 chats，lastrowid 是数据库自动生成的 id。'},{at:'conn.execute("UPDATE chats SET updated_at = CURRENT_TIMESTAMP WHERE id = ?", (chat_id,))',text:'已有的对话只更新“最后提问时间”，它决定历史列表的排序。'},{at:'conn.executemany(',to:'return chat_id',text:'一问一答两条消息一起存。因为都在同一个 with conn 里，是一个事务，不会出现“存了问题没存回答”的半截数据。'},{at:'def delete_chat(user_id, chat_id):',to:'return True',text:'先确认这段对话是自己的，再删消息、删对话，三步在同一个事务里。先删消息是因为消息表引用了对话表。'}]}}}},
  {title:'任务二：对话的业务逻辑和五个接口',body:'业务逻辑层负责：校验消息、确认对话是自己的、取最近的历史、占用次数、拼 messages 调用模型、失败退回次数、成功才保存。接口层把它们挂到五个路径上。',variants:{go:{practice:{steps:['新建 internal/service/chat.go，补完 TODO 1 到 7。','新建 internal/handler/chat.go；在 handler.go 里加字段、参数和五条路由；在 main.go 里创建 ChatStore 和 ChatService 并传给 handler.New。','go vet ./... 没有报错后，设置好第 14 关的三个环境变量启动：go run .。登录后在浏览器控制台试一下：fetch("/api/chats",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({message:"你好"})}).then(r=>r.json()).then(console.log)'],expect:'{chatId: 1, reply: "……", remaining: 19}'},code:'// internal/service/chat.go\npackage service\n\nimport (\n    "errors"\n    "strings"\n    "unicode/utf8"\n\n    "zixishi/internal/ai"\n    "zixishi/internal/store"\n)\n\nvar (\n    ErrBadMessage    = errors.New("消息不能为空，最多 1000 个字")\n    ErrChatNotFound  = errors.New("对话不存在")\n    ErrQuotaExceeded = errors.New("今天的提问次数用完了，明天再来")\n)\n\nconst (\n    chatHistory = 10\n    tutorPrompt = "你是面试自习室的 AI 老师，学生是初学者。用简短、通俗的中文回答，必要时举一个小例子。"\n)\n\ntype ChatReply struct {\n    ChatID    int    `json:"chatId"`\n    Reply     string `json:"reply"`\n    Remaining int    `json:"remaining"`\n}\n\ntype ChatDetail struct {\n    store.Chat\n    Messages []store.ChatMessage `json:"messages"`\n}\n\ntype ChatService struct {\n    ai        *ai.Client\n    chats     *store.ChatStore\n    questions *store.QuestionStore\n    limit     int\n}\n\nfunc NewChatService(client *ai.Client, chats *store.ChatStore, questions *store.QuestionStore, limit int) *ChatService {\n    if limit < 1 {\n        limit = 20\n    }\n    return &ChatService{ai: client, chats: chats, questions: questions, limit: limit}\n}\n\n// systemPrompt 生成系统提示词：对话是针对某道题的，就把题目和参考答案也告诉模型。\nfunc (s *ChatService) systemPrompt(questionID *int) string {\n    if questionID == nil {\n        return tutorPrompt\n    }\n    q, err := s.questions.Get(*questionID)\n    if err != nil {\n        return tutorPrompt\n    }\n    return tutorPrompt + "\\n学生正在看这道题：" + q.Title + "\\n参考答案：" + q.Answer\n}\n\n// Send 提问：chatID 为 0 是开一段新对话，否则是在已有的对话里追问。\nfunc (s *ChatService) Send(userID, chatID int, questionID *int, message string) (ChatReply, error) {\n    // TODO 1：message 去掉首尾空白；为空或超过 1000 个字（utf8.RuneCountInString）返回 ErrBadMessage\n    // TODO 2：追问（chatID 不是 0）：用 s.chats.Get 确认是自己的对话，store.ErrNotFound 换成 ErrChatNotFound；\n    //         questionID 用对话里记的；history 取这段对话最近 chatHistory 条消息。\n    //         新对话：传了 questionID 就用 s.questions.Get 确认题目存在，出错直接返回\n    // TODO 3：s.chats.TakeQuota 占用一次，ok 为 false 说明今天用完了，返回 ErrQuotaExceeded\n    // TODO 4：拼出 []ai.Message：系统提示词、history 里的每一条、这次的问题；调用 s.ai.ChatMessages（temperature 0.5）。\n    //         失败时先 s.chats.RefundQuota 把次数还回去，再返回 aiError(err)（第 14 关写的函数）\n    // TODO 5：s.chats.SaveTurn 保存这一问一答（新对话的标题取问题的前 20 个字），返回 ChatReply\n    return ChatReply{}, nil\n}\n\nfunc (s *ChatService) List(userID int) ([]store.ChatSummary, error) {\n    return s.chats.List(userID)\n}\n\nfunc (s *ChatService) Detail(userID, chatID int) (ChatDetail, error) {\n    // TODO 6：对话不是自己的返回 ErrChatNotFound，否则返回对话信息加上全部消息\n    return ChatDetail{}, nil\n}\n\nfunc (s *ChatService) Delete(userID, chatID int) error {\n    // TODO 7：调用 s.chats.Delete，store.ErrNotFound 换成 ErrChatNotFound\n    return nil\n}\n\n// internal/handler/chat.go\npackage handler\n\nimport (\n    "encoding/json"\n    "errors"\n    "net/http"\n    "strconv"\n\n    "zixishi/internal/ai"\n    "zixishi/internal/service"\n    "zixishi/internal/store"\n)\n\n// chatError 把业务逻辑层的错误写成对应状态码的响应。\nfunc (h *Handler) chatError(w http.ResponseWriter, err error) {\n    status := http.StatusInternalServerError\n    switch {\n    case errors.Is(err, service.ErrBadMessage):\n        status = http.StatusBadRequest\n    case errors.Is(err, service.ErrChatNotFound):\n        status = http.StatusNotFound\n    case errors.Is(err, store.ErrNotFound):\n        writeJSON(w, http.StatusNotFound, map[string]string{"error": "题目不存在"})\n        return\n    case errors.Is(err, service.ErrQuotaExceeded):\n        status = http.StatusTooManyRequests\n    case errors.Is(err, ai.ErrNotConfigured):\n        status = http.StatusServiceUnavailable\n    case errors.Is(err, service.ErrAIFailed):\n        status = http.StatusBadGateway\n    default:\n        h.serverError(w, err)\n        return\n    }\n    writeJSON(w, status, map[string]string{"error": err.Error()})\n}\n\n// chatID 读取路径里的对话编号；不是正整数时当作对话不存在。\nfunc chatID(r *http.Request) (int, bool) {\n    id, err := strconv.Atoi(r.PathValue("id"))\n    return id, err == nil && id > 0\n}\n\nfunc (h *Handler) startChat(w http.ResponseWriter, r *http.Request) {\n    u, ok := h.requireUser(w, r)\n    if !ok {\n        return\n    }\n    var body struct {\n        QuestionID *int   `json:"questionId"`\n        Message    string `json:"message"`\n    }\n    json.NewDecoder(r.Body).Decode(&body)\n    reply, err := h.chats.Send(u.ID, 0, body.QuestionID, body.Message)\n    if err != nil {\n        h.chatError(w, err)\n        return\n    }\n    writeJSON(w, http.StatusCreated, reply)\n}\n\nfunc (h *Handler) followUpChat(w http.ResponseWriter, r *http.Request) {\n    u, ok := h.requireUser(w, r)\n    if !ok {\n        return\n    }\n    id, valid := chatID(r)\n    if !valid {\n        h.chatError(w, service.ErrChatNotFound)\n        return\n    }\n    var body struct {\n        Message string `json:"message"`\n    }\n    json.NewDecoder(r.Body).Decode(&body)\n    reply, err := h.chats.Send(u.ID, id, nil, body.Message)\n    if err != nil {\n        h.chatError(w, err)\n        return\n    }\n    writeJSON(w, http.StatusOK, reply)\n}\n\nfunc (h *Handler) listChats(w http.ResponseWriter, r *http.Request) {\n    u, ok := h.requireUser(w, r)\n    if !ok {\n        return\n    }\n    list, err := h.chats.List(u.ID)\n    if err != nil {\n        h.chatError(w, err)\n        return\n    }\n    writeJSON(w, http.StatusOK, list)\n}\n\nfunc (h *Handler) chatDetail(w http.ResponseWriter, r *http.Request) {\n    u, ok := h.requireUser(w, r)\n    if !ok {\n        return\n    }\n    id, valid := chatID(r)\n    if !valid {\n        h.chatError(w, service.ErrChatNotFound)\n        return\n    }\n    detail, err := h.chats.Detail(u.ID, id)\n    if err != nil {\n        h.chatError(w, err)\n        return\n    }\n    writeJSON(w, http.StatusOK, detail)\n}\n\nfunc (h *Handler) deleteChat(w http.ResponseWriter, r *http.Request) {\n    u, ok := h.requireUser(w, r)\n    if !ok {\n        return\n    }\n    id, valid := chatID(r)\n    if !valid {\n        h.chatError(w, service.ErrChatNotFound)\n        return\n    }\n    if err := h.chats.Delete(u.ID, id); err != nil {\n        h.chatError(w, err)\n        return\n    }\n    w.WriteHeader(http.StatusNoContent)\n}\n\n// 组装：internal/handler/handler.go 的 Handler 加一个字段 chats *service.ChatService，New 多接收一个参数 chats 并存起来；\n// Routes 里在 AI 接口后面注册这五条路由：\n    mux.HandleFunc("POST /api/chats", h.startChat)\n    mux.HandleFunc("POST /api/chats/{id}/messages", h.followUpChat)\n    mux.HandleFunc("GET /api/chats", h.listChats)\n    mux.HandleFunc("GET /api/chats/{id}", h.chatDetail)\n    mux.HandleFunc("DELETE /api/chats/{id}", h.deleteChat)\n\n// main.go：在 aiService 那一行后面创建对话的 store 和 service，再把 chats 传给 handler.New\n    cs, err := store.NewChatStore(qs.DB())\n    if err != nil {\n        log.Fatalf("创建对话表失败：%v", err)\n    }\n    chatLimit, _ := strconv.Atoi(os.Getenv("CHAT_DAILY_LIMIT"))\n    chats := service.NewChatService(aiClient, cs, qs, chatLimit)',explain:[{at:'// internal/service/chat.go',to:'var (',text:'业务逻辑层：用到任务一改好的 ai 包和刚写的对话数据访问层。'},{at:'ErrBadMessage    = errors.New("消息不能为空，最多 1000 个字")',to:'const (',text:'这一层自己的三种业务错误，处理请求的那一层按它们决定状态码。'},{at:'chatHistory = 10',text:'追问时最多带上最近 10 条历史消息（5 轮问答）。对话越长，每次发给模型的内容越多、越贵，所以只带最近的。10 是偶数，截出来的第一条正好是学生的提问。'},{at:'tutorPrompt = ',text:'AI 老师的系统提示词。',to:')'},{at:'type ChatReply struct {',to:'Messages []store.ChatMessage `json:"messages"`',text:'两个返回给前端的结构：一次提问的结果（对话编号、回答、今天还剩几次），以及对话详情（对话信息加全部消息）。'},{at:'type ChatService struct {',to:'// systemPrompt 生成系统提示词：对话是针对某道题的，就把题目和参考答案也告诉模型。',text:'ChatService 需要大模型客户端、对话和题目两个数据访问层，以及每日次数上限。上限没设置或不合法时用默认的 20。大模型按用量收费，不限制的话，一个人写个脚本循环提问就能把你的余额刷光。'},{at:'func (s *ChatService) systemPrompt(questionID *int) string {',to:'// Send 提问：chatID 为 0 是开一段新对话，否则是在已有的对话里追问。',text:'对话关联了题目时，把题目和参考答案拼进系统提示词，模型才知道学生在问哪道题。这些内容来自数据库，不是用户输入的，所以放在 system 消息里。'},{at:'func (s *ChatService) Send(userID, chatID int, questionID *int, message string) (ChatReply, error) {',text:'这一关的核心方法，要你补全。',to:'return ChatReply{}, nil'},{at:'func (s *ChatService) List(userID int) ([]store.ChatSummary, error) {',to:'}',text:'历史列表直接转给数据访问层。'},{at:'func (s *ChatService) Detail(userID, chatID int) (ChatDetail, error) {',text:'对话详情，要你补全。',to:'return ChatDetail{}, nil'},{at:'func (s *ChatService) Delete(userID, chatID int) error {',text:'删除对话，要你补全。',to:'}'},{at:'// internal/handler/chat.go',to:'// chatError 把业务逻辑层的错误写成对应状态码的响应。',text:'处理请求的这一层：只负责取参数、调用业务逻辑、把结果或错误变成 HTTP 响应。'},{at:'func (h *Handler) chatError(w http.ResponseWriter, err error) {',to:'// chatID 读取路径里的对话编号；不是正整数时当作对话不存在。',text:'错误和状态码的对照：消息不合法 400，对话或题目不存在 404，次数用完 429（请求太多），没配置密钥 503，大模型出错 502；其他意料之外的错误交给 serverError 返回 500。'},{at:'func chatID(r *http.Request) (int, bool) {',to:'}',text:'从路径里取对话编号。写成 /api/chats/abc 这种不是数字的，直接当作对话不存在。'},{at:'func (h *Handler) startChat(w http.ResponseWriter, r *http.Request) {',to:'writeJSON(w, http.StatusCreated, reply)',text:'开新对话：chatID 传 0，成功返回 201（新建了资源）。QuestionID 用指针，前端没传时是 nil。五个接口都要先登录，用户 id 只从会话里取。'},{at:'func (h *Handler) followUpChat(w http.ResponseWriter, r *http.Request) {',to:'writeJSON(w, http.StatusOK, reply)',text:'在已有对话里追问：对话编号来自路径，questionID 传 nil（用对话里记的）。'},{at:'func (h *Handler) listChats(w http.ResponseWriter, r *http.Request) {',to:'writeJSON(w, http.StatusOK, detail)',text:'历史列表和某段对话的详情。'},{at:'func (h *Handler) deleteChat(w http.ResponseWriter, r *http.Request) {',to:'w.WriteHeader(http.StatusNoContent)',text:'删除对话，成功返回 204，没有正文。'},{at:'// 组装：internal/handler/handler.go 的 Handler 加一个字段',to:'mux.HandleFunc("DELETE /api/chats/{id}", h.deleteChat)',text:'在 handler.go 里给 Handler 加上 chats 字段，New 函数多接收一个参数，再注册五条路由。'},{at:'// main.go：在 aiService 那一行后面创建对话的 store 和 service',to:'chats := service.NewChatService(aiClient, cs, qs, chatLimit)',text:'main.go 负责把各层接起来：建表、从环境变量 CHAT_DAILY_LIMIT 读每日次数（没设置时 Atoi 得到 0，NewChatService 会换成 20）、创建 ChatService，最后别忘了把 chats 传给 handler.New。'}],solution:{code:'// internal/service/chat.go\npackage service\n\nimport (\n    "errors"\n    "strings"\n    "unicode/utf8"\n\n    "zixishi/internal/ai"\n    "zixishi/internal/store"\n)\n\nvar (\n    ErrBadMessage    = errors.New("消息不能为空，最多 1000 个字")\n    ErrChatNotFound  = errors.New("对话不存在")\n    ErrQuotaExceeded = errors.New("今天的提问次数用完了，明天再来")\n)\n\nconst (\n    chatHistory = 10\n    tutorPrompt = "你是面试自习室的 AI 老师，学生是初学者。用简短、通俗的中文回答，必要时举一个小例子。"\n)\n\ntype ChatReply struct {\n    ChatID    int    `json:"chatId"`\n    Reply     string `json:"reply"`\n    Remaining int    `json:"remaining"`\n}\n\ntype ChatDetail struct {\n    store.Chat\n    Messages []store.ChatMessage `json:"messages"`\n}\n\ntype ChatService struct {\n    ai        *ai.Client\n    chats     *store.ChatStore\n    questions *store.QuestionStore\n    limit     int\n}\n\nfunc NewChatService(client *ai.Client, chats *store.ChatStore, questions *store.QuestionStore, limit int) *ChatService {\n    if limit < 1 {\n        limit = 20\n    }\n    return &ChatService{ai: client, chats: chats, questions: questions, limit: limit}\n}\n\n// systemPrompt 生成系统提示词：对话是针对某道题的，就把题目和参考答案也告诉模型。\nfunc (s *ChatService) systemPrompt(questionID *int) string {\n    if questionID == nil {\n        return tutorPrompt\n    }\n    q, err := s.questions.Get(*questionID)\n    if err != nil {\n        return tutorPrompt\n    }\n    return tutorPrompt + "\\n学生正在看这道题：" + q.Title + "\\n参考答案：" + q.Answer\n}\n\n// Send 提问：chatID 为 0 是开一段新对话，否则是在已有的对话里追问。\nfunc (s *ChatService) Send(userID, chatID int, questionID *int, message string) (ChatReply, error) {\n    text := strings.TrimSpace(message)\n    if text == "" || utf8.RuneCountInString(text) > 1000 {\n        return ChatReply{}, ErrBadMessage\n    }\n    var history []store.ChatMessage\n    if chatID != 0 {\n        chat, err := s.chats.Get(userID, chatID)\n        if errors.Is(err, store.ErrNotFound) {\n            return ChatReply{}, ErrChatNotFound\n        }\n        if err != nil {\n            return ChatReply{}, err\n        }\n        questionID = chat.QuestionID\n        if history, err = s.chats.Messages(chatID); err != nil {\n            return ChatReply{}, err\n        }\n        if len(history) > chatHistory {\n            history = history[len(history)-chatHistory:]\n        }\n    } else if questionID != nil {\n        if _, err := s.questions.Get(*questionID); err != nil {\n            return ChatReply{}, err\n        }\n    }\n    used, ok, err := s.chats.TakeQuota(userID, s.limit)\n    if err != nil {\n        return ChatReply{}, err\n    }\n    if !ok {\n        return ChatReply{}, ErrQuotaExceeded\n    }\n    messages := []ai.Message{{Role: "system", Content: s.systemPrompt(questionID)}}\n    for _, m := range history {\n        messages = append(messages, ai.Message{Role: m.Role, Content: m.Content})\n    }\n    messages = append(messages, ai.Message{Role: "user", Content: text})\n    reply, err := s.ai.ChatMessages(messages, 0.5)\n    if err != nil {\n        s.chats.RefundQuota(userID)\n        return ChatReply{}, aiError(err)\n    }\n    reply = strings.TrimSpace(reply)\n    title := []rune(text)\n    if len(title) > 20 {\n        title = title[:20]\n    }\n    id, err := s.chats.SaveTurn(userID, chatID, questionID, string(title), text, reply)\n    if err != nil {\n        return ChatReply{}, err\n    }\n    return ChatReply{ChatID: id, Reply: reply, Remaining: s.limit - used}, nil\n}\n\nfunc (s *ChatService) List(userID int) ([]store.ChatSummary, error) {\n    return s.chats.List(userID)\n}\n\nfunc (s *ChatService) Detail(userID, chatID int) (ChatDetail, error) {\n    chat, err := s.chats.Get(userID, chatID)\n    if errors.Is(err, store.ErrNotFound) {\n        return ChatDetail{}, ErrChatNotFound\n    }\n    if err != nil {\n        return ChatDetail{}, err\n    }\n    messages, err := s.chats.Messages(chatID)\n    return ChatDetail{Chat: chat, Messages: messages}, err\n}\n\nfunc (s *ChatService) Delete(userID, chatID int) error {\n    if err := s.chats.Delete(userID, chatID); errors.Is(err, store.ErrNotFound) {\n        return ErrChatNotFound\n    } else {\n        return err\n    }\n}\n\n// internal/handler/chat.go\npackage handler\n\nimport (\n    "encoding/json"\n    "errors"\n    "net/http"\n    "strconv"\n\n    "zixishi/internal/ai"\n    "zixishi/internal/service"\n    "zixishi/internal/store"\n)\n\n// chatError 把业务逻辑层的错误写成对应状态码的响应。\nfunc (h *Handler) chatError(w http.ResponseWriter, err error) {\n    status := http.StatusInternalServerError\n    switch {\n    case errors.Is(err, service.ErrBadMessage):\n        status = http.StatusBadRequest\n    case errors.Is(err, service.ErrChatNotFound):\n        status = http.StatusNotFound\n    case errors.Is(err, store.ErrNotFound):\n        writeJSON(w, http.StatusNotFound, map[string]string{"error": "题目不存在"})\n        return\n    case errors.Is(err, service.ErrQuotaExceeded):\n        status = http.StatusTooManyRequests\n    case errors.Is(err, ai.ErrNotConfigured):\n        status = http.StatusServiceUnavailable\n    case errors.Is(err, service.ErrAIFailed):\n        status = http.StatusBadGateway\n    default:\n        h.serverError(w, err)\n        return\n    }\n    writeJSON(w, status, map[string]string{"error": err.Error()})\n}\n\n// chatID 读取路径里的对话编号；不是正整数时当作对话不存在。\nfunc chatID(r *http.Request) (int, bool) {\n    id, err := strconv.Atoi(r.PathValue("id"))\n    return id, err == nil && id > 0\n}\n\nfunc (h *Handler) startChat(w http.ResponseWriter, r *http.Request) {\n    u, ok := h.requireUser(w, r)\n    if !ok {\n        return\n    }\n    var body struct {\n        QuestionID *int   `json:"questionId"`\n        Message    string `json:"message"`\n    }\n    json.NewDecoder(r.Body).Decode(&body)\n    reply, err := h.chats.Send(u.ID, 0, body.QuestionID, body.Message)\n    if err != nil {\n        h.chatError(w, err)\n        return\n    }\n    writeJSON(w, http.StatusCreated, reply)\n}\n\nfunc (h *Handler) followUpChat(w http.ResponseWriter, r *http.Request) {\n    u, ok := h.requireUser(w, r)\n    if !ok {\n        return\n    }\n    id, valid := chatID(r)\n    if !valid {\n        h.chatError(w, service.ErrChatNotFound)\n        return\n    }\n    var body struct {\n        Message string `json:"message"`\n    }\n    json.NewDecoder(r.Body).Decode(&body)\n    reply, err := h.chats.Send(u.ID, id, nil, body.Message)\n    if err != nil {\n        h.chatError(w, err)\n        return\n    }\n    writeJSON(w, http.StatusOK, reply)\n}\n\nfunc (h *Handler) listChats(w http.ResponseWriter, r *http.Request) {\n    u, ok := h.requireUser(w, r)\n    if !ok {\n        return\n    }\n    list, err := h.chats.List(u.ID)\n    if err != nil {\n        h.chatError(w, err)\n        return\n    }\n    writeJSON(w, http.StatusOK, list)\n}\n\nfunc (h *Handler) chatDetail(w http.ResponseWriter, r *http.Request) {\n    u, ok := h.requireUser(w, r)\n    if !ok {\n        return\n    }\n    id, valid := chatID(r)\n    if !valid {\n        h.chatError(w, service.ErrChatNotFound)\n        return\n    }\n    detail, err := h.chats.Detail(u.ID, id)\n    if err != nil {\n        h.chatError(w, err)\n        return\n    }\n    writeJSON(w, http.StatusOK, detail)\n}\n\nfunc (h *Handler) deleteChat(w http.ResponseWriter, r *http.Request) {\n    u, ok := h.requireUser(w, r)\n    if !ok {\n        return\n    }\n    id, valid := chatID(r)\n    if !valid {\n        h.chatError(w, service.ErrChatNotFound)\n        return\n    }\n    if err := h.chats.Delete(u.ID, id); err != nil {\n        h.chatError(w, err)\n        return\n    }\n    w.WriteHeader(http.StatusNoContent)\n}\n\n// 组装：internal/handler/handler.go 的 Handler 加一个字段 chats *service.ChatService，New 多接收一个参数 chats 并存起来；\n// Routes 里在 AI 接口后面注册这五条路由：\n    mux.HandleFunc("POST /api/chats", h.startChat)\n    mux.HandleFunc("POST /api/chats/{id}/messages", h.followUpChat)\n    mux.HandleFunc("GET /api/chats", h.listChats)\n    mux.HandleFunc("GET /api/chats/{id}", h.chatDetail)\n    mux.HandleFunc("DELETE /api/chats/{id}", h.deleteChat)\n\n// main.go：在 aiService 那一行后面创建对话的 store 和 service，再把 chats 传给 handler.New\n    cs, err := store.NewChatStore(qs.DB())\n    if err != nil {\n        log.Fatalf("创建对话表失败：%v", err)\n    }\n    chatLimit, _ := strconv.Atoi(os.Getenv("CHAT_DAILY_LIMIT"))\n    chats := service.NewChatService(aiClient, cs, qs, chatLimit)',explain:[{at:'// internal/service/chat.go',to:'var (',text:'业务逻辑层：用到任务一改好的 ai 包和刚写的对话数据访问层。'},{at:'ErrBadMessage    = errors.New("消息不能为空，最多 1000 个字")',to:'const (',text:'这一层自己的三种业务错误，处理请求的那一层按它们决定状态码。'},{at:'chatHistory = 10',text:'追问时最多带上最近 10 条历史消息（5 轮问答）。对话越长，每次发给模型的内容越多、越贵，所以只带最近的。10 是偶数，截出来的第一条正好是学生的提问。'},{at:'tutorPrompt = ',text:'AI 老师的系统提示词。',to:')'},{at:'type ChatReply struct {',to:'Messages []store.ChatMessage `json:"messages"`',text:'两个返回给前端的结构：一次提问的结果（对话编号、回答、今天还剩几次），以及对话详情（对话信息加全部消息）。'},{at:'type ChatService struct {',to:'// systemPrompt 生成系统提示词：对话是针对某道题的，就把题目和参考答案也告诉模型。',text:'ChatService 需要大模型客户端、对话和题目两个数据访问层，以及每日次数上限。上限没设置或不合法时用默认的 20。大模型按用量收费，不限制的话，一个人写个脚本循环提问就能把你的余额刷光。'},{at:'func (s *ChatService) systemPrompt(questionID *int) string {',to:'// Send 提问：chatID 为 0 是开一段新对话，否则是在已有的对话里追问。',text:'对话关联了题目时，把题目和参考答案拼进系统提示词，模型才知道学生在问哪道题。这些内容来自数据库，不是用户输入的，所以放在 system 消息里。'},{at:'func (s *ChatService) Send(userID, chatID int, questionID *int, message string) (ChatReply, error) {',to:'return ChatReply{}, ErrBadMessage',text:'先校验消息。utf8.RuneCountInString 数的是“字”数，一个汉字算一个；len 数的是字节，一个汉字占 3 个。'},{at:'var history []store.ChatMessage',to:'history = history[len(history)-chatHistory:]',text:'追问：Get 同时检查“存在”和“是我的”，查不到一律当作对话不存在。关联的题目以对话里记的为准，再取出最近 10 条历史。'},{at:'} else if questionID != nil {',to:'return ChatReply{}, err',text:'新对话：传了题目编号就确认题目存在（不存在时 Get 返回 store.ErrNotFound，接口层会变成 404）；没传就不关联题目。'},{at:'used, ok, err := s.chats.TakeQuota(userID, s.limit)',to:'return ChatReply{}, ErrQuotaExceeded',text:'校验都通过了，才占用一次。注意顺序：先占用，再去调用大模型。如果先调用、成功后再记次数，同一个人同时发 100 个请求，就都能通过。'},{at:'messages := []ai.Message{{Role: "system", Content: s.systemPrompt(questionID)}}',to:'messages = append(messages, ai.Message{Role: "user", Content: text})',text:'发给模型的消息：系统提示词在最前面，然后是历史消息，最后是这次的问题。模型本身不记得之前聊过什么，“多轮对话”就是每次把之前的对话再发一遍。'},{at:'reply, err := s.ai.ChatMessages(messages, 0.5)',to:'return ChatReply{}, aiError(err)',text:'调用失败：先把刚才占用的次数还回去，不能让用户为失败的请求买单。aiError 是第 14 关写的：没配置的错误原样返回，其他错误写进日志后统一成 ErrAIFailed。'},{at:'reply = strings.TrimSpace(reply)',to:'return ChatReply{ChatID: id, Reply: reply, Remaining: s.limit - used}, nil',text:'成功后才保存：一问一答同时写入。失败的提问不会留在对话里，下次追问也就不会把一句没有回答的话发给模型。标题取问题的前 20 个字，先转成 []rune 再截，才不会把一个汉字截成两半。'},{at:'func (s *ChatService) List(userID int) ([]store.ChatSummary, error) {',to:'}',text:'历史列表直接转给数据访问层。'},{at:'func (s *ChatService) Detail(userID, chatID int) (ChatDetail, error) {',to:'return ChatDetail{Chat: chat, Messages: messages}, err',text:'详情：对话的基本信息加上全部消息。'},{at:'func (s *ChatService) Delete(userID, chatID int) error {',to:'return err',text:'删除：把数据访问层的“找不到”换成这一层的 ErrChatNotFound。'},{at:'// internal/handler/chat.go',to:'// chatError 把业务逻辑层的错误写成对应状态码的响应。',text:'处理请求的这一层：只负责取参数、调用业务逻辑、把结果或错误变成 HTTP 响应。'},{at:'func (h *Handler) chatError(w http.ResponseWriter, err error) {',to:'// chatID 读取路径里的对话编号；不是正整数时当作对话不存在。',text:'错误和状态码的对照：消息不合法 400，对话或题目不存在 404，次数用完 429（请求太多），没配置密钥 503，大模型出错 502；其他意料之外的错误交给 serverError 返回 500。'},{at:'func chatID(r *http.Request) (int, bool) {',to:'}',text:'从路径里取对话编号。写成 /api/chats/abc 这种不是数字的，直接当作对话不存在。'},{at:'func (h *Handler) startChat(w http.ResponseWriter, r *http.Request) {',to:'writeJSON(w, http.StatusCreated, reply)',text:'开新对话：chatID 传 0，成功返回 201（新建了资源）。QuestionID 用指针，前端没传时是 nil。五个接口都要先登录，用户 id 只从会话里取。'},{at:'func (h *Handler) followUpChat(w http.ResponseWriter, r *http.Request) {',to:'writeJSON(w, http.StatusOK, reply)',text:'在已有对话里追问：对话编号来自路径，questionID 传 nil（用对话里记的）。'},{at:'func (h *Handler) listChats(w http.ResponseWriter, r *http.Request) {',to:'writeJSON(w, http.StatusOK, detail)',text:'历史列表和某段对话的详情。'},{at:'func (h *Handler) deleteChat(w http.ResponseWriter, r *http.Request) {',to:'w.WriteHeader(http.StatusNoContent)',text:'删除对话，成功返回 204，没有正文。'},{at:'// 组装：internal/handler/handler.go 的 Handler 加一个字段',to:'mux.HandleFunc("DELETE /api/chats/{id}", h.deleteChat)',text:'在 handler.go 里给 Handler 加上 chats 字段，New 函数多接收一个参数，再注册五条路由。'},{at:'// main.go：在 aiService 那一行后面创建对话的 store 和 service',to:'chats := service.NewChatService(aiClient, cs, qs, chatLimit)',text:'main.go 负责把各层接起来：建表、从环境变量 CHAT_DAILY_LIMIT 读每日次数（没设置时 Atoi 得到 0，NewChatService 会换成 20）、创建 ChatService，最后别忘了把 chats 传给 handler.New。'}]}},java:{practice:{steps:['新建 service/ChatService.java，补完 TODO 1 到 7。','新建 controller/ChatController.java，在 application.properties 里加上 chat.daily-limit 这一行。','设置好第 14 关的三个环境变量后启动：mvn spring-boot:run。登录后在浏览器控制台试一下：fetch("/api/chats",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({message:"你好"})}).then(r=>r.json()).then(console.log)'],expect:'{chatId: 1, reply: "……", remaining: 19}'},code:'// service/ChatService.java\npackage com.example.zixishi.service;\n\nimport com.example.zixishi.ai.AiClient;\nimport com.example.zixishi.model.Question;\nimport com.example.zixishi.repository.ChatRepository;\nimport com.example.zixishi.repository.ChatRepository.Chat;\nimport com.example.zixishi.repository.ChatRepository.ChatMessage;\nimport com.example.zixishi.repository.QuestionRepository;\nimport java.util.ArrayList;\nimport java.util.List;\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\nimport org.springframework.beans.factory.annotation.Value;\nimport org.springframework.stereotype.Service;\n\n@Service\npublic class ChatService {\n\n    private static final Logger log = LoggerFactory.getLogger(ChatService.class);\n    private static final int HISTORY = 10;\n    private static final String TUTOR_PROMPT = "你是面试自习室的 AI 老师，学生是初学者。用简短、通俗的中文回答，必要时举一个小例子。";\n\n    public record ChatReply(int chatId, String reply, int remaining) {}\n\n    public record ChatDetail(int id, Integer questionId, String title, List<ChatMessage> messages) {}\n\n    private final AiClient ai;\n    private final ChatRepository chats;\n    private final QuestionRepository questions;\n    private final int dailyLimit;\n\n    public ChatService(AiClient ai, ChatRepository chats, QuestionRepository questions,\n                       @Value("${chat.daily-limit}") int dailyLimit) {\n        this.ai = ai;\n        this.chats = chats;\n        this.questions = questions;\n        this.dailyLimit = Math.max(dailyLimit, 1);\n    }\n\n    private static StudyService.StudyException error(int status, String message) {\n        return new StudyService.StudyException(status, message);\n    }\n\n    // 系统提示词：对话是针对某道题的，就把题目和参考答案也告诉模型\n    private String systemPrompt(Integer questionId) {\n        Question q = questionId == null ? null : questions.findById(questionId).orElse(null);\n        return q == null ? TUTOR_PROMPT : TUTOR_PROMPT + "\\n学生正在看这道题：" + q.title() + "\\n参考答案：" + q.answer();\n    }\n\n    // 提问：chatId 为 null 是开一段新对话，否则是在已有的对话里追问\n    public ChatReply send(int userId, Integer chatId, Integer questionId, String message) {\n        // TODO 1：message 去掉首尾空白；为空或超过 1000 个字（text.codePointCount(0, text.length())）抛出 error(400, …)\n        // TODO 2：追问（chatId 不是 null）：用 chats.find 确认是自己的对话，不是就 404；questionId 用对话里记的；\n        //         history 取这段对话最近 HISTORY 条消息。新对话：传了 questionId 就确认题目存在（不存在 404）\n        // TODO 3：chats.takeQuota 占用一次，得到空的 Optional 说明今天用完了，抛出 error(429, …)\n        // TODO 4：拼出 List<AiClient.Message>：系统提示词、history 里的每一条、这次的问题；调用 ai.chatMessages（temperature 0.5）。\n        //         失败时先 chats.refundQuota 把次数还回去：没配置是 503，其他错误写日志后统一 502\n        // TODO 5：chats.saveTurn 保存这一问一答（新对话的标题取问题的前 20 个字），返回 ChatReply\n        return null;\n    }\n\n    public List<ChatRepository.ChatSummary> list(int userId) {\n        return chats.list(userId);\n    }\n\n    public ChatDetail detail(int userId, int chatId) {\n        // TODO 6：对话不是自己的抛出 404，否则返回对话信息加上全部消息\n        return null;\n    }\n\n    public void delete(int userId, int chatId) {\n        // TODO 7：chats.delete 返回 false 时抛出 404\n    }\n}\n\n// controller/ChatController.java\npackage com.example.zixishi.controller;\n\nimport com.example.zixishi.repository.ChatRepository;\nimport com.example.zixishi.service.AuthService;\nimport com.example.zixishi.service.ChatService;\nimport java.util.List;\nimport org.springframework.http.ResponseEntity;\nimport org.springframework.web.bind.annotation.*;\n\n@RestController\n@RequestMapping("/api/chats")\npublic class ChatController {\n\n    public record NewChatBody(Integer questionId, String message) {}\n\n    public record MessageBody(String message) {}\n\n    private final AuthService auth;\n    private final ChatService chats;\n\n    public ChatController(AuthService auth, ChatService chats) {\n        this.auth = auth;\n        this.chats = chats;\n    }\n\n    @PostMapping\n    public ResponseEntity<ChatService.ChatReply> start(@CookieValue(name = "session", required = false) String token,\n                                                       @RequestBody NewChatBody body) {\n        int userId = auth.currentUser(token).id();\n        return ResponseEntity.status(201).body(chats.send(userId, null, body.questionId(), body.message()));\n    }\n\n    @PostMapping("/{id}/messages")\n    public ChatService.ChatReply followUp(@CookieValue(name = "session", required = false) String token,\n                                          @PathVariable int id, @RequestBody MessageBody body) {\n        return chats.send(auth.currentUser(token).id(), id, null, body.message());\n    }\n\n    @GetMapping\n    public List<ChatRepository.ChatSummary> list(@CookieValue(name = "session", required = false) String token) {\n        return chats.list(auth.currentUser(token).id());\n    }\n\n    @GetMapping("/{id}")\n    public ChatService.ChatDetail detail(@CookieValue(name = "session", required = false) String token, @PathVariable int id) {\n        return chats.detail(auth.currentUser(token).id(), id);\n    }\n\n    @DeleteMapping("/{id}")\n    public ResponseEntity<Void> delete(@CookieValue(name = "session", required = false) String token, @PathVariable int id) {\n        chats.delete(auth.currentUser(token).id(), id);\n        return ResponseEntity.noContent().build();\n    }\n}\n\n# application.properties（加一行：每人每天能问几次）\nchat.daily-limit=${CHAT_DAILY_LIMIT:20}',explain:[{at:'// service/ChatService.java',to:'private static final Logger log = LoggerFactory.getLogger(ChatService.class);',text:'业务逻辑层：用到任务一改好的 AiClient、刚写的 ChatRepository 和题目的 QuestionRepository。'},{at:'private static final int HISTORY = 10;',text:'追问时最多带上最近 10 条历史消息（5 轮问答）。对话越长，每次发给模型的内容越多、越贵，所以只带最近的。10 是偶数，截出来的第一条正好是学生的提问。'},{at:'private static final String TUTOR_PROMPT =',text:'AI 老师的系统提示词。'},{at:'public record ChatReply(int chatId, String reply, int remaining) {}',to:'private final int dailyLimit;',text:'两个返回给前端的类型：一次提问的结果（对话编号、回答、今天还剩几次），以及对话详情（对话信息加全部消息）。'},{at:'public ChatService(AiClient ai, ChatRepository chats, QuestionRepository questions,',to:'this.dailyLimit = Math.max(dailyLimit, 1);',text:'@Value 从配置里读每人每天能问几次，至少是 1。大模型按用量收费，不限制的话，一个人写个脚本循环提问就能把你的余额刷光。'},{at:'private static StudyService.StudyException error(int status, String message) {',to:'// 系统提示词：对话是针对某道题的，就把题目和参考答案也告诉模型',text:'和 AiService 一样，用第 9 关的 StudyException 表示“带状态码的业务错误”，全局错误处理已经会把它变成对应的响应。'},{at:'private String systemPrompt(Integer questionId) {',to:'// 提问：chatId 为 null 是开一段新对话，否则是在已有的对话里追问',text:'对话关联了题目时，把题目和参考答案拼进系统提示词，模型才知道学生在问哪道题。这些内容来自数据库，不是用户输入的，所以放在 system 消息里。'},{at:'public ChatReply send(int userId, Integer chatId, Integer questionId, String message) {',text:'这一关的核心方法，要你补全。',to:'}'},{at:'public List<ChatRepository.ChatSummary> list(int userId) {',to:'}',text:'历史列表直接转给数据访问层。'},{at:'public ChatDetail detail(int userId, int chatId) {',text:'对话详情，要你补全。',to:'}'},{at:'public void delete(int userId, int chatId) {',text:'删除对话，要你补全。',to:'}'},{at:'// controller/ChatController.java',to:'public class ChatController {',text:'接口层：五个接口的路径都以 /api/chats 开头，所以写在 @RequestMapping 上。'},{at:'public record NewChatBody(Integer questionId, String message) {}',to:'this.chats = chats;',text:'两个请求正文。字段没传时是 null，交给业务逻辑层统一处理。'},{at:'@PostMapping',to:'}',text:'开新对话：chatId 传 null，返回 201（新建了资源）。五个接口都先用 auth.currentUser 确认登录，用户 id 只从会话里取。'},{at:'@PostMapping("/{id}/messages")',to:'return chats.send(auth.currentUser(token).id(), id, null, body.message());',text:'在已有对话里追问：对话 id 来自路径，questionId 传 null（用对话里记的）。'},{at:'@GetMapping',to:'return chats.detail(auth.currentUser(token).id(), id);',text:'历史列表和某段对话的详情。'},{at:'@DeleteMapping("/{id}")',to:'return ResponseEntity.noContent().build();',text:'删除对话，成功返回 204，没有正文。'},{at:'# application.properties（加一行：每人每天能问几次）',to:'chat.daily-limit=${CHAT_DAILY_LIMIT:20}',text:'从环境变量 CHAT_DAILY_LIMIT 读取，没有设置时是 20。'}],solution:{code:'// service/ChatService.java\npackage com.example.zixishi.service;\n\nimport com.example.zixishi.ai.AiClient;\nimport com.example.zixishi.model.Question;\nimport com.example.zixishi.repository.ChatRepository;\nimport com.example.zixishi.repository.ChatRepository.Chat;\nimport com.example.zixishi.repository.ChatRepository.ChatMessage;\nimport com.example.zixishi.repository.QuestionRepository;\nimport java.util.ArrayList;\nimport java.util.List;\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\nimport org.springframework.beans.factory.annotation.Value;\nimport org.springframework.stereotype.Service;\n\n@Service\npublic class ChatService {\n\n    private static final Logger log = LoggerFactory.getLogger(ChatService.class);\n    private static final int HISTORY = 10;\n    private static final String TUTOR_PROMPT = "你是面试自习室的 AI 老师，学生是初学者。用简短、通俗的中文回答，必要时举一个小例子。";\n\n    public record ChatReply(int chatId, String reply, int remaining) {}\n\n    public record ChatDetail(int id, Integer questionId, String title, List<ChatMessage> messages) {}\n\n    private final AiClient ai;\n    private final ChatRepository chats;\n    private final QuestionRepository questions;\n    private final int dailyLimit;\n\n    public ChatService(AiClient ai, ChatRepository chats, QuestionRepository questions,\n                       @Value("${chat.daily-limit}") int dailyLimit) {\n        this.ai = ai;\n        this.chats = chats;\n        this.questions = questions;\n        this.dailyLimit = Math.max(dailyLimit, 1);\n    }\n\n    private static StudyService.StudyException error(int status, String message) {\n        return new StudyService.StudyException(status, message);\n    }\n\n    // 系统提示词：对话是针对某道题的，就把题目和参考答案也告诉模型\n    private String systemPrompt(Integer questionId) {\n        Question q = questionId == null ? null : questions.findById(questionId).orElse(null);\n        return q == null ? TUTOR_PROMPT : TUTOR_PROMPT + "\\n学生正在看这道题：" + q.title() + "\\n参考答案：" + q.answer();\n    }\n\n    // 提问：chatId 为 null 是开一段新对话，否则是在已有的对话里追问\n    public ChatReply send(int userId, Integer chatId, Integer questionId, String message) {\n        String text = message == null ? "" : message.strip();\n        if (text.isEmpty() || text.codePointCount(0, text.length()) > 1000) {\n            throw error(400, "消息不能为空，最多 1000 个字");\n        }\n        List<ChatMessage> history = List.of();\n        if (chatId != null) {\n            Chat chat = chats.find(userId, chatId).orElseThrow(() -> error(404, "对话不存在"));\n            questionId = chat.questionId();\n            List<ChatMessage> all = chats.messages(chatId);\n            history = all.subList(Math.max(all.size() - HISTORY, 0), all.size());\n        } else if (questionId != null && questions.findById(questionId).isEmpty()) {\n            throw error(404, "题目不存在");\n        }\n        int used = chats.takeQuota(userId, dailyLimit).orElseThrow(() -> error(429, "今天的提问次数用完了，明天再来"));\n        List<AiClient.Message> messages = new ArrayList<>();\n        messages.add(new AiClient.Message("system", systemPrompt(questionId)));\n        for (ChatMessage m : history) {\n            messages.add(new AiClient.Message(m.role(), m.content()));\n        }\n        messages.add(new AiClient.Message("user", text));\n        String reply;\n        try {\n            reply = ai.chatMessages(messages, 0.5).strip();\n        } catch (AiClient.NotConfiguredException e) {\n            chats.refundQuota(userId);\n            throw error(503, e.getMessage());\n        } catch (RuntimeException e) {\n            chats.refundQuota(userId);\n            log.error("调用 AI 出错", e);\n            throw error(502, "AI 服务暂时不可用，请稍后再试");\n        }\n        String title = text.substring(0, text.offsetByCodePoints(0, Math.min(20, text.codePointCount(0, text.length()))));\n        int id = chats.saveTurn(userId, chatId, questionId, title, text, reply);\n        return new ChatReply(id, reply, dailyLimit - used);\n    }\n\n    public List<ChatRepository.ChatSummary> list(int userId) {\n        return chats.list(userId);\n    }\n\n    public ChatDetail detail(int userId, int chatId) {\n        Chat chat = chats.find(userId, chatId).orElseThrow(() -> error(404, "对话不存在"));\n        return new ChatDetail(chat.id(), chat.questionId(), chat.title(), chats.messages(chatId));\n    }\n\n    public void delete(int userId, int chatId) {\n        if (!chats.delete(userId, chatId)) {\n            throw error(404, "对话不存在");\n        }\n    }\n}\n\n// controller/ChatController.java\npackage com.example.zixishi.controller;\n\nimport com.example.zixishi.repository.ChatRepository;\nimport com.example.zixishi.service.AuthService;\nimport com.example.zixishi.service.ChatService;\nimport java.util.List;\nimport org.springframework.http.ResponseEntity;\nimport org.springframework.web.bind.annotation.*;\n\n@RestController\n@RequestMapping("/api/chats")\npublic class ChatController {\n\n    public record NewChatBody(Integer questionId, String message) {}\n\n    public record MessageBody(String message) {}\n\n    private final AuthService auth;\n    private final ChatService chats;\n\n    public ChatController(AuthService auth, ChatService chats) {\n        this.auth = auth;\n        this.chats = chats;\n    }\n\n    @PostMapping\n    public ResponseEntity<ChatService.ChatReply> start(@CookieValue(name = "session", required = false) String token,\n                                                       @RequestBody NewChatBody body) {\n        int userId = auth.currentUser(token).id();\n        return ResponseEntity.status(201).body(chats.send(userId, null, body.questionId(), body.message()));\n    }\n\n    @PostMapping("/{id}/messages")\n    public ChatService.ChatReply followUp(@CookieValue(name = "session", required = false) String token,\n                                          @PathVariable int id, @RequestBody MessageBody body) {\n        return chats.send(auth.currentUser(token).id(), id, null, body.message());\n    }\n\n    @GetMapping\n    public List<ChatRepository.ChatSummary> list(@CookieValue(name = "session", required = false) String token) {\n        return chats.list(auth.currentUser(token).id());\n    }\n\n    @GetMapping("/{id}")\n    public ChatService.ChatDetail detail(@CookieValue(name = "session", required = false) String token, @PathVariable int id) {\n        return chats.detail(auth.currentUser(token).id(), id);\n    }\n\n    @DeleteMapping("/{id}")\n    public ResponseEntity<Void> delete(@CookieValue(name = "session", required = false) String token, @PathVariable int id) {\n        chats.delete(auth.currentUser(token).id(), id);\n        return ResponseEntity.noContent().build();\n    }\n}\n\n# application.properties（加一行：每人每天能问几次）\nchat.daily-limit=${CHAT_DAILY_LIMIT:20}',explain:[{at:'// service/ChatService.java',to:'private static final Logger log = LoggerFactory.getLogger(ChatService.class);',text:'业务逻辑层：用到任务一改好的 AiClient、刚写的 ChatRepository 和题目的 QuestionRepository。'},{at:'private static final int HISTORY = 10;',text:'追问时最多带上最近 10 条历史消息（5 轮问答）。对话越长，每次发给模型的内容越多、越贵，所以只带最近的。10 是偶数，截出来的第一条正好是学生的提问。'},{at:'private static final String TUTOR_PROMPT =',text:'AI 老师的系统提示词。'},{at:'public record ChatReply(int chatId, String reply, int remaining) {}',to:'private final int dailyLimit;',text:'两个返回给前端的类型：一次提问的结果（对话编号、回答、今天还剩几次），以及对话详情（对话信息加全部消息）。'},{at:'public ChatService(AiClient ai, ChatRepository chats, QuestionRepository questions,',to:'this.dailyLimit = Math.max(dailyLimit, 1);',text:'@Value 从配置里读每人每天能问几次，至少是 1。大模型按用量收费，不限制的话，一个人写个脚本循环提问就能把你的余额刷光。'},{at:'private static StudyService.StudyException error(int status, String message) {',to:'// 系统提示词：对话是针对某道题的，就把题目和参考答案也告诉模型',text:'和 AiService 一样，用第 9 关的 StudyException 表示“带状态码的业务错误”，全局错误处理已经会把它变成对应的响应。'},{at:'private String systemPrompt(Integer questionId) {',to:'// 提问：chatId 为 null 是开一段新对话，否则是在已有的对话里追问',text:'对话关联了题目时，把题目和参考答案拼进系统提示词，模型才知道学生在问哪道题。这些内容来自数据库，不是用户输入的，所以放在 system 消息里。'},{at:'public ChatReply send(int userId, Integer chatId, Integer questionId, String message) {',to:'}',text:'先校验消息。codePointCount 数的是“字”数，一个汉字或表情算一个；length() 对表情会算成两个。'},{at:'List<ChatMessage> history = List.of();',to:'history = all.subList(Math.max(all.size() - HISTORY, 0), all.size());',text:'追问：find 同时检查“存在”和“是我的”，查不到一律 404。关联的题目以对话里记的为准，再用 subList 取出最近 10 条历史。'},{at:'} else if (questionId != null && questions.findById(questionId).isEmpty()) {',to:'throw error(404, "题目不存在");',text:'新对话：传了题目 id 就确认题目存在；没传就不关联题目。'},{at:'int used = chats.takeQuota(userId, dailyLimit)',text:'校验都通过了，才占用一次；得到空的 Optional 说明今天用完了，返回 429（请求太多）。注意顺序：先占用，再去调用大模型。如果先调用、成功后再记次数，同一个人同时发 100 个请求，就都能通过。'},{at:'List<AiClient.Message> messages = new ArrayList<>();',to:'messages.add(new AiClient.Message("user", text));',text:'发给模型的消息：系统提示词在最前面，然后是历史消息，最后是这次的问题。模型本身不记得之前聊过什么，“多轮对话”就是每次把之前的对话再发一遍。'},{at:'String reply;',to:'throw error(502, "AI 服务暂时不可用，请稍后再试");',text:'调用失败：先把刚才占用的次数还回去，不能让用户为失败的请求买单。然后和第 14 关一样，没配置是 503，其他都是 502，详细原因只写进日志。'},{at:'String title = text.substring(',to:'}',text:'成功后才保存：一问一答同时写入。失败的提问不会留在对话里，下次追问也就不会把一句没有回答的话发给模型。标题取问题的前 20 个字，offsetByCodePoints 按“字”算位置，不会把一个表情截成两半。'},{at:'public List<ChatRepository.ChatSummary> list(int userId) {',to:'}',text:'历史列表直接转给数据访问层。'},{at:'public ChatDetail detail(int userId, int chatId) {',to:'}',text:'详情：对话的基本信息加上全部消息。'},{at:'public void delete(int userId, int chatId) {',to:'}',text:'删除：数据访问层返回 false 说明对话不存在或不是自己的。'},{at:'// controller/ChatController.java',to:'public class ChatController {',text:'接口层：五个接口的路径都以 /api/chats 开头，所以写在 @RequestMapping 上。'},{at:'public record NewChatBody(Integer questionId, String message) {}',to:'this.chats = chats;',text:'两个请求正文。字段没传时是 null，交给业务逻辑层统一处理。'},{at:'@PostMapping',to:'}',text:'开新对话：chatId 传 null，返回 201（新建了资源）。五个接口都先用 auth.currentUser 确认登录，用户 id 只从会话里取。'},{at:'@PostMapping("/{id}/messages")',to:'return chats.send(auth.currentUser(token).id(), id, null, body.message());',text:'在已有对话里追问：对话 id 来自路径，questionId 传 null（用对话里记的）。'},{at:'@GetMapping',to:'return chats.detail(auth.currentUser(token).id(), id);',text:'历史列表和某段对话的详情。'},{at:'@DeleteMapping("/{id}")',to:'return ResponseEntity.noContent().build();',text:'删除对话，成功返回 204，没有正文。'},{at:'# application.properties（加一行：每人每天能问几次）',to:'chat.daily-limit=${CHAT_DAILY_LIMIT:20}',text:'从环境变量 CHAT_DAILY_LIMIT 读取，没有设置时是 20。'}]}},node:{practice:{steps:['新建 src/services/chat.js，补完 TODO 1 到 7。','新建 src/routes/chat.js，再在 app.js 里加上一行挂载。','设置好第 14 关的三个环境变量后启动：node app.js。登录后在浏览器控制台试一下：fetch("/api/chats",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({message:"你好"})}).then(r=>r.json()).then(console.log)'],expect:'{chatId: 1, reply: "……", remaining: 19}'},code:'// src/services/chat.js\nconst { NotConfiguredError, chatMessages } = require("../ai/client");\nconst { getQuestion } = require("../db/questions");\nconst store = require("../db/chat");\n\nclass ChatError extends Error {\n  constructor(status, message) {\n    super(message);\n    this.status = status;\n  }\n}\n\nconst DAILY_LIMIT = Math.max(Number(process.env.CHAT_DAILY_LIMIT) || 20, 1);\nconst HISTORY = 10;\nconst TUTOR_PROMPT = "你是面试自习室的 AI 老师，学生是初学者。用简短、通俗的中文回答，必要时举一个小例子。";\n\n// 系统提示词：对话是针对某道题的，就把题目和参考答案也告诉模型\nfunction systemPrompt(questionId) {\n  const q = questionId ? getQuestion(questionId) : null;\n  return q ? `${TUTOR_PROMPT}\\n学生正在看这道题：${q.title}\\n参考答案：${q.answer}` : TUTOR_PROMPT;\n}\n\n// 提问：chatId 为 null 是开一段新对话，否则是在已有的对话里追问\nasync function send(userId, chatId, questionId, message) {\n  // TODO 1：message 去掉首尾空白；为空或超过 1000 个字（用 [...text].length 数字数）抛出 ChatError(400)\n  // TODO 2：追问（chatId 不是 null）：用 store.getChat 确认是自己的对话，不是就 404；questionId 用对话里记的；\n  //         history 取这段对话最近 HISTORY 条消息。新对话：传了 questionId 就确认题目存在（不存在 404），没传就是 null\n  // TODO 3：store.takeQuota 占用一次，返回 null 说明今天用完了，抛出 ChatError(429)\n  // TODO 4：调用 chatMessages，消息依次是：系统提示词、history 里的每一条（只要 role 和 content）、这次的问题。\n  //         失败时先 store.refundQuota 把次数还回去：没配置是 503，其他错误写日志后统一 502\n  // TODO 5：store.saveTurn 保存这一问一答（新对话的标题取问题的前 20 个字），返回 { chatId, reply, remaining }\n}\n\nfunction list(userId) {\n  return store.listChats(userId);\n}\n\nfunction detail(userId, chatId) {\n  // TODO 6：对话不是自己的抛出 404，否则返回对话信息加上 messages\n}\n\nfunction remove(userId, chatId) {\n  // TODO 7：store.deleteChat 返回 false 时抛出 404\n}\n\nmodule.exports = { ChatError, send, list, detail, remove };\n\n// src/routes/chat.js\nconst express = require("express");\nconst chat = require("../services/chat");\nconst { requireUser } = require("../middleware");\n\nconst router = express.Router();\n\nfunction handle(status, fn) {\n  return async (req, res, next) => {\n    try {\n      const data = await fn(req);\n      if (status === 204) return res.status(204).end();\n      res.status(status).json(data);\n    } catch (err) {\n      if (err instanceof chat.ChatError) return res.status(err.status).json({ error: err.message });\n      next(err);\n    }\n  };\n}\n\nrouter.post("/chats", requireUser, handle(201, (req) => chat.send(req.user.id, null, req.body?.questionId, req.body?.message)));\nrouter.post("/chats/:id/messages", requireUser, handle(200, (req) => chat.send(req.user.id, Number(req.params.id), null, req.body?.message)));\nrouter.get("/chats", requireUser, handle(200, (req) => chat.list(req.user.id)));\nrouter.get("/chats/:id", requireUser, handle(200, (req) => chat.detail(req.user.id, Number(req.params.id))));\nrouter.delete("/chats/:id", requireUser, handle(204, (req) => chat.remove(req.user.id, Number(req.params.id))));\n\nmodule.exports = router;\n\n// app.js（加在 ai 路由的下一行）\napp.use("/api", require("./src/routes/chat"));',explain:[{at:'// src/services/chat.js',to:'const store = require("../db/chat");',text:'业务逻辑层：用到任务一改好的 chatMessages、题目的数据访问层，以及刚写的对话数据访问层（起个短名字 store）。'},{at:'class ChatError extends Error {',to:'}',text:'带状态码的业务错误，和前几关的 ExamError、AIError 是同一个套路。'},{at:'const DAILY_LIMIT = Math.max(Number(process.env.CHAT_DAILY_LIMIT) || 20, 1);',text:'每人每天能问几次，从环境变量读，默认 20，至少是 1。大模型按用量收费，不限制的话，一个人写个脚本循环提问就能把你的余额刷光。'},{at:'const HISTORY = 10;',text:'追问时最多带上最近 10 条历史消息（5 轮问答）。对话越长，每次发给模型的内容越多、越贵，所以只带最近的。10 是偶数，截出来的第一条正好是学生的提问。'},{at:'const TUTOR_PROMPT =',text:'AI 老师的系统提示词。',to:'// 系统提示词：对话是针对某道题的，就把题目和参考答案也告诉模型'},{at:'function systemPrompt(questionId) {',to:'// 提问：chatId 为 null 是开一段新对话，否则是在已有的对话里追问',text:'对话关联了题目时，把题目和参考答案拼进系统提示词，模型才知道学生在问哪道题。这些内容来自数据库，不是用户输入的，所以放在 system 消息里。'},{at:'async function send(userId, chatId, questionId, message) {',text:'这一关的核心函数，要你补全。',to:'// TODO 5：store.saveTurn 保存这一问一答（新对话的标题取问题的前 20 个字），返回 { chatId, reply, remaining }'},{at:'function list(userId) {',to:'}',text:'历史列表直接转给数据访问层。'},{at:'function detail(userId, chatId) {',text:'对话详情，要你补全。',to:'}'},{at:'function remove(userId, chatId) {',text:'删除对话，要你补全。',to:'}'},{at:'module.exports = { ChatError, send, list, detail, remove };',text:'导出。'},{at:'// src/routes/chat.js',to:'const router = express.Router();',text:'接口层：只负责取参数、调用业务逻辑、把结果或错误变成 HTTP 响应。'},{at:'function handle(status, fn) {',to:'};',text:'公共的包装：成功时按指定的状态码返回 JSON（204 没有正文，直接 end）；ChatError 按它带的状态码返回 {"error": …}；其他错误交给全局错误处理。fn 可能是异步的，所以要 await。'},{at:'router.post("/chats", requireUser,',text:'开新对话：chatId 传 null，返回 201（新建了资源）。五个接口都要先登录，用户 id 只从会话里取。'},{at:'router.post("/chats/:id/messages", requireUser,',text:'在已有对话里追问：对话 id 来自路径，questionId 传 null（用对话里记的）。'},{at:'router.get("/chats", requireUser,',to:'router.get("/chats/:id", requireUser,',text:'历史列表和某段对话的详情。'},{at:'router.delete("/chats/:id", requireUser,',text:'删除对话，成功返回 204。'},{at:'module.exports = router;',text:'导出路由。'},{at:'// app.js（加在 ai 路由的下一行）',to:'app.use("/api", require("./src/routes/chat"));',text:'在 app.js 里把新路由挂到 /api 下面。'}],solution:{code:'// src/services/chat.js\nconst { NotConfiguredError, chatMessages } = require("../ai/client");\nconst { getQuestion } = require("../db/questions");\nconst store = require("../db/chat");\n\nclass ChatError extends Error {\n  constructor(status, message) {\n    super(message);\n    this.status = status;\n  }\n}\n\nconst DAILY_LIMIT = Math.max(Number(process.env.CHAT_DAILY_LIMIT) || 20, 1);\nconst HISTORY = 10;\nconst TUTOR_PROMPT = "你是面试自习室的 AI 老师，学生是初学者。用简短、通俗的中文回答，必要时举一个小例子。";\n\n// 系统提示词：对话是针对某道题的，就把题目和参考答案也告诉模型\nfunction systemPrompt(questionId) {\n  const q = questionId ? getQuestion(questionId) : null;\n  return q ? `${TUTOR_PROMPT}\\n学生正在看这道题：${q.title}\\n参考答案：${q.answer}` : TUTOR_PROMPT;\n}\n\n// 提问：chatId 为 null 是开一段新对话，否则是在已有的对话里追问\nasync function send(userId, chatId, questionId, message) {\n  const text = typeof message === "string" ? message.trim() : "";\n  if (!text || [...text].length > 1000) throw new ChatError(400, "消息不能为空，最多 1000 个字");\n  let history = [];\n  if (chatId !== null) {\n    const chat = store.getChat(userId, chatId);\n    if (!chat) throw new ChatError(404, "对话不存在");\n    questionId = chat.questionId;\n    history = store.listMessages(chatId).slice(-HISTORY);\n  } else if (questionId != null) {\n    questionId = Number(questionId);\n    if (!getQuestion(questionId)) throw new ChatError(404, "题目不存在");\n  } else {\n    questionId = null;\n  }\n  const used = store.takeQuota(userId, DAILY_LIMIT);\n  if (used === null) throw new ChatError(429, "今天的提问次数用完了，明天再来");\n  let reply;\n  try {\n    reply = await chatMessages([\n      { role: "system", content: systemPrompt(questionId) },\n      ...history.map((m) => ({ role: m.role, content: m.content })),\n      { role: "user", content: text },\n    ]);\n  } catch (err) {\n    store.refundQuota(userId);\n    if (err instanceof NotConfiguredError) throw new ChatError(503, err.message);\n    console.error("调用 AI 出错：", err);\n    throw new ChatError(502, "AI 服务暂时不可用，请稍后再试");\n  }\n  reply = reply.trim();\n  const id = store.saveTurn(userId, chatId, questionId, [...text].slice(0, 20).join(""), text, reply);\n  return { chatId: id, reply, remaining: DAILY_LIMIT - used };\n}\n\nfunction list(userId) {\n  return store.listChats(userId);\n}\n\nfunction detail(userId, chatId) {\n  const chat = store.getChat(userId, chatId);\n  if (!chat) throw new ChatError(404, "对话不存在");\n  return { ...chat, messages: store.listMessages(chatId) };\n}\n\nfunction remove(userId, chatId) {\n  if (!store.deleteChat(userId, chatId)) throw new ChatError(404, "对话不存在");\n}\n\nmodule.exports = { ChatError, send, list, detail, remove };\n\n// src/routes/chat.js\nconst express = require("express");\nconst chat = require("../services/chat");\nconst { requireUser } = require("../middleware");\n\nconst router = express.Router();\n\nfunction handle(status, fn) {\n  return async (req, res, next) => {\n    try {\n      const data = await fn(req);\n      if (status === 204) return res.status(204).end();\n      res.status(status).json(data);\n    } catch (err) {\n      if (err instanceof chat.ChatError) return res.status(err.status).json({ error: err.message });\n      next(err);\n    }\n  };\n}\n\nrouter.post("/chats", requireUser, handle(201, (req) => chat.send(req.user.id, null, req.body?.questionId, req.body?.message)));\nrouter.post("/chats/:id/messages", requireUser, handle(200, (req) => chat.send(req.user.id, Number(req.params.id), null, req.body?.message)));\nrouter.get("/chats", requireUser, handle(200, (req) => chat.list(req.user.id)));\nrouter.get("/chats/:id", requireUser, handle(200, (req) => chat.detail(req.user.id, Number(req.params.id))));\nrouter.delete("/chats/:id", requireUser, handle(204, (req) => chat.remove(req.user.id, Number(req.params.id))));\n\nmodule.exports = router;\n\n// app.js（加在 ai 路由的下一行）\napp.use("/api", require("./src/routes/chat"));',explain:[{at:'// src/services/chat.js',to:'const store = require("../db/chat");',text:'业务逻辑层：用到任务一改好的 chatMessages、题目的数据访问层，以及刚写的对话数据访问层（起个短名字 store）。'},{at:'class ChatError extends Error {',to:'}',text:'带状态码的业务错误，和前几关的 ExamError、AIError 是同一个套路。'},{at:'const DAILY_LIMIT = Math.max(Number(process.env.CHAT_DAILY_LIMIT) || 20, 1);',text:'每人每天能问几次，从环境变量读，默认 20，至少是 1。大模型按用量收费，不限制的话，一个人写个脚本循环提问就能把你的余额刷光。'},{at:'const HISTORY = 10;',text:'追问时最多带上最近 10 条历史消息（5 轮问答）。对话越长，每次发给模型的内容越多、越贵，所以只带最近的。10 是偶数，截出来的第一条正好是学生的提问。'},{at:'const TUTOR_PROMPT =',text:'AI 老师的系统提示词。',to:'// 系统提示词：对话是针对某道题的，就把题目和参考答案也告诉模型'},{at:'function systemPrompt(questionId) {',to:'// 提问：chatId 为 null 是开一段新对话，否则是在已有的对话里追问',text:'对话关联了题目时，把题目和参考答案拼进系统提示词，模型才知道学生在问哪道题。这些内容来自数据库，不是用户输入的，所以放在 system 消息里。'},{at:'async function send(userId, chatId, questionId, message) {',to:'if (!text || [...text].length > 1000) throw new ChatError(400, "消息不能为空，最多 1000 个字");',text:'先校验消息。[...text] 按“字”拆开再数，一个汉字或表情算一个字。'},{at:'let history = [];',to:'history = store.listMessages(chatId).slice(-HISTORY);',text:'追问：getChat 同时检查“存在”和“是我的”，查不到一律 404。关联的题目以对话里记的为准，再取出最近 10 条历史。'},{at:'} else if (questionId != null) {',to:'questionId = null;',text:'新对话：传了题目 id 就确认题目存在；没传就不关联题目。'},{at:'const used = store.takeQuota(userId, DAILY_LIMIT);',to:'try {',text:'校验都通过了，才占用一次。429 的意思是“请求太多”。注意顺序：先占用，再去调用大模型。如果先调用、成功后再记次数，同一个人同时发 100 个请求，就都能通过。'},{at:'reply = await chatMessages([',to:']);',text:'发给模型的消息：系统提示词在最前面，然后是历史消息，最后是这次的问题。模型本身不记得之前聊过什么，“多轮对话”就是每次把之前的对话再发一遍。'},{at:'} catch (err) {',to:'throw new ChatError(502, "AI 服务暂时不可用，请稍后再试");',text:'调用失败：先把刚才占用的次数还回去，不能让用户为失败的请求买单。然后和第 14 关一样，没配置是 503，其他都是 502，详细原因只写进日志。'},{at:'reply = reply.trim();',to:'return { chatId: id, reply, remaining: DAILY_LIMIT - used };',text:'成功后才保存：一问一答同时写入。失败的提问不会留在对话里，下次追问也就不会把一句没有回答的话发给模型。remaining 是今天还能问几次。'},{at:'function list(userId) {',to:'}',text:'历史列表直接转给数据访问层。'},{at:'function detail(userId, chatId) {',to:'return { ...chat, messages: store.listMessages(chatId) };',text:'详情：对话的基本信息加上全部消息。'},{at:'function remove(userId, chatId) {',to:'}',text:'删除：数据访问层返回 false 说明对话不存在或不是自己的。'},{at:'module.exports = { ChatError, send, list, detail, remove };',text:'导出。'},{at:'// src/routes/chat.js',to:'const router = express.Router();',text:'接口层：只负责取参数、调用业务逻辑、把结果或错误变成 HTTP 响应。'},{at:'function handle(status, fn) {',to:'};',text:'公共的包装：成功时按指定的状态码返回 JSON（204 没有正文，直接 end）；ChatError 按它带的状态码返回 {"error": …}；其他错误交给全局错误处理。fn 可能是异步的，所以要 await。'},{at:'router.post("/chats", requireUser,',text:'开新对话：chatId 传 null，返回 201（新建了资源）。五个接口都要先登录，用户 id 只从会话里取。'},{at:'router.post("/chats/:id/messages", requireUser,',text:'在已有对话里追问：对话 id 来自路径，questionId 传 null（用对话里记的）。'},{at:'router.get("/chats", requireUser,',to:'router.get("/chats/:id", requireUser,',text:'历史列表和某段对话的详情。'},{at:'router.delete("/chats/:id", requireUser,',text:'删除对话，成功返回 204。'},{at:'module.exports = router;',text:'导出路由。'},{at:'// app.js（加在 ai 路由的下一行）',to:'app.use("/api", require("./src/routes/chat"));',text:'在 app.js 里把新路由挂到 /api 下面。'}]}},python:{practice:{steps:['新建 app/services/chat.py，补完 TODO 1 到 7。','新建 app/routers/chat.py，再在 main.py 里注册路由和错误处理。','设置好第 14 关的三个环境变量后启动：python main.py。登录后在浏览器控制台试一下：fetch("/api/chats",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({message:"你好"})}).then(r=>r.json()).then(console.log)'],expect:'{chatId: 1, reply: "……", remaining: 19}'},code:'# app/services/chat.py\nimport logging\nimport os\n\nfrom app import ai_client\nfrom app import chat as store\nfrom app.db import get_question\n\nlog = logging.getLogger("zixishi")\n\nDAILY_LIMIT = max(int(os.getenv("CHAT_DAILY_LIMIT", "20") or 20), 1)\nHISTORY = 10\nTUTOR_PROMPT = "你是面试自习室的 AI 老师，学生是初学者。用简短、通俗的中文回答，必要时举一个小例子。"\n\n\nclass ChatError(Exception):\n    def __init__(self, status, message):\n        super().__init__(message)\n        self.status = status\n        self.message = message\n\n\ndef system_prompt(question_id):\n    """系统提示词：对话是针对某道题的，就把题目和参考答案也告诉模型"""\n    q = get_question(question_id) if question_id else None\n    if q is None:\n        return TUTOR_PROMPT\n    return f"{TUTOR_PROMPT}\\n学生正在看这道题：{q[\'title\']}\\n参考答案：{q[\'answer\']}"\n\n\ndef send(user_id, chat_id, question_id, message):\n    """提问：chat_id 为 None 是开一段新对话，否则是在已有的对话里追问"""\n    # TODO 1：message 去掉首尾空白；为空或超过 1000 个字抛出 ChatError(400)\n    # TODO 2：追问（chat_id 不是 None）：用 store.get_chat 确认是自己的对话，不是就 404；question_id 用对话里记的；\n    #         history 取这段对话最近 HISTORY 条消息。新对话：传了 question_id 就确认题目存在（不存在 404）\n    # TODO 3：store.take_quota 占用一次，返回 None 说明今天用完了，抛出 ChatError(429)\n    # TODO 4：调用 ai_client.chat_messages，消息依次是：系统提示词、history 里的每一条（只要 role 和 content）、这次的问题。\n    #         失败时先 store.refund_quota 把次数还回去：没配置是 503，其他错误写日志后统一 502\n    # TODO 5：store.save_turn 保存这一问一答（新对话的标题取问题的前 20 个字），返回 chatId、reply、remaining\n\n\ndef detail(user_id, chat_id):\n    # TODO 6：对话不是自己的抛出 404，否则返回对话信息加上 messages\n    ...\n\n\ndef remove(user_id, chat_id):\n    # TODO 7：store.delete_chat 返回 False 时抛出 404\n    ...\n\n\n# app/routers/chat.py\nfrom fastapi import APIRouter, Depends, Response\nfrom pydantic import BaseModel\n\nfrom app import chat as store\nfrom app.routers.study import require_user\nfrom app.services import chat\n\nrouter = APIRouter(prefix="/api")\n\n\nclass NewChatBody(BaseModel):\n    questionId: int | None = None\n    message: str = ""\n\n\nclass MessageBody(BaseModel):\n    message: str = ""\n\n\n@router.post("/chats", status_code=201)\ndef start(body: NewChatBody, user=Depends(require_user)):\n    return chat.send(user["id"], None, body.questionId, body.message)\n\n\n@router.post("/chats/{chat_id}/messages")\ndef follow_up(chat_id: int, body: MessageBody, user=Depends(require_user)):\n    return chat.send(user["id"], chat_id, None, body.message)\n\n\n@router.get("/chats")\ndef history(user=Depends(require_user)):\n    return store.list_chats(user["id"])\n\n\n@router.get("/chats/{chat_id}")\ndef detail(chat_id: int, user=Depends(require_user)):\n    return chat.detail(user["id"], chat_id)\n\n\n@router.delete("/chats/{chat_id}", status_code=204)\ndef remove(chat_id: int, user=Depends(require_user)):\n    chat.remove(user["id"], chat_id)\n    return Response(status_code=204)\n\n\n# main.py（导入加在其他路由的导入旁边；另外两段加在 ai 路由和 AIError 处理的后面）\nfrom app.routers import chat as chat_routes\nfrom app.services.chat import ChatError\n\napp.include_router(chat_routes.router)\n\n\n@app.exception_handler(ChatError)\nasync def chat_error(request: Request, exc: ChatError):\n    return JSONResponse({"error": exc.message}, status_code=exc.status)',explain:[{at:'# app/services/chat.py',to:'log = logging.getLogger("zixishi")',text:'业务逻辑层：用到任务一改好的 ai_client、对话的数据访问层（起个短名字 store）和题目的数据访问层。'},{at:'DAILY_LIMIT = max(int(os.getenv("CHAT_DAILY_LIMIT", "20") or 20), 1)',text:'每人每天能问几次，从环境变量读，默认 20，至少是 1。大模型按用量收费，不限制的话，一个人写个脚本循环提问就能把你的余额刷光。'},{at:'HISTORY = 10',text:'追问时最多带上最近 10 条历史消息（5 轮问答）。对话越长，每次发给模型的内容越多、越贵，所以只带最近的。10 是偶数，截出来的第一条正好是学生的提问。'},{at:'TUTOR_PROMPT =',text:'AI 老师的系统提示词。'},{at:'class ChatError(Exception):',to:'self.message = message',text:'带状态码的业务错误，和前几关的 ExamError、AIError 是同一个套路。'},{at:'def system_prompt(question_id):',to:'return f"{TUTOR_PROMPT}',text:'对话关联了题目时，把题目和参考答案拼进系统提示词，模型才知道学生在问哪道题。这些内容来自数据库，不是用户输入的，所以放在 system 消息里。'},{at:'def send(user_id, chat_id, question_id, message):',text:'这一关的核心函数，要你补全。',to:'# TODO 5：store.save_turn 保存这一问一答（新对话的标题取问题的前 20 个字），返回 chatId、reply、remaining'},{at:'def detail(user_id, chat_id):',text:'对话详情，要你补全。',to:'...'},{at:'def remove(user_id, chat_id):',text:'删除对话，要你补全。',to:'...'},{at:'# app/routers/chat.py',to:'router = APIRouter(prefix="/api")',text:'接口层：只负责取参数、调用业务逻辑。'},{at:'class MessageBody(BaseModel):',to:'message: str = ""',text:'追问只需要消息内容。'},{at:'class NewChatBody(BaseModel):',to:'message: str = ""',text:'两个请求正文。questionId 可以不传（int | None）；message 没传时是空字符串，交给业务逻辑层统一返回 400。'},{at:'@router.post("/chats", status_code=201)',to:'return chat.send(user["id"], None, body.questionId, body.message)',text:'开新对话：chat_id 传 None，返回 201（新建了资源）。五个接口都要先登录，用户 id 只从会话里取。'},{at:'@router.post("/chats/{chat_id}/messages")',to:'return chat.send(user["id"], chat_id, None, body.message)',text:'在已有对话里追问：对话 id 来自路径，question_id 传 None（用对话里记的）。'},{at:'@router.get("/chats")',to:'return chat.detail(user["id"], chat_id)',text:'历史列表和某段对话的详情。列表没有业务规则，直接调用数据访问层。'},{at:'@router.delete("/chats/{chat_id}", status_code=204)',to:'return Response(status_code=204)',text:'删除对话，成功返回 204，没有正文。'},{at:'# main.py（导入加在其他路由的导入旁边',to:'return JSONResponse({"error": exc.message}, status_code=exc.status)',text:'在 main.py 里注册新路由，并把 ChatError 变成对应状态码的 {"error": …}，写法和 AIError 的处理一样。'}],solution:{code:'# app/services/chat.py\nimport logging\nimport os\n\nfrom app import ai_client\nfrom app import chat as store\nfrom app.db import get_question\n\nlog = logging.getLogger("zixishi")\n\nDAILY_LIMIT = max(int(os.getenv("CHAT_DAILY_LIMIT", "20") or 20), 1)\nHISTORY = 10\nTUTOR_PROMPT = "你是面试自习室的 AI 老师，学生是初学者。用简短、通俗的中文回答，必要时举一个小例子。"\n\n\nclass ChatError(Exception):\n    def __init__(self, status, message):\n        super().__init__(message)\n        self.status = status\n        self.message = message\n\n\ndef system_prompt(question_id):\n    """系统提示词：对话是针对某道题的，就把题目和参考答案也告诉模型"""\n    q = get_question(question_id) if question_id else None\n    if q is None:\n        return TUTOR_PROMPT\n    return f"{TUTOR_PROMPT}\\n学生正在看这道题：{q[\'title\']}\\n参考答案：{q[\'answer\']}"\n\n\ndef send(user_id, chat_id, question_id, message):\n    """提问：chat_id 为 None 是开一段新对话，否则是在已有的对话里追问"""\n    text = message.strip() if isinstance(message, str) else ""\n    if not text or len(text) > 1000:\n        raise ChatError(400, "消息不能为空，最多 1000 个字")\n    history = []\n    if chat_id is not None:\n        chat = store.get_chat(user_id, chat_id)\n        if chat is None:\n            raise ChatError(404, "对话不存在")\n        question_id = chat["questionId"]\n        history = store.list_messages(chat_id)[-HISTORY:]\n    elif question_id is not None and get_question(question_id) is None:\n        raise ChatError(404, "题目不存在")\n    used = store.take_quota(user_id, DAILY_LIMIT)\n    if used is None:\n        raise ChatError(429, "今天的提问次数用完了，明天再来")\n    messages = [{"role": "system", "content": system_prompt(question_id)}]\n    messages += [{"role": m["role"], "content": m["content"]} for m in history]\n    messages.append({"role": "user", "content": text})\n    try:\n        reply = ai_client.chat_messages(messages).strip()\n    except ai_client.NotConfigured as e:\n        store.refund_quota(user_id)\n        raise ChatError(503, str(e)) from None\n    except Exception:\n        store.refund_quota(user_id)\n        log.exception("调用 AI 出错")\n        raise ChatError(502, "AI 服务暂时不可用，请稍后再试") from None\n    new_id = store.save_turn(user_id, chat_id, question_id, text[:20], text, reply)\n    return {"chatId": new_id, "reply": reply, "remaining": DAILY_LIMIT - used}\n\n\ndef detail(user_id, chat_id):\n    chat = store.get_chat(user_id, chat_id)\n    if chat is None:\n        raise ChatError(404, "对话不存在")\n    return {**chat, "messages": store.list_messages(chat_id)}\n\n\ndef remove(user_id, chat_id):\n    if not store.delete_chat(user_id, chat_id):\n        raise ChatError(404, "对话不存在")\n\n\n# app/routers/chat.py\nfrom fastapi import APIRouter, Depends, Response\nfrom pydantic import BaseModel\n\nfrom app import chat as store\nfrom app.routers.study import require_user\nfrom app.services import chat\n\nrouter = APIRouter(prefix="/api")\n\n\nclass NewChatBody(BaseModel):\n    questionId: int | None = None\n    message: str = ""\n\n\nclass MessageBody(BaseModel):\n    message: str = ""\n\n\n@router.post("/chats", status_code=201)\ndef start(body: NewChatBody, user=Depends(require_user)):\n    return chat.send(user["id"], None, body.questionId, body.message)\n\n\n@router.post("/chats/{chat_id}/messages")\ndef follow_up(chat_id: int, body: MessageBody, user=Depends(require_user)):\n    return chat.send(user["id"], chat_id, None, body.message)\n\n\n@router.get("/chats")\ndef history(user=Depends(require_user)):\n    return store.list_chats(user["id"])\n\n\n@router.get("/chats/{chat_id}")\ndef detail(chat_id: int, user=Depends(require_user)):\n    return chat.detail(user["id"], chat_id)\n\n\n@router.delete("/chats/{chat_id}", status_code=204)\ndef remove(chat_id: int, user=Depends(require_user)):\n    chat.remove(user["id"], chat_id)\n    return Response(status_code=204)\n\n\n# main.py（导入加在其他路由的导入旁边；另外两段加在 ai 路由和 AIError 处理的后面）\nfrom app.routers import chat as chat_routes\nfrom app.services.chat import ChatError\n\napp.include_router(chat_routes.router)\n\n\n@app.exception_handler(ChatError)\nasync def chat_error(request: Request, exc: ChatError):\n    return JSONResponse({"error": exc.message}, status_code=exc.status)',explain:[{at:'# app/services/chat.py',to:'log = logging.getLogger("zixishi")',text:'业务逻辑层：用到任务一改好的 ai_client、对话的数据访问层（起个短名字 store）和题目的数据访问层。'},{at:'DAILY_LIMIT = max(int(os.getenv("CHAT_DAILY_LIMIT", "20") or 20), 1)',text:'每人每天能问几次，从环境变量读，默认 20，至少是 1。大模型按用量收费，不限制的话，一个人写个脚本循环提问就能把你的余额刷光。'},{at:'HISTORY = 10',text:'追问时最多带上最近 10 条历史消息（5 轮问答）。对话越长，每次发给模型的内容越多、越贵，所以只带最近的。10 是偶数，截出来的第一条正好是学生的提问。'},{at:'TUTOR_PROMPT =',text:'AI 老师的系统提示词。'},{at:'class ChatError(Exception):',to:'self.message = message',text:'带状态码的业务错误，和前几关的 ExamError、AIError 是同一个套路。'},{at:'def system_prompt(question_id):',to:'return f"{TUTOR_PROMPT}',text:'对话关联了题目时，把题目和参考答案拼进系统提示词，模型才知道学生在问哪道题。这些内容来自数据库，不是用户输入的，所以放在 system 消息里。'},{at:'def send(user_id, chat_id, question_id, message):',to:'raise ChatError(400, "消息不能为空，最多 1000 个字")',text:'先校验消息。Python 的 len 对字符串数的就是“字”数，一个汉字算一个。'},{at:'history = []',to:'history = store.list_messages(chat_id)[-HISTORY:]',text:'追问：get_chat 同时检查“存在”和“是我的”，查不到一律 404。关联的题目以对话里记的为准，再取出最近 10 条历史。'},{at:'elif question_id is not None and get_question(question_id) is None:',to:'raise ChatError(404, "题目不存在")',text:'新对话：传了题目 id 就确认题目存在；没传就不关联题目。'},{at:'used = store.take_quota(user_id, DAILY_LIMIT)',to:'raise ChatError(429, "今天的提问次数用完了，明天再来")',text:'校验都通过了，才占用一次。429 的意思是“请求太多”。注意顺序：先占用，再去调用大模型。如果先调用、成功后再记次数，同一个人同时发 100 个请求，就都能通过。'},{at:'messages = [{"role": "system", "content": system_prompt(question_id)}]',to:'messages.append({"role": "user", "content": text})',text:'发给模型的消息：系统提示词在最前面，然后是历史消息，最后是这次的问题。模型本身不记得之前聊过什么，“多轮对话”就是每次把之前的对话再发一遍。'},{at:'try:',to:'raise ChatError(502, "AI 服务暂时不可用，请稍后再试") from None',text:'调用失败：先把刚才占用的次数还回去，不能让用户为失败的请求买单。然后和第 14 关一样，没配置是 503，其他都是 502，详细原因只写进日志。'},{at:'new_id = store.save_turn(',to:'return {"chatId": new_id, "reply": reply, "remaining": DAILY_LIMIT - used}',text:'成功后才保存：一问一答同时写入。失败的提问不会留在对话里，下次追问也就不会把一句没有回答的话发给模型。remaining 是今天还能问几次。'},{at:'def detail(user_id, chat_id):',to:'return {**chat, "messages": store.list_messages(chat_id)}',text:'详情：对话的基本信息加上全部消息。'},{at:'def remove(user_id, chat_id):',to:'raise ChatError(404, "对话不存在")',text:'删除：数据访问层返回 False 说明对话不存在或不是自己的。'},{at:'# app/routers/chat.py',to:'router = APIRouter(prefix="/api")',text:'接口层：只负责取参数、调用业务逻辑。'},{at:'class MessageBody(BaseModel):',to:'message: str = ""',text:'追问只需要消息内容。'},{at:'class NewChatBody(BaseModel):',to:'message: str = ""',text:'两个请求正文。questionId 可以不传（int | None）；message 没传时是空字符串，交给业务逻辑层统一返回 400。'},{at:'@router.post("/chats", status_code=201)',to:'return chat.send(user["id"], None, body.questionId, body.message)',text:'开新对话：chat_id 传 None，返回 201（新建了资源）。五个接口都要先登录，用户 id 只从会话里取。'},{at:'@router.post("/chats/{chat_id}/messages")',to:'return chat.send(user["id"], chat_id, None, body.message)',text:'在已有对话里追问：对话 id 来自路径，question_id 传 None（用对话里记的）。'},{at:'@router.get("/chats")',to:'return chat.detail(user["id"], chat_id)',text:'历史列表和某段对话的详情。列表没有业务规则，直接调用数据访问层。'},{at:'@router.delete("/chats/{chat_id}", status_code=204)',to:'return Response(status_code=204)',text:'删除对话，成功返回 204，没有正文。'},{at:'# main.py（导入加在其他路由的导入旁边',to:'return JSONResponse({"error": exc.message}, status_code=exc.status)',text:'在 main.py 里注册新路由，并把 ChatError 变成对应状态码的 {"error": …}，写法和 AIError 的处理一样。'}]}}}},
  {title:'任务三：页面上的“问 AI 老师”',body:'在题目详情页上可以针对这道题提问、接着追问，刷新页面后对话还在。按你选的前端做法显示具体写法。',variants:{html:{body:'在题目详情页上加一个对话框：可以针对这道题提问、接着追问；刷新页面后，之前的对话还在。',practice:{steps:['在 question.html 里加上“问 AI 老师”这一块，在 question.js 最后补完 TODO 1 到 5。','登录后打开一道题，问一个问题，再追问一句；刷新页面，确认两轮对话都还在。'],expect:'页面上依次显示：我：…… / AI 老师：…… / 我：…… / AI 老师：……，下面提示“今天还可以问 18 次”'},code:'<!-- question.html：在第 14 关的 AI 评分区域后面、</article> 前面加上 -->\n<section>\n  <h2>问 AI 老师</h2>\n  <div id="chatLog"></div>\n  <textarea id="chatInput" rows="3" cols="60" maxlength="1000" placeholder="哪里没看懂？可以接着追问"></textarea>\n  <p><button id="chatSend">发送</button> <span id="chatHint"></span></p>\n</section>\n\n// question.js：在文件最后加上（postJSON 是第 14 关写的）\nlet chatId = null;\n\nfunction addMessage(role, content) {\n  const p = document.createElement("p");\n  p.textContent = (role === "user" ? "我：" : "AI 老师：") + content;\n  document.getElementById("chatLog").append(p);\n}\n\n// 打开页面时，找出针对这道题的最近一段对话，把里面的消息显示出来\nasync function loadChat() {\n  // TODO 1：GET /api/chats（没登录会返回 401，这时直接 return）；在列表里找 questionId 等于这道题的第一段对话\n  // TODO 2：找到了就 GET /api/chats/{id} 取详情，把 chatId 记下来，用 addMessage 把每条消息显示出来\n}\n\ndocument.getElementById("chatSend").addEventListener("click", async (event) => {\n  const input = document.getElementById("chatInput");\n  const hint = document.getElementById("chatHint");\n  const message = input.value.trim();\n  if (!message) return;\n  // TODO 3：请求期间禁用按钮，提示“AI 老师正在回答…”\n  // TODO 4：chatId 是 null 就 POST /api/chats（带上 questionId 和 message），否则 POST /api/chats/{chatId}/messages；\n  //         成功后记下 data.chatId，显示这一问一答，清空输入框，提示今天还可以问几次\n  // TODO 5：失败时把错误信息显示在提示里（比如“今天的提问次数用完了”）；最后不管成功失败都恢复按钮\n});\n\nloadChat().catch(() => {});\n',explain:[{at:'<!-- question.html',to:'</section>',text:'详情页再加一块“问 AI 老师”：chatLog 用来显示对话，下面是输入框、发送按钮和一行提示。'},{at:'// question.js',to:'let chatId = null;',text:'chatId 记着当前这段对话的编号：null 表示还没开始，第一次提问成功后变成后端返回的编号，之后的提问就是追问。'},{at:'function addMessage(role, content) {',to:'// 打开页面时，找出针对这道题的最近一段对话，把里面的消息显示出来',text:'往对话区域加一行。用 textContent 而不是 innerHTML：AI 的回答里如果有 HTML 标签，也只会当作普通文字显示。'},{at:'async function loadChat() {',text:'打开页面时恢复之前的对话，要你补全。',to:'// TODO 2：找到了就 GET /api/chats/{id} 取详情，把 chatId 记下来，用 addMessage 把每条消息显示出来'},{at:'document.getElementById("chatSend").addEventListener("click", async (event) => {',to:'});',text:'点“发送”时：取出输入的内容，空的就不发。后面的部分要你补全。'},{at:'loadChat().catch(() => {});',text:'页面加载时调用。恢复历史失败不影响看题，所以出错时什么都不做。'}],solution:{code:'<!-- question.html：在第 14 关的 AI 评分区域后面、</article> 前面加上 -->\n<section>\n  <h2>问 AI 老师</h2>\n  <div id="chatLog"></div>\n  <textarea id="chatInput" rows="3" cols="60" maxlength="1000" placeholder="哪里没看懂？可以接着追问"></textarea>\n  <p><button id="chatSend">发送</button> <span id="chatHint"></span></p>\n</section>\n\n// question.js：在文件最后加上（postJSON 是第 14 关写的）\nlet chatId = null;\n\nfunction addMessage(role, content) {\n  const p = document.createElement("p");\n  p.textContent = (role === "user" ? "我：" : "AI 老师：") + content;\n  document.getElementById("chatLog").append(p);\n}\n\n// 打开页面时，找出针对这道题的最近一段对话，把里面的消息显示出来\nasync function loadChat() {\n  const res = await fetch("/api/chats");\n  if (!res.ok) return;\n  const mine = (await res.json()).find((c) => c.questionId === Number(id));\n  if (!mine) return;\n  const detail = await (await fetch(`/api/chats/${mine.id}`)).json();\n  chatId = mine.id;\n  for (const m of detail.messages) addMessage(m.role, m.content);\n}\n\ndocument.getElementById("chatSend").addEventListener("click", async (event) => {\n  const input = document.getElementById("chatInput");\n  const hint = document.getElementById("chatHint");\n  const message = input.value.trim();\n  if (!message) return;\n  event.target.disabled = true;\n  hint.textContent = "AI 老师正在回答…";\n  try {\n    const data = chatId === null\n      ? await postJSON("/api/chats", { questionId: Number(id), message })\n      : await postJSON(`/api/chats/${chatId}/messages`, { message });\n    chatId = data.chatId;\n    addMessage("user", message);\n    addMessage("assistant", data.reply);\n    input.value = "";\n    hint.textContent = `今天还可以问 ${data.remaining} 次`;\n  } catch (err) {\n    hint.textContent = err.message;\n  } finally {\n    event.target.disabled = false;\n  }\n});\n\nloadChat().catch(() => {});\n',explain:[{at:'<!-- question.html',to:'</section>',text:'详情页再加一块“问 AI 老师”：chatLog 用来显示对话，下面是输入框、发送按钮和一行提示。'},{at:'// question.js',to:'let chatId = null;',text:'chatId 记着当前这段对话的编号：null 表示还没开始，第一次提问成功后变成后端返回的编号，之后的提问就是追问。'},{at:'function addMessage(role, content) {',to:'// 打开页面时，找出针对这道题的最近一段对话，把里面的消息显示出来',text:'往对话区域加一行。用 textContent 而不是 innerHTML：AI 的回答里如果有 HTML 标签，也只会当作普通文字显示。'},{at:'async function loadChat() {',to:'for (const m of detail.messages) addMessage(m.role, m.content);',text:'先取我的对话列表（后端已经按最近提问排好序），find 找到第一段 questionId 等于这道题的，就是最近的那段；再取它的详情，把消息一条条显示出来，并记下 chatId，之后的提问就接在这段对话后面。'},{at:'document.getElementById("chatSend").addEventListener("click", async (event) => {',to:'try {',text:'发送前先禁用按钮，避免连点两次发出两个请求、扣两次次数；并告诉用户正在等回答。'},{at:'const data = chatId === null',to:': await postJSON(`/api/chats/${chatId}/messages`, { message });',text:'还没有对话就开一段新的（带上题目编号），已经有了就追问。两个接口返回的格式一样。'},{at:'chatId = data.chatId;',to:'hint.textContent = `今天还可以问 ${data.remaining} 次`;',text:'成功后才把这一问一答显示出来，和后端“成功才保存”保持一致。'},{at:'} catch (err) {',to:'});',text:'失败时显示后端给的原因；输入框里的内容不清空，用户可以直接重试。finally 里的代码不管成功失败都会执行。'},{at:'loadChat().catch(() => {});',text:'页面加载时调用。恢复历史失败不影响看题，所以出错时什么都不做。'}]}},react:{body:'在题目详情页上加一个对话组件：可以针对这道题提问、接着追问；刷新页面后，之前的对话还在。',practice:{steps:['新建 src/ChatPanel.jsx，补完 TODO 1 到 5；在 QuestionDetail.jsx 里导入并放上 <ChatPanel questionId={question.id} />。','npm run build（或开发服务器），登录后打开一道题，问一个问题，再追问一句；刷新页面，确认两轮对话都还在。'],expect:'页面上依次显示：我：…… / AI 老师：…… / 我：…… / AI 老师：……，下面提示“今天还可以问 18 次”'},code:'// src/ChatPanel.jsx（在 QuestionDetail 里 <AIPanel … /> 的后面放上 <ChatPanel questionId={question.id} />，顶部导入它）\nimport { useEffect, useState } from "react";\n\nasync function postJSON(url, body) {\n  const res = await fetch(url, {\n    method: "POST",\n    headers: { "Content-Type": "application/json" },\n    body: JSON.stringify(body),\n  });\n  const data = await res.json();\n  if (!res.ok) throw new Error(res.status === 401 ? "请先登录" : data.error);\n  return data;\n}\n\nexport default function ChatPanel({ questionId }) {\n  const [chatId, setChatId] = useState(null);\n  const [messages, setMessages] = useState([]);\n  const [input, setInput] = useState("");\n  const [busy, setBusy] = useState(false);\n  const [hint, setHint] = useState("");\n\n  // 打开页面时，找出针对这道题的最近一段对话\n  useEffect(() => {\n    // TODO 1：GET /api/chats（不是 2xx 就什么都不做）；在列表里找 questionId 等于这道题的第一段对话\n    // TODO 2：找到了就 GET /api/chats/{id} 取详情，setChatId、setMessages\n  }, [questionId]);\n\n  async function send() {\n    const message = input.trim();\n    if (!message || busy) return;\n    // TODO 3：setBusy(true)，提示“AI 老师正在回答…”\n    // TODO 4：chatId 是 null 就 POST /api/chats（带上 questionId 和 message），否则 POST /api/chats/{chatId}/messages；\n    //         成功后 setChatId，把这一问一答追加到 messages，清空输入框，提示今天还可以问几次\n    // TODO 5：失败时把错误信息放进提示；最后 setBusy(false)\n  }\n\n  return (\n    <section>\n      <h2>问 AI 老师</h2>\n      {messages.map((m, i) => (\n        <p key={i}>{m.role === "user" ? "我：" : "AI 老师："}{m.content}</p>\n      ))}\n      <textarea rows={3} cols={60} maxLength={1000} placeholder="哪里没看懂？可以接着追问"\n        value={input} onChange={(e) => setInput(e.target.value)} />\n      <p><button onClick={send} disabled={busy}>发送</button> <span>{hint}</span></p>\n    </section>\n  );\n}',explain:[{at:'// src/ChatPanel.jsx',to:'import { useEffect, useState } from "react";',text:'把对话框写成一个独立的组件，详情页只要放上它，传入题目编号。'},{at:'async function postJSON(url, body) {',to:'return data;',text:'发 POST 请求的小工具：失败时把后端的 error 抛出来，没登录时换成“请先登录”。'},{at:'export default function ChatPanel({ questionId }) {',to:'// 打开页面时，找出针对这道题的最近一段对话',text:'五个状态：当前对话的编号（null 表示还没开始）、已经显示的消息、输入框的内容、是否正在请求、提示文字。'},{at:'useEffect(() => {',text:'组件显示出来（或题目换了）时恢复之前的对话，要你补全。',to:'}, [questionId]);'},{at:'async function send() {',to:'// TODO 5：失败时把错误信息放进提示；最后 setBusy(false)',text:'点“发送”时：空的不发，正在请求时也不重复发。后面的部分要你补全。'},{at:'return (',to:'))}',text:'界面：把 messages 里的每条消息显示成一段。'},{at:'<textarea rows={3} cols={60} maxLength={1000}',to:');',text:'输入框的内容由 input 状态控制；请求期间按钮禁用。React 默认会把文字转义，AI 的回答里有 HTML 标签也只当普通文字显示。'}],solution:{code:'// src/ChatPanel.jsx（在 QuestionDetail 里 <AIPanel … /> 的后面放上 <ChatPanel questionId={question.id} />，顶部导入它）\nimport { useEffect, useState } from "react";\n\nasync function postJSON(url, body) {\n  const res = await fetch(url, {\n    method: "POST",\n    headers: { "Content-Type": "application/json" },\n    body: JSON.stringify(body),\n  });\n  const data = await res.json();\n  if (!res.ok) throw new Error(res.status === 401 ? "请先登录" : data.error);\n  return data;\n}\n\nexport default function ChatPanel({ questionId }) {\n  const [chatId, setChatId] = useState(null);\n  const [messages, setMessages] = useState([]);\n  const [input, setInput] = useState("");\n  const [busy, setBusy] = useState(false);\n  const [hint, setHint] = useState("");\n\n  // 打开页面时，找出针对这道题的最近一段对话\n  useEffect(() => {\n    let ignore = false;\n    async function load() {\n      const res = await fetch("/api/chats");\n      if (!res.ok) return;\n      const mine = (await res.json()).find((c) => c.questionId === questionId);\n      if (!mine) return;\n      const detail = await (await fetch(`/api/chats/${mine.id}`)).json();\n      if (ignore) return;\n      setChatId(mine.id);\n      setMessages(detail.messages);\n    }\n    load().catch(() => {});\n    return () => {\n      ignore = true;\n    };\n  }, [questionId]);\n\n  async function send() {\n    const message = input.trim();\n    if (!message || busy) return;\n    setBusy(true);\n    setHint("AI 老师正在回答…");\n    try {\n      const data = chatId === null\n        ? await postJSON("/api/chats", { questionId, message })\n        : await postJSON(`/api/chats/${chatId}/messages`, { message });\n      setChatId(data.chatId);\n      setMessages((list) => [...list, { role: "user", content: message }, { role: "assistant", content: data.reply }]);\n      setInput("");\n      setHint(`今天还可以问 ${data.remaining} 次`);\n    } catch (err) {\n      setHint(err.message);\n    } finally {\n      setBusy(false);\n    }\n  }\n\n  return (\n    <section>\n      <h2>问 AI 老师</h2>\n      {messages.map((m, i) => (\n        <p key={i}>{m.role === "user" ? "我：" : "AI 老师："}{m.content}</p>\n      ))}\n      <textarea rows={3} cols={60} maxLength={1000} placeholder="哪里没看懂？可以接着追问"\n        value={input} onChange={(e) => setInput(e.target.value)} />\n      <p><button onClick={send} disabled={busy}>发送</button> <span>{hint}</span></p>\n    </section>\n  );\n}',explain:[{at:'// src/ChatPanel.jsx',to:'import { useEffect, useState } from "react";',text:'把对话框写成一个独立的组件，详情页只要放上它，传入题目编号。'},{at:'async function postJSON(url, body) {',to:'return data;',text:'发 POST 请求的小工具：失败时把后端的 error 抛出来，没登录时换成“请先登录”。'},{at:'export default function ChatPanel({ questionId }) {',to:'// 打开页面时，找出针对这道题的最近一段对话',text:'五个状态：当前对话的编号（null 表示还没开始）、已经显示的消息、输入框的内容、是否正在请求、提示文字。'},{at:'useEffect(() => {',to:'}, [questionId]);',text:'先取我的对话列表（后端已经按最近提问排好序），find 找到第一段 questionId 等于这道题的；再取它的详情放进状态。ignore 是防止“请求还没回来，组件已经换了题目”时把旧数据写进去：清理函数会把它改成 true。'},{at:'async function send() {',to:'try {',text:'发送前把 busy 设成 true，按钮随之禁用，避免连点两次扣两次次数。'},{at:'const data = chatId === null',to:': await postJSON(`/api/chats/${chatId}/messages`, { message });',text:'还没有对话就开一段新的（带上题目编号），已经有了就追问。'},{at:'setChatId(data.chatId);',to:'setHint(`今天还可以问 ${data.remaining} 次`);',text:'成功后才把这一问一答追加到列表里。setMessages 传函数，拿到的 list 一定是最新的。'},{at:'} catch (err) {',to:'setBusy(false);',text:'失败时显示后端给的原因，输入框的内容不清空，可以直接重试。'},{at:'return (',to:'))}',text:'界面：把 messages 里的每条消息显示成一段。'},{at:'<textarea rows={3} cols={60} maxLength={1000}',to:');',text:'输入框的内容由 input 状态控制；请求期间按钮禁用。React 默认会把文字转义，AI 的回答里有 HTML 标签也只当普通文字显示。'}]}},'template-node':{body:'模板渲染的做法：给每道题加一个单独的对话页面 /questions/题目编号/chat。打开页面时显示针对这道题的最近一段对话；提交表单后由后端调用业务逻辑层，再重定向回这个页面（“提交后重定向”，刷新页面不会重复提问）。',practice:{steps:['在 app.js 里加上两个页面路由，补完 TODO。','新建对话页面的模板，再在题目详情页的模板里加一个指向它的链接。','登录后打开一道题，点“问 AI 老师”，问一个问题，再追问一句；刷新页面，确认两轮对话都还在。'],expect:'页面上依次显示：我：…… / AI 老师：…… / 我：…… / AI 老师：……'},code:'// app.js（加在 app.use("/auth", …) 的前面）\nconst chat = require("./src/services/chat");\n\n// 针对这道题的最近一段对话（没有时 chatId 是 null、messages 是空数组）\nfunction latestChat(userId, questionId) {\n  const mine = chat.list(userId).find((c) => c.questionId === questionId);\n  return mine ? { chatId: mine.id, messages: chat.detail(userId, mine.id).messages } : { chatId: null, messages: [] };\n}\n\napp.get("/questions/:id/chat", pageUser, (req, res) => {\n  // TODO 1：题目不存在时渲染 question 模板并返回 404（和详情页一样）；\n  //         否则渲染 chat 模板，传入 question、error（空字符串）以及 latestChat 的结果\n});\n\napp.post("/questions/:id/chat", pageUser, async (req, res, next) => {\n  // TODO 2：题目不存在同上。先用 latestChat 找到当前对话，再调用 chat.send（消息在 req.body.message）\n  // TODO 3：成功后 303 重定向回 /questions/题目编号/chat；\n  //         ChatError 时用它的状态码重新渲染 chat 模板，把错误信息传给 error；其他错误交给 next\n});\n\n<!-- views/chat.ejs -->\n<!DOCTYPE html>\n<html lang="zh-CN">\n<head>\n  <meta charset="utf-8">\n  <title>问 AI 老师 - 面试自习室</title>\n</head>\n<body>\n  <p><a href="/questions/<%= question.id %>">← 返回题目</a></p>\n  <h1>问 AI 老师：<%= question.title %></h1>\n  <% for (const m of messages) { %>\n  <p><%= m.role === "user" ? "我：" : "AI 老师：" %><%= m.content %></p>\n  <% } %>\n  <% if (error) { %><p><%= error %></p><% } %>\n  <form method="post" action="/questions/<%= question.id %>/chat">\n    <textarea name="message" rows="3" cols="60" maxlength="1000" placeholder="哪里没看懂？可以接着追问"></textarea>\n    <p><button>发送</button></p>\n  </form>\n</body>\n</html>\n\n<!-- views/question.ejs：在 </article> 前面加一个链接 -->\n<p><a href="/questions/<%= question.id %>/chat">问 AI 老师</a></p>',explain:[{at:'// app.js（加在 app.use("/auth", …) 的前面）',to:'// 针对这道题的最近一段对话（没有时 chatId 是 null、messages 是空数组）',text:'页面路由直接调用业务逻辑层，不用再绕一圈去请求自己的 JSON 接口。'},{at:'function latestChat(userId, questionId) {',to:'}',text:'对话列表已经按最近提问排好序，find 找到第一段针对这道题的就是最近的那段，再取它的全部消息。'},{at:'app.get("/questions/:id/chat", pageUser, (req, res) => {',text:'显示对话页面，要你补全。pageUser 是前面写的：没登录就跳到登录页。',to:'});'},{at:'app.post("/questions/:id/chat", pageUser, async (req, res, next) => {',text:'处理提交的问题，要你补全。',to:'});'},{at:'<!-- views/chat.ejs -->',to:'</html>',text:'对话页面的模板：循环显示每条消息，有错误就显示错误，最下面是提问的表单。模板默认会把内容转义，AI 的回答里有 HTML 标签也只当普通文字显示。'},{at:'<!-- views/question.ejs：在 </article> 前面加一个链接 -->',text:'题目详情页上加一个进入对话页面的链接。',to:'<p><a href="/questions/<%= question.id %>/chat">问 AI 老师</a></p>'}],solution:{code:'// app.js（加在 app.use("/auth", …) 的前面）\nconst chat = require("./src/services/chat");\n\n// 针对这道题的最近一段对话（没有时 chatId 是 null、messages 是空数组）\nfunction latestChat(userId, questionId) {\n  const mine = chat.list(userId).find((c) => c.questionId === questionId);\n  return mine ? { chatId: mine.id, messages: chat.detail(userId, mine.id).messages } : { chatId: null, messages: [] };\n}\n\napp.get("/questions/:id/chat", pageUser, (req, res) => {\n  const question = getQuestion(Number(req.params.id));\n  if (!question) return res.status(404).render("question", { question: null, myAnswer: "", aiText: "" });\n  res.render("chat", { question, error: "", ...latestChat(req.user.id, question.id) });\n});\n\napp.post("/questions/:id/chat", pageUser, async (req, res, next) => {\n  const question = getQuestion(Number(req.params.id));\n  if (!question) return res.status(404).render("question", { question: null, myAnswer: "", aiText: "" });\n  const current = latestChat(req.user.id, question.id);\n  try {\n    await chat.send(req.user.id, current.chatId, question.id, req.body.message);\n    res.redirect(303, `/questions/${question.id}/chat`);\n  } catch (err) {\n    if (!(err instanceof chat.ChatError)) return next(err);\n    res.status(err.status).render("chat", { question, error: err.message, ...current });\n  }\n});\n\n<!-- views/chat.ejs -->\n<!DOCTYPE html>\n<html lang="zh-CN">\n<head>\n  <meta charset="utf-8">\n  <title>问 AI 老师 - 面试自习室</title>\n</head>\n<body>\n  <p><a href="/questions/<%= question.id %>">← 返回题目</a></p>\n  <h1>问 AI 老师：<%= question.title %></h1>\n  <% for (const m of messages) { %>\n  <p><%= m.role === "user" ? "我：" : "AI 老师：" %><%= m.content %></p>\n  <% } %>\n  <% if (error) { %><p><%= error %></p><% } %>\n  <form method="post" action="/questions/<%= question.id %>/chat">\n    <textarea name="message" rows="3" cols="60" maxlength="1000" placeholder="哪里没看懂？可以接着追问"></textarea>\n    <p><button>发送</button></p>\n  </form>\n</body>\n</html>\n\n<!-- views/question.ejs：在 </article> 前面加一个链接 -->\n<p><a href="/questions/<%= question.id %>/chat">问 AI 老师</a></p>',explain:[{at:'// app.js（加在 app.use("/auth", …) 的前面）',to:'// 针对这道题的最近一段对话（没有时 chatId 是 null、messages 是空数组）',text:'页面路由直接调用业务逻辑层，不用再绕一圈去请求自己的 JSON 接口。'},{at:'function latestChat(userId, questionId) {',to:'}',text:'对话列表已经按最近提问排好序，find 找到第一段针对这道题的就是最近的那段，再取它的全部消息。'},{at:'app.get("/questions/:id/chat", pageUser, (req, res) => {',to:'res.render("chat", { question, error: "", ...latestChat(req.user.id, question.id) });',text:'显示页面：题目不存在返回 404；否则把题目和最近的对话交给模板。...latestChat(…) 把 chatId 和 messages 两个字段展开进去。'},{at:'app.post("/questions/:id/chat", pageUser, async (req, res, next) => {',to:'res.redirect(303, `/questions/${question.id}/chat`);',text:'提交问题：有对话就追问，没有就新开一段（chatId 是 null）。成功后重定向回对话页面，由那边重新查出最新的消息来显示；这样用户刷新页面只是重新打开页面，不会把问题再提交一次。'},{at:'} catch (err) {',to:'res.status(err.status).render("chat", { question, error: err.message, ...current });',text:'业务错误（消息为空、次数用完、AI 出错）就留在当前页面显示原因，状态码用错误自带的；其他错误交给全局错误处理。'},{at:'<!-- views/chat.ejs -->',to:'</html>',text:'对话页面的模板：循环显示每条消息，有错误就显示错误，最下面是提问的表单。模板默认会把内容转义，AI 的回答里有 HTML 标签也只当普通文字显示。'},{at:'<!-- views/question.ejs：在 </article> 前面加一个链接 -->',text:'题目详情页上加一个进入对话页面的链接。',to:'<p><a href="/questions/<%= question.id %>/chat">问 AI 老师</a></p>'}]}},'template-python':{body:'模板渲染的做法：给每道题加一个单独的对话页面 /questions/题目编号/chat。打开页面时显示针对这道题的最近一段对话；提交表单后由后端调用业务逻辑层，再重定向回这个页面（“提交后重定向”，刷新页面不会重复提问）。',practice:{steps:['在 main.py 里加上两个页面路由，补完 TODO。','新建对话页面的模板，再在题目详情页的模板里加一个指向它的链接。','登录后打开一道题，点“问 AI 老师”，问一个问题，再追问一句；刷新页面，确认两轮对话都还在。'],expect:'页面上依次显示：我：…… / AI 老师：…… / 我：…… / AI 老师：……'},code:'# main.py（加在 @app.api_route("/api/{rest:path}" …) 的前面；顶部导入 from app.services import chat as chat_service）\ndef latest_chat(user_id, question_id):\n    """针对这道题的最近一段对话（没有时 chat_id 是 None、messages 是空列表）"""\n    for c in chat_store.list_chats(user_id):\n        if c["questionId"] == question_id:\n            return c["id"], chat_store.list_messages(c["id"])\n    return None, []\n\n\n@app.get("/questions/{qid}/chat")\ndef chat_page(request: Request, qid: int):\n    # TODO 1：没登录跳到 /login；题目不存在时渲染 question.html 并返回 404（和详情页一样）；\n    #         否则渲染 chat.html，传入 question、messages（latest_chat 的结果）和 error（空字符串）\n    ...\n\n\n@app.post("/questions/{qid}/chat")\ndef chat_submit(request: Request, qid: int, message: str = Form("")):\n    # TODO 2：没登录、题目不存在同上。先用 latest_chat 找到当前对话，再调用 chat_service.send\n    # TODO 3：ChatError 时用它的状态码重新渲染 chat.html，把错误信息传给 error；\n    #         成功后 303 重定向回 /questions/题目编号/chat\n    ...\n\n<!-- templates/chat.html -->\n<!DOCTYPE html>\n<html lang="zh-CN">\n<head>\n  <meta charset="utf-8">\n  <title>问 AI 老师 - 面试自习室</title>\n</head>\n<body>\n  <p><a href="/questions/{{ question.id }}">← 返回题目</a></p>\n  <h1>问 AI 老师：{{ question.title }}</h1>\n  {% for m in messages %}\n  <p>{{ "我：" if m.role == "user" else "AI 老师：" }}{{ m.content }}</p>\n  {% endfor %}\n  {% if error %}<p>{{ error }}</p>{% endif %}\n  <form method="post" action="/questions/{{ question.id }}/chat">\n    <textarea name="message" rows="3" cols="60" maxlength="1000" placeholder="哪里没看懂？可以接着追问"></textarea>\n    <p><button>发送</button></p>\n  </form>\n</body>\n</html>\n\n<!-- templates/question.html：在 </article> 前面加一个链接 -->\n<p><a href="/questions/{{ question.id }}/chat">问 AI 老师</a></p>',explain:[{at:'# main.py（加在 @app.api_route("/api/{rest:path}" …) 的前面',text:'页面路由直接调用业务逻辑层，不用再绕一圈去请求自己的 JSON 接口。还要在顶部加两行导入：from app import chat as chat_store 和 from app.services import chat as chat_service。'},{at:'def latest_chat(user_id, question_id):',to:'@app.get("/questions/{qid}/chat")',text:'对话列表已经按最近提问排好序，第一段针对这道题的就是最近的那段，再取它的全部消息。'},{at:'def chat_page(request: Request, qid: int):',text:'显示对话页面，要你补全。',to:'@app.post("/questions/{qid}/chat")'},{at:'def chat_submit(request: Request, qid: int, message: str = Form("")):',text:'处理提交的问题，要你补全。Form("") 表示从表单里取 message，没填时是空字符串。',to:'...'},{at:'<!-- templates/chat.html -->',to:'</html>',text:'对话页面的模板：循环显示每条消息，有错误就显示错误，最下面是提问的表单。模板默认会把内容转义，AI 的回答里有 HTML 标签也只当普通文字显示。'},{at:'<!-- templates/question.html：在 </article> 前面加一个链接 -->',text:'题目详情页上加一个进入对话页面的链接。',to:'<p><a href="/questions/{{ question.id }}/chat">问 AI 老师</a></p>'}],solution:{code:'# main.py（加在 @app.api_route("/api/{rest:path}" …) 的前面；顶部导入 from app.services import chat as chat_service）\ndef latest_chat(user_id, question_id):\n    """针对这道题的最近一段对话（没有时 chat_id 是 None、messages 是空列表）"""\n    for c in chat_store.list_chats(user_id):\n        if c["questionId"] == question_id:\n            return c["id"], chat_store.list_messages(c["id"])\n    return None, []\n\n\n@app.get("/questions/{qid}/chat")\ndef chat_page(request: Request, qid: int):\n    user = page_user(request)\n    if user is None:\n        return RedirectResponse("/login", status_code=303)\n    question = get_question(qid)\n    if question is None:\n        return templates.TemplateResponse(request, "question.html", {"question": None}, status_code=404)\n    chat_id, messages = latest_chat(user["id"], qid)\n    return templates.TemplateResponse(request, "chat.html", {"question": question, "messages": messages, "error": ""})\n\n\n@app.post("/questions/{qid}/chat")\ndef chat_submit(request: Request, qid: int, message: str = Form("")):\n    user = page_user(request)\n    if user is None:\n        return RedirectResponse("/login", status_code=303)\n    question = get_question(qid)\n    if question is None:\n        return templates.TemplateResponse(request, "question.html", {"question": None}, status_code=404)\n    chat_id, messages = latest_chat(user["id"], qid)\n    try:\n        chat_service.send(user["id"], chat_id, qid, message)\n    except chat_service.ChatError as e:\n        return templates.TemplateResponse(\n            request, "chat.html", {"question": question, "messages": messages, "error": e.message}, status_code=e.status\n        )\n    return RedirectResponse(f"/questions/{qid}/chat", status_code=303)\n\n<!-- templates/chat.html -->\n<!DOCTYPE html>\n<html lang="zh-CN">\n<head>\n  <meta charset="utf-8">\n  <title>问 AI 老师 - 面试自习室</title>\n</head>\n<body>\n  <p><a href="/questions/{{ question.id }}">← 返回题目</a></p>\n  <h1>问 AI 老师：{{ question.title }}</h1>\n  {% for m in messages %}\n  <p>{{ "我：" if m.role == "user" else "AI 老师：" }}{{ m.content }}</p>\n  {% endfor %}\n  {% if error %}<p>{{ error }}</p>{% endif %}\n  <form method="post" action="/questions/{{ question.id }}/chat">\n    <textarea name="message" rows="3" cols="60" maxlength="1000" placeholder="哪里没看懂？可以接着追问"></textarea>\n    <p><button>发送</button></p>\n  </form>\n</body>\n</html>\n\n<!-- templates/question.html：在 </article> 前面加一个链接 -->\n<p><a href="/questions/{{ question.id }}/chat">问 AI 老师</a></p>',explain:[{at:'# main.py（加在 @app.api_route("/api/{rest:path}" …) 的前面',text:'页面路由直接调用业务逻辑层，不用再绕一圈去请求自己的 JSON 接口。还要在顶部加两行导入：from app import chat as chat_store 和 from app.services import chat as chat_service。'},{at:'def latest_chat(user_id, question_id):',to:'@app.get("/questions/{qid}/chat")',text:'对话列表已经按最近提问排好序，第一段针对这道题的就是最近的那段，再取它的全部消息。'},{at:'def chat_page(request: Request, qid: int):',to:'@app.post("/questions/{qid}/chat")',text:'显示页面：没登录跳到登录页，题目不存在返回 404；否则把题目和最近的对话交给模板。'},{at:'def chat_submit(request: Request, qid: int, message: str = Form("")):',to:'chat_service.send(user["id"], chat_id, qid, message)',text:'提交问题：有对话就追问，没有就新开一段（chat_id 是 None）。'},{at:'except chat_service.ChatError as e:',to:')',text:'业务错误（消息为空、次数用完、AI 出错）就留在当前页面显示原因，状态码用错误自带的。'},{at:'return RedirectResponse(f"/questions/{qid}/chat", status_code=303)',text:'成功后重定向回对话页面，由那边重新查出最新的消息来显示；这样用户刷新页面只是重新打开页面，不会把问题再提交一次。'},{at:'<!-- templates/chat.html -->',to:'</html>',text:'对话页面的模板：循环显示每条消息，有错误就显示错误，最下面是提问的表单。模板默认会把内容转义，AI 的回答里有 HTML 标签也只当普通文字显示。'},{at:'<!-- templates/question.html：在 </article> 前面加一个链接 -->',text:'题目详情页上加一个进入对话页面的链接。',to:'<p><a href="/questions/{{ question.id }}/chat">问 AI 老师</a></p>'}]}},'template-go':{body:'模板渲染的做法：给每道题加一个单独的对话页面 /questions/题目编号/chat。这一张卡片的 Go 版本暂时只有步骤，没有代码骨架，请按下面的步骤自己写；写法和其他语言的模板版完全一样，卡在哪里可以点右下角问 AI 老师要提示。\n一、在 internal/handler/pages_chat.go 里写一个函数 latestChat：取我的对话列表，找出第一段 questionId 等于这道题的（列表已经按最近提问排好序），返回它的编号和全部消息；没有就返回“没有对话”；\n二、GET /questions/{id}/chat：没登录跳到 /login；题目不存在返回 404；否则渲染 chat 模板，传入题目和 latestChat 取出的消息；\n三、POST /questions/{id}/chat：同样先检查登录和题目，再用 latestChat 找到当前对话，调用任务二的 send（新对话传题目编号，追问传对话编号）；成功后用 303 重定向回 /questions/{id}/chat，这样刷新页面不会重复提问；业务错误（400、429、502、503）就用这个状态码重新渲染 chat 模板，把错误信息显示出来；\n四、新建 web/templates/chat.html：循环显示每条消息（“我：”或“AI 老师：”加内容），有错误就显示错误，最下面是一个 POST 到 /questions/{id}/chat 的表单，文本框的 name 是 message；\n五、在题目详情页的模板里加一个链接：<a href="/questions/{id}/chat">问 AI 老师</a>。',practice:{steps:['按上面五步写好页面路由和模板。','登录后打开一道题，点“问 AI 老师”，问一个问题，再追问一句；刷新页面，确认两轮对话都还在；提交空消息，确认页面上显示“消息不能为空”。'],expect:'页面上依次显示：我：…… / AI 老师：…… / 我：…… / AI 老师：……'}},'template-java':{body:'模板渲染的做法：给每道题加一个单独的对话页面 /questions/题目编号/chat。这一张卡片的 Java 版本暂时只有步骤，没有代码骨架，请按下面的步骤自己写；写法和其他语言的模板版完全一样，卡在哪里可以点右下角问 AI 老师要提示。\n一、在 controller/ChatPageController.java 里写一个函数 latestChat：取我的对话列表，找出第一段 questionId 等于这道题的（列表已经按最近提问排好序），返回它的编号和全部消息；没有就返回“没有对话”；\n二、GET /questions/{id}/chat：没登录跳到 /login；题目不存在返回 404；否则渲染 chat 模板，传入题目和 latestChat 取出的消息；\n三、POST /questions/{id}/chat：同样先检查登录和题目，再用 latestChat 找到当前对话，调用任务二的 send（新对话传题目编号，追问传对话编号）；成功后用 303 重定向回 /questions/{id}/chat，这样刷新页面不会重复提问；业务错误（400、429、502、503）就用这个状态码重新渲染 chat 模板，把错误信息显示出来；\n四、新建 src/main/resources/templates/chat.html：循环显示每条消息（“我：”或“AI 老师：”加内容），有错误就显示错误，最下面是一个 POST 到 /questions/{id}/chat 的表单，文本框的 name 是 message；\n五、在题目详情页的模板里加一个链接：<a href="/questions/{id}/chat">问 AI 老师</a>。',practice:{steps:['按上面五步写好页面路由和模板。','登录后打开一道题，点“问 AI 老师”，问一个问题，再追问一句；刷新页面，确认两轮对话都还在；提交空消息，确认页面上显示“消息不能为空”。'],expect:'页面上依次显示：我：…… / AI 老师：…… / 我：…… / AI 老师：……'}}}},
  {title:'验收：多轮对话、历史和次数限制',body:'验收脚本和第 14 关一样，会在本机 8090 端口启动一个“假的大模型服务”。这次它会数一数每次请求里有几条消息，并把最后一句话原样带回来：这样就能检查你的后端有没有把之前的对话一起发过去。\n运行验收前，除了第 14 关的三个环境变量，还要把每日次数设成 5（脚本要把次数用完，检查 429）：\nAI_BASE_URL=http://127.0.0.1:8090\nAI_API_KEY=test-key\nAI_MODEL=test-model\nCHAT_DAILY_LIMIT=5\n脚本每次都会注册两个新用户，所以可以反复运行。',practice:{steps:['停掉后端，设置好四个环境变量再启动。PowerShell：$env:AI_BASE_URL="http://127.0.0.1:8090"; $env:AI_API_KEY="test-key"; $env:AI_MODEL="test-model"; $env:CHAT_DAILY_LIMIT="5"；Mac 把这四项写在启动命令前面。','把下面的脚本保存为 checks/check_l15.py，运行 python checks/check_l15.py，直到全部 ✓。','在页面上打开一道题，问 AI 老师一个问题，再追问一句“能举个例子吗”，刷新页面后看看对话还在不在。','全部通过后提交：git add . 然后 git commit -m "第 15 关：AI 老师对话"。'],expect:'✓ 健康检查仍然正常\n✓ 没登录时不能提问\n✓ 新对话返回 201、对话编号、回答和剩余次数\n✓ 第一次提问带上了题目和系统提示词\n✓ 追问时把之前的对话一起发给了模型\n✓ 对话列表和详情按顺序保存了 4 条消息\n✓ 看不到也不能接着问别人的对话\n✓ 空消息和超长消息返回 400\n✓ AI 出错返回 502，不扣次数也不保存\n✓ 次数用完返回 429\n✓ 删除对话后再查返回 404\n\n通过 11 / 11'},code:`import http.cookiejar
import json
import random
import sys
import threading
import urllib.error
import urllib.request
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

BASE = sys.argv[1] if len(sys.argv) > 1 else "http://localhost:8080"
received = []
passed = 0


class FakeLLM(BaseHTTPRequestHandler):
    """假的大模型服务：回答里带上收到了几条消息，以及最后一句话"""

    def read_body(self):
        if self.headers.get("Content-Length"):
            return self.rfile.read(int(self.headers["Content-Length"]))
        data = b""
        while True:
            size = int(self.rfile.readline().strip(), 16)
            if size == 0:
                self.rfile.readline()
                return data
            data += self.rfile.read(size)
            self.rfile.readline()

    def do_POST(self):
        body = json.loads(self.read_body())
        messages = body.get("messages", [])
        received.append({"auth": self.headers.get("Authorization"), "messages": messages})
        last = messages[-1].get("content", "") if messages else ""
        if "服务出错" in last:
            return self.reply(500, {"error": {"message": "server error"}})
        content = f"收到 {len(messages)} 条消息：{last}"
        self.reply(200, {"choices": [{"message": {"role": "assistant", "content": content}}]})

    def reply(self, status, data):
        raw = json.dumps(data, ensure_ascii=False).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(raw)))
        self.end_headers()
        self.wfile.write(raw)

    def log_message(self, *args):
        pass


threading.Thread(target=ThreadingHTTPServer(("127.0.0.1", 8090), FakeLLM).serve_forever, daemon=True).start()


def check(name, ok):
    global passed
    print(("✓ " if ok else "✗ ") + name)
    passed += bool(ok)


def new_client():
    opener = urllib.request.build_opener(urllib.request.HTTPCookieProcessor(http.cookiejar.CookieJar()))

    def call(method, path, body=None):
        data = json.dumps(body).encode("utf-8") if body is not None else None
        req = urllib.request.Request(BASE + path, data=data, method=method, headers={"Content-Type": "application/json"})
        try:
            with opener.open(req, timeout=40) as r:
                status, raw = r.status, r.read()
        except urllib.error.HTTPError as e:
            status, raw = e.code, e.read()
        except OSError as e:
            sys.exit(f"连不上 {BASE}，服务启动了吗？（{e}）")
        try:
            return status, json.loads(raw.decode("utf-8") or "null")
        except ValueError:
            return status, None

    return call


def obj(value):
    return value if isinstance(value, dict) else {}


anon, me, other = new_client(), new_client(), new_client()
suffix = random.randint(100000, 999999)
for client, name in ((me, "chat_a"), (other, "chat_b")):
    user = {"username": f"{name}{suffix}", "password": "secret123"}
    client("POST", "/api/register", user)
    client("POST", "/api/login", user)

status, data = anon("GET", "/api/health")
check("健康检查仍然正常", status == 200 and obj(data).get("status") == "ok")

status, _ = anon("POST", "/api/chats", {"message": "你好"})
check("没登录时不能提问", status == 401)

status, data = me("POST", "/api/chats", {"questionId": 1, "message": "defer 是什么时候执行的？"})
first = obj(data)
chat_id = first.get("chatId")
check("新对话返回 201、对话编号、回答和剩余次数",
      status == 201 and isinstance(chat_id, int) and "defer 是什么时候执行的" in str(first.get("reply")) and first.get("remaining") == 4)

sent = received[-1]["messages"] if received else []
status, question = anon("GET", "/api/questions/1")
title = obj(question).get("title", "？")
check("第一次提问带上了题目和系统提示词",
      len(sent) == 2 and sent[0].get("role") == "system" and title in sent[0].get("content", "")
      and sent[1] == {"role": "user", "content": "defer 是什么时候执行的？"} and received[-1]["auth"] == "Bearer test-key")

status, data = me("POST", f"/api/chats/{chat_id}/messages", {"message": "能举个例子吗"})
sent = received[-1]["messages"] if received else []
roles = [m.get("role") for m in sent]
check("追问时把之前的对话一起发给了模型",
      status == 200 and roles == ["system", "user", "assistant", "user"] and obj(data).get("reply") == "收到 4 条消息：能举个例子吗"
      and obj(data).get("remaining") == 3)

status, chats = me("GET", "/api/chats")
mine = [c for c in chats if obj(c).get("id") == chat_id] if isinstance(chats, list) else []
status2, detail = me("GET", f"/api/chats/{chat_id}")
messages = obj(detail).get("messages", [])
check("对话列表和详情按顺序保存了 4 条消息",
      status == 200 and len(mine) == 1 and mine[0].get("messages") == 4 and mine[0].get("questionId") == 1
      and status2 == 200 and [m.get("role") for m in messages] == ["user", "assistant", "user", "assistant"]
      and messages[2].get("content") == "能举个例子吗")

status, _ = other("GET", f"/api/chats/{chat_id}")
status2, _ = other("POST", f"/api/chats/{chat_id}/messages", {"message": "我也想问"})
status3, chats = other("GET", "/api/chats")
check("看不到也不能接着问别人的对话", status == 404 and status2 == 404 and chats == [])

status, _ = me("POST", "/api/chats", {"message": "   "})
status2, _ = me("POST", f"/api/chats/{chat_id}/messages", {"message": "长" * 1001})
check("空消息和超长消息返回 400", status == 400 and status2 == 400)

status, _ = me("POST", f"/api/chats/{chat_id}/messages", {"message": "服务出错"})
status2, detail = me("GET", f"/api/chats/{chat_id}")
status3, data = me("POST", f"/api/chats/{chat_id}/messages", {"message": "还在吗"})
check("AI 出错返回 502，不扣次数也不保存",
      status == 502 and len(obj(detail).get("messages", [])) == 4 and status3 == 200 and obj(data).get("remaining") == 2)

me("POST", "/api/chats", {"message": "第四次"})
status, data = me("POST", "/api/chats", {"message": "第五次"})
status2, _ = me("POST", "/api/chats", {"message": "第六次"})
check("次数用完返回 429", status == 201 and obj(data).get("remaining") == 0 and status2 == 429)

status, _ = me("DELETE", f"/api/chats/{chat_id}")
status2, _ = me("GET", f"/api/chats/{chat_id}")
status3, _ = other("DELETE", f"/api/chats/{chat_id}")
check("删除对话后再查返回 404", status == 204 and status2 == 404 and status3 == 404)

print(f"\\n通过 {passed} / 11")`,explain:[{at:'import http.cookiejar',to:'from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer',text:'用到的都是 Python 自带的模块。'},{at:'BASE = sys.argv[1]',to:'passed = 0',text:'后端地址，received 记下假服务收到的每一次请求，passed 是通过的项数。'},{at:'class FakeLLM(BaseHTTPRequestHandler):',to:'return data',text:'假的大模型服务，读请求正文的写法和第 14 关一样。'},{at:'data += self.rfile.read(size)',to:'self.rfile.readline()',text:'读完一块内容后，跳过块后面的换行，再读下一块。'},{at:'def do_POST(self):',to:'last = messages[-1].get("content", "") if messages else ""',text:'收到请求后，记下请求头里的密钥和整个 messages 数组，取出最后一条消息的内容。'},{at:'if "服务出错" in last:',to:'return self.reply(500',text:'最后一句话里有“服务出错”这个暗号时，故意返回 500，用来检查你的后端怎么处理失败。'},{at:'content = f"收到 {len(messages)} 条消息：{last}"',to:'self.reply(200,',text:'正常情况：回答里写明收到了几条消息和最后一句话。追问时如果你只发了最新一句，条数就对不上。'},{at:'def reply(self, status, data):',to:'pass',text:'返回 JSON，并关掉默认的访问日志。'},{at:'threading.Thread(',text:'在后台线程里启动假服务，监听 8090 端口。'},{at:'def check(name, ok):',to:'passed += bool(ok)',text:'打印一项检查的结果并计数。'},{at:'def new_client():',to:'return call',text:'每个“客户端”有自己的 Cookie 罐，相当于一个独立的浏览器。返回的 call 函数负责发请求，并把结果整理成“状态码 + 解析后的 JSON”。'},{at:'def obj(value):',to:'return value if isinstance(value, dict) else {}',text:'接口没按约定返回对象时，换成空字典，后面取字段就不会报错。'},{at:'anon, me, other = new_client(), new_client(), new_client()',to:'client("POST", "/api/login", user)',text:'三个客户端：没登录的、我、另一个用户。用随机数拼出两个新用户名，分别注册并登录。'},{at:'status, data = anon("GET", "/api/health")',to:'check("没登录时不能提问", status == 401)',text:'健康检查还正常；没登录提问要返回 401。'},{at:'status, data = me("POST", "/api/chats", {"questionId": 1',to:'and first.get("remaining") == 4)',text:'针对第 1 题开一段新对话：状态码 201，有整数的 chatId，回答里带着问题原文，每日 5 次用掉 1 次还剩 4 次。'},{at:'sent = received[-1]["messages"] if received else []',to:'and received[-1]["auth"] == "Bearer test-key")',text:'看假服务收到了什么：应该正好两条消息，第一条是系统提示词而且里面有第 1 题的题目，第二条是用户的问题；请求头带着密钥。'},{at:'status, data = me("POST", f"/api/chats/{chat_id}/messages", {"message": "能举个例子吗"})',to:'and obj(data).get("remaining") == 3)',text:'追问一句。这次假服务应该收到 4 条消息：系统提示词、第一问、第一次的回答、这次的追问。这是这一关最关键的一项。'},{at:'status, chats = me("GET", "/api/chats")',to:'and messages[2].get("content") == "能举个例子吗")',text:'对话列表里有这段对话，记着 4 条消息和关联的题目；详情里 4 条消息按“问、答、问、答”的顺序排列。'},{at:'status, _ = other("GET", f"/api/chats/{chat_id}")',to:'check("看不到也不能接着问别人的对话"',text:'另一个用户查看、追问这段对话都返回 404（不是 403，不透露它存在），他自己的列表是空的。'},{at:'status, _ = me("POST", "/api/chats", {"message": "   "})',to:'check("空消息和超长消息返回 400"',text:'只有空格的消息、超过 1000 个字的消息都返回 400。'},{at:'status, _ = me("POST", f"/api/chats/{chat_id}/messages", {"message": "服务出错"})',to:'and status3 == 200 and obj(data).get("remaining") == 2)',text:'让假服务返回 500：你的后端应该返回 502，而且这句话不能存进对话（还是 4 条），次数也不能扣（下一次成功提问后剩 2 次，而不是 1 次）。'},{at:'me("POST", "/api/chats", {"message": "第四次"})',to:'check("次数用完返回 429"',text:'再问两次把 5 次用完，第 6 次返回 429。'},{at:'status, _ = me("DELETE", f"/api/chats/{chat_id}")',to:'check("删除对话后再查返回 404"',text:'删除自己的对话返回 204，之后再查是 404；别人来删也是 404。'},{at:'print(f"\\n通过 {passed} / 11")',text:'打印总结。'}]},
  {title:'这一关学到了什么',body:'一、模型本身不记得对话，多轮对话是后端每次把历史一起发过去；系统提示词放在最前面，历史按先后顺序，最后是新问题；\n二、历史越长越贵，只带最近几轮（这里是 10 条消息）；\n三、对话、消息、次数分三张表存；次数单独记，删除对话不会把次数“删回来”；\n四、“检查有没有超限”和“加一”要在一条 SQL 里完成（INSERT … ON CONFLICT … WHERE count < 上限 RETURNING count），否则并发请求会超限；\n五、先占用次数再调用模型；调用失败要退回次数，并且不保存这句话；\n六、对话不是自己的一律返回 404，不透露它是否存在；\n七、模板渲染的页面提交后重定向（303），刷新页面不会重复提问。\n下一关给 AI 加上流式输出、思考过程拆分与超时兜底，告别干等几十秒。'}
 ],quiz:[
 {id:'pj-chat-1',q:'追问时 AI 能“记得”之前聊过什么，靠的是什么？',options:['后端每次把之前的对话一起发给模型','模型会自动记住每个用户的聊天','模型服务按密钥保存了对话记录','浏览器的 Cookie 里存着对话'],why:['','模型每次请求都是独立的，参数不会因为聊天而改变。','这一关用的接口不保存对话，每次请求只看 messages。','Cookie 里只有会话令牌，对话存在我们的数据库里。'],answer:0,explain:'模型本身不记得任何对话。“多轮对话”是后端把之前的一问一答按顺序放进 messages，再加上新问题一起发过去。'},
 {id:'pj-chat-2',q:'发给模型的 messages 应该按什么顺序排列？',options:['系统提示词 → 历史消息（按先后）→ 新问题','新问题 → 历史消息 → 系统提示词','历史消息（最新的在前）→ 新问题','只发新问题，系统提示词放在请求头里'],why:['','模型从前往后读，新问题要放在最后。','历史要按说话的先后顺序，否则对话就乱了。','系统提示词是 messages 里 role 为 system 的消息，不放在请求头里。'],answer:0,explain:'系统提示词放最前面设定角色和规则，然后是按时间顺序的历史，最后是这次的问题。'},
 {id:'pj-chat-3',type:'judge',q:'追问时应该把这段对话的全部历史消息都发给模型，带得越多回答越准。',answer:false,explain:'错误。大模型按 token 收费，历史越长越贵也越慢。这一关只带最近 10 条消息（5 轮问答），对答疑来说一般够用。'},
 {id:'pj-chat-4',q:'为什么每日次数要单独记在 chat_usage 表里，而不是数一数今天存了几条消息？',options:['删掉对话后统计消息数会失真','SQL 语句很难按天统计消息条数','消息表里没有记录发送时间戳','单独建计数表导致查询超时失真'],why:['','用 COUNT 和日期条件就能数出来，问题不在写不出。','chat_messages 有 created_at。','单独一张表按主键查，反而更快。'],answer:0,explain:'如果按消息数算次数，用户问完把对话删掉，次数就回来了，限制形同虚设。单独记次数，删除对话不影响它。'},
 {id:'pj-chat-5',q:'“先查今天问了几次，没到上限再加一”这种写法，在什么情况下会超限？',options:['同一个人的两个请求同时到达','用户在晚上 12 点前后提问','上限设置成了 1','用户换了一台电脑提问'],why:['','日期变了就是新的一天，各算各的，不会超限。','上限是 1 时同样只有并发才会出问题。','换电脑不影响服务器上的次数记录。'],answer:0,explain:'两个请求都先查到“还差一次”，再各自加一，结果超过上限。解决办法是让检查和加一在一条 SQL 里完成。'},
 {id:'pj-chat-6',type:'multi',q:'关于 INSERT … ON CONFLICT (user_id, day) DO UPDATE SET count = count + 1 WHERE count < ? RETURNING count，下面说法正确的有？（多选）',options:['今天还没有记录时，插入一行 count = 1','已经有记录且没到上限时，count 加一','到了上限时一行都不改，拿不到返回值','到了上限时数据库会报错，程序要捕获这个错误'],why:['','','','不会报错，只是一行都不改；程序看到“没有返回值”就知道用完了。'],answers:[0,1,2],explain:'ON CONFLICT 处理“今天已经有记录”的情况，WHERE 只在没到上限时才改，RETURNING 把改完的次数拿回来。整条语句一次完成，并发请求插不进来。'},
 {id:'pj-chat-7',q:'今天的提问次数用完了，接口应该返回哪个状态码？',options:['429','403','400','503'],why:['','403 表示没有权限，这里用户有权限，只是太频繁了。','400 表示请求本身不对，这里请求是对的。','503 表示服务暂时不可用，这里服务是好的。'],answer:0,explain:'429 Too Many Requests 的意思就是“请求太多了”，用于限流和配额用完。'},
 {id:'pj-chat-8',type:'judge',q:'大模型调用失败时，应该把刚才占用的一次提问次数退回去。',answer:true,explain:'正确。失败不是用户的错，不能让用户为失败的请求买单。所以先占用次数、再调用模型，失败时退回。'},
 {id:'pj-chat-9',q:'为什么要“先占用次数，再调用模型”，而不是“调用成功后再记一次”？',options:['并发请求会在记账前全部通过检查','成功后再记账会导致模型重复调用','先占用次数能让模型生成速度变快','成功后再记账很难按用户汇总统计'],why:['','两种写法调用模型的次数一样。','顺序不影响模型的速度。','成功后再记也能统计，只是限制不住并发。'],answer:0,explain:'如果成功后才记次数，同一个人同时发 100 个请求，在任何一个记下之前它们都会通过检查，限制就失效了。'},
 {id:'pj-chat-10',type:'judge',q:'AI 出错返回 502 时，用户这次的提问也要存进对话里，方便以后查看。',answer:false,explain:'错误。只有成功拿到回答才保存一问一答。如果把没有回答的问题存进去，下次追问时就会把一句没有回答的话发给模型，对话就乱了。'},
 {id:'pj-chat-11',q:'用户请求查看别人的对话（GET /api/chats/别人的编号），应该返回什么？',options:['404，当作不存在','403，提示没有权限','200，但消息列表为空','401，要求重新登录'],why:['','403 等于告诉对方“这个编号的对话存在”。','返回 200 会让人以为这段对话就是空的。','用户已经登录了，401 不对。'],answer:0,explain:'按“对话编号 + 用户编号”一起查，不是自己的就查不到，和不存在一样返回 404，不透露别人有没有这段对话。'},
 {id:'pj-chat-12',type:'fill',q:'调用大模型的 messages 里，AI 自己说过的话 role 是 ＿＿＿＿＿＿＿＿＿。',accepted:['assistant'],explain:'assistant。system 是系统提示词，user 是用户说的话，assistant 是模型的回答。数据库里也用同样的名字，取出来就能直接放进 messages。'},
 {id:'pj-chat-13',q:'保存一问一答时，为什么要把几条写入放在同一个事务里？',options:['避免出现“存了问题没存回答”的半截数据','让写入速度变快一倍','事务能自动生成对话编号','不放在事务里 SQLite 会拒绝写入'],why:['','事务的主要目的不是速度。','编号是自增主键生成的，和事务无关。','SQLite 单条写入不需要显式事务。'],answer:0,explain:'事务保证里面的写入要么全部成功、要么全部不生效。中途出错时，不会留下只有问题没有回答的对话。'},
 {id:'pj-chat-14',type:'multi',q:'这一关的系统提示词里放了哪些内容？（多选）',options:['AI 老师的角色设定','学生正在看的题目','这道题的参考答案','学生这次的提问'],why:['','','','学生的提问放在最后一条 user 消息里，不放进系统提示词。'],answers:[0,1,2],explain:'角色设定、题目和参考答案都来自我们自己，放在 system 消息里；学生说的话放在 user 消息里，和规则分开。'},
 {id:'pj-chat-15',type:'judge',q:'模板渲染的对话页面提交问题后直接渲染页面就好，用不着重定向。',answer:false,explain:'错误。直接渲染的话，用户一刷新浏览器就会重新提交表单，再问一次、再扣一次次数。提交成功后用 303 重定向回对话页面，刷新只是重新打开页面。'},
 {id:'pj-chat-go-1',stack:'go',q:'Go 里 Chat 结构体的 QuestionID 字段为什么用 *int 而不是 int？',options:['使用整型指针比普通整型更省内存','对话可不关联题目，nil 对应 NULL','Go 编码 JSON 时无法处理普通整型','普通 int 类型长度不够存放题目 ID'],why:['一个指针并不比 int 省内存。','','JSON 可以直接序列化 int。','int 足够存题目编号。'],answer:1,explain:'int 的零值是 0，分不清“没关联题目”和“关联了 0 号题”。*int 为 nil 时表示 NULL，转成 JSON 是 null。'},
 {id:'pj-chat-java-1',stack:'java',q:'Java 里 takeQuota 为什么用 jdbc.queryForList 来执行一条 INSERT 语句？',options:['使用 queryForList 执行效率更高','使用 update 方法无法执行 INSERT','语句带 RETURNING 会像查询返回行','使用 queryForList 可以跳过事务锁'],why:['速度不是原因。','update 可以执行 INSERT，但拿不到 RETURNING 的结果。','','和事务无关。'],answer:2,explain:'RETURNING count 让这条写入语句返回一行结果。用 queryForList 拿到它；到了上限时一行都没改，列表是空的。'},
 {id:'pj-chat-node-1',stack:'node',q:'Node.js 里 saveTurn 用 db.transaction(…) 包起来，有什么作用？',options:['自动把同步代码转成异步函数','自动为每条消息加上创建时间','防止各类参数拼接带来的注入','几条写入放进事务中同成同败'],why:['better-sqlite3 的事务函数是同步的。','时间由列的默认值 CURRENT_TIMESTAMP 填写。','防注入靠的是参数化查询。',''],answer:3,explain:'db.transaction 返回一个新函数，调用它时里面的写入在一个事务中执行，中途出错会全部撤销。'},
 {id:'pj-chat-python-1',stack:'python',q:'Python 里 history = store.list_messages(chat_id)[-HISTORY:] 取到的是什么？',options:['按顺序取出的前 10 条消息','最近 10 条，不够时全取','跳过前 10 条之后的剩余消息','倒数第 10 位这一条单条消息'],why:['[:10] 才是前 10 条。','','[10:] 才是第 10 条以后。','[-10] 才是单独一条。'],answer:1,explain:'切片 [-10:] 从倒数第 10 个取到最后；列表不够 10 个元素时不会报错，直接取全部。'},
]};
